self.onInit = function () {
  const ctx = self.ctx;

  // ===== 2 BASE_URL + 1 default =====
  // sửa 3 URL này theo môi trường của bạn
  const BASE_URL_TABLET    = "https://visiflow-dev.m-tech.com.vn/webrtc2221/"; // Edge Device
  const BASE_URL_EDGE  = "https://skds1x9p-8007.asse.devtunnels.ms/";      // Tablet Device
  const BASE_URL_DEFAULT = "https://skds1x9p-8007.asse.devtunnels.ms/";      // fallback

  // Profile cho multi-account (map với key trong tb_profiles.json)
  const PROFILE_KEY = "default"; // hoặc "tenant_a", "tenant_b", ... tuỳ dashboard

  const IFRAME_SANDBOX = ""; // "allow-scripts allow-same-origin" nếu cần

  // ==== DOM ====
  const root = ctx.$container[0];
  root.innerHTML = "";
  Object.assign(root.style, {
    position: "relative",
    height: "100%",
    width: "100%",
    overflow: "hidden",
    background: "#000"
  });

  const iframe = document.createElement("iframe");
  Object.assign(iframe.style, {
    border: "0",
    width: "100%",
    height: "100%",
    display: "block"
  });

  if (IFRAME_SANDBOX && IFRAME_SANDBOX.trim()) {
    iframe.setAttribute("sandbox", IFRAME_SANDBOX.trim());
  }

  // URL hiện tại (khởi tạo = default để luôn có cái chạy được)
  let currentBaseUrl = BASE_URL_DEFAULT;
  iframe.src = currentBaseUrl;
  root.appendChild(iframe);

  // ==== LẤY NGÔN NGỮ CURRENT CỦA THINGSBOARD ====
  function detectTbLang() {
    const langAttr = (document.documentElement.getAttribute("lang") || "").toLowerCase();
    const ls =
      (window.localStorage.getItem("tbLang") ||
       window.localStorage.getItem("language") ||
       "").toLowerCase();
    const nav = (navigator.language || navigator.userLanguage || "").toLowerCase();

    let raw = langAttr || ls || nav || "en";
    if (raw.startsWith("ja")) return "ja";
    if (raw.startsWith("en")) return "en";
    return "en";
  }

  // ==== LẤY DEVICE TỪ DATASOURCE ====
  function getDeviceFromDatasource() {
    const sub = ctx.defaultSubscription;
    if (!sub || !sub.datasources || !sub.datasources.length) {
      return null;
    }

    const ds = sub.datasources[0];

    let entityId = null;
    let entityType = null;
    let entityName = null;

    if (ds.entityId) {
      if (typeof ds.entityId === "string") {
        entityId = ds.entityId;
      } else if (typeof ds.entityId === "object") {
        entityId   = ds.entityId.id || ds.entityId.entityId || null;
        entityType = ds.entityId.entityType || null;
      }
    }

    if (!entityId && ds.entity && typeof ds.entity === "object") {
      entityId   = ds.entity.id   || entityId;
      entityType = ds.entity.type || entityType;
    }

    entityType = entityType || ds.entityType || "DEVICE";
    entityName = ds.entityName || ds.name || (ds.entity && ds.entity.name) || entityId;

    if (!entityId) {
      return null;
    }

    return {
      id: entityId,
      name: entityName || entityId,
      type: entityType
    };
  }

  // ===== CHỌN BASE_URL THEO deviceLabel =====
  let lastLabel = null;  // để tránh đổi URL liên tục khi label không đổi

  function pickBaseUrl(label) {
    if (label === "Edge Device") {
      return BASE_URL_EDGE;
    }
    if (label === "Tablet Device") {
      return BASE_URL_TABLET;
    }
    return BASE_URL_DEFAULT;
  }

  function updateBaseUrlByDeviceLabel(dev) {
    if (!dev || dev.type !== "DEVICE") {
      // alias không phải device → cứ để default
      return;
    }

    const url =
      `/api/plugins/telemetry/DEVICE/${dev.id}` +
      `/values/attributes/SERVER_SCOPE?keys=deviceLabel`;

    ctx.http.get(url).subscribe(
      function success(resp) {
        const data = resp.data || resp;
        let label = null;

        if (Array.isArray(data)) {
          data.forEach(it => {
            if (it && it.key === "deviceLabel") {
              label = it.value;
            }
          });
        }

        // nếu không có label → dùng default, nhưng không cần spam reload
        if (!label && lastLabel === null) {
          lastLabel = null;
          currentBaseUrl = BASE_URL_DEFAULT;
          iframe.src = currentBaseUrl;
          return;
        }

        if (label === lastLabel) {
          return; // không đổi
        }
        lastLabel = label;

        const newUrl = pickBaseUrl(label);
        if (newUrl && newUrl !== currentBaseUrl) {
          currentBaseUrl = newUrl;
          iframe.src = currentBaseUrl;
          // console.log("deviceLabel =", label, "→ BASE_URL =", currentBaseUrl);
        }
      },
      function error(err) {
        // lỗi (404, v.v.) thì giữ nguyên currentBaseUrl, không làm gì
        // console.warn("read deviceLabel error:", err);
      }
    );
  }

  // ==== GỬI DEVICE + LANG + PROFILE VÀO IFRAME ====
  function sendContextToIframe() {
    const dev = getDeviceFromDatasource();
    const lang = detectTbLang();

    // mỗi lần gửi context, cố gắng update base URL (nếu device có label)
    if (dev) {
      updateBaseUrlByDeviceLabel(dev);
    }

    const payload = {
      type: "TB_DEVICE_SELECTED",
      lang,
      profile: PROFILE_KEY
    };

    if (dev) {
      payload.deviceId = dev.id;
      payload.deviceName = dev.name;
    }

    try {
      iframe.contentWindow.postMessage(payload, "*");
    } catch (err) {
      // console.error("[Annotator widget] postMessage lỗi:", err);
    }
  }

  // Gửi device vài lần lúc đầu để iframe chắc chắn nhận
  let retryCount = 0;
  function autoSendContext() {
    sendContextToIframe();
    retryCount++;
    if (retryCount < 10) {
      setTimeout(autoSendContext, 200);
    }
  }
  autoSendContext();

  // ==== LIFECYCLE ====
  self.onDataUpdated = function () {
    // khi đổi device / alias / data → gửi lại context
    sendContextToIframe();
  };

  self.onResize = function () {};

  self.onDestroy = function () {};

  // Khi iframe load xong lần đầu → gửi thêm 1 lần nữa
  iframe.addEventListener("load", function () {
    setTimeout(sendContextToIframe, 200);
  });
};

