descriptor.controllerScript:
self.onInit = function () {
  self.ctx.ngZone.run(function () {
    init();
    self.ctx.detectChanges();
  });
};

self.onDataUpdated = function () {
  self.ctx.ngZone.run(function () {
    refreshFromTelemetry();
    self.ctx.detectChanges();
  });
};

function init() {
  // ===== UI text =====
  self.ctx.$scope.title = self.ctx.settings.title || 'Select Cam';
  self.ctx.$scope.showTitle = !!(self.ctx.$scope.title && self.ctx.$scope.title.length);

  self.ctx.$scope.dropdownLabel = self.ctx.settings.dropdownLabel || 'Chọn Camera';
  self.ctx.$scope.emptyHint = self.ctx.settings.emptyHint || 'Không tìm thấy camera';
  self.ctx.$scope.error = '';

  // ===== Settings =====
  // Nếu bạn không tạo settings telemetryKey thì mặc định dùng pass_total
  self.telemetryKey = self.ctx.settings.telemetryKey || 'pass_total';

  // Shared attribute key cần update
  self.sharedKey = 'cam';

  // ===== Services =====
  self.attributeService = self.ctx.$scope.$injector.get(
    self.ctx.servicesMap.get('attributeService')
  );

  // ===== State =====
  self.ctx.$scope.camOptions = [];
  self.ctx.$scope.selectedCam = null;

  // ===== Events =====
  self.ctx.$scope.onCamChange = function (camValue) {
      self.ctx.$scope.selectedCam = camValue; 
      self.ctx.detectChanges();
    saveSharedCam(camValue);
  };

  // First load
  refreshFromTelemetry();
}

/** Lấy last telemetry value cho telemetryKey từ self.ctx.data */
function getLatestTelemetryValueFromCtxData(key) {
  const dataArr = self.ctx.data || [];
  if (!Array.isArray(dataArr) || !dataArr.length) return null;

  // ctx.data dạng: [{dataKey:{name:'pass_total'}, data:[[ts,val],...]}]
  const item = dataArr.find(x => x && x.dataKey && x.dataKey.name === key);
  if (!item || !item.data || !item.data.length) return null;

  const last = item.data[item.data.length - 1];
  return last ? last[1] : null;
}

/** Parse raw JSON -> ["CAM2","CAM10",...] */
// function buildCamOptions(raw) {
//   if (raw == null) return [];

//   let obj = raw;

//   // telemetry thường là string JSON
//   if (typeof raw === 'string') {
//     try {
//       obj = JSON.parse(raw);
//     } catch (e) {
//       return [];
//     }
//   }

//   if (!obj || typeof obj !== 'object') return [];

//   const keys = Object.keys(obj);

//   // sort numeric: 2,10,11...
//   keys.sort((a, b) => (parseInt(a, 10) || 0) - (parseInt(b, 10) || 0));

//   return keys.map(k => `CAM${k}`);
// }
function buildCamOptions(raw) {
  if (raw == null) return [];
  let s = raw;

  // ép về string nếu cần
  if (typeof s !== 'string') s = JSON.stringify(s);

  // gỡ bọc quote nếu có:  "\"{...}\""
  s = s.trim();
  if ((s.startsWith('"') && s.endsWith('"')) || (s.startsWith("'") && s.endsWith("'"))) {
    s = s.slice(1, -1);
  }

  // unescape nếu có
  s = s.replace(/\\"/g, '"');

  let obj;
  try { obj = JSON.parse(s); } catch (e) { return []; }

  const keys = Object.keys(obj).sort((a,b)=> (parseInt(a,10)||0)-(parseInt(b,10)||0));
  return keys.map(k => `CAM${k}`);
}


/** Refresh dropdown options từ telemetry */
function refreshFromTelemetry() {
     const raw = getLatestTelemetryValueFromCtxData(self.telemetryKey);
  self.ctx.$scope.error = 'telemetryKey=' + self.telemetryKey + ', raw=' + (raw ? 'OK' : 'NULL');  // debug
  try {
    const raw = getLatestTelemetryValueFromCtxData(self.telemetryKey);
    const options = buildCamOptions(raw);

    self.ctx.$scope.camOptions = options;

    // nếu selectedCam không còn trong options -> reset
    if (self.ctx.$scope.selectedCam && !options.includes(self.ctx.$scope.selectedCam)) {
      self.ctx.$scope.selectedCam = null;
    }

    // nếu chưa chọn gì mà có options -> auto chọn option đầu
    if (!self.ctx.$scope.selectedCam && options.length) {
      self.ctx.$scope.selectedCam = options[0];
      // (tuỳ bạn) auto save luôn khi auto chọn:
      // saveSharedCam(self.ctx.$scope.selectedCam);
    }

    self.ctx.$scope.error = '';
  } catch (e) {
    self.ctx.$scope.camOptions = [];
    self.ctx.$scope.selectedCam = null;
    self.ctx.$scope.error = 'Parse/refresh error';
  }
}

/** Save shared attribute: cam = "CAMx" */
function saveSharedCam(camValue) {
  if (!camValue) return;

  const deviceId = self.ctx.defaultSubscription && self.ctx.defaultSubscription.targetDeviceId;
  if (!deviceId) {
    self.ctx.$scope.error = 'No targetDeviceId in subscription';
    self.ctx.detectChanges();
    return;
  }

  const entityId = {
    entityType: "DEVICE",
    id: deviceId
  };

  const attributes = [{
    key: self.sharedKey,
    value: camValue
  }];

  self.attributeService.saveEntityAttributes(entityId, 'SHARED_SCOPE', attributes).subscribe(
    function () {
      self.ctx.$scope.error = '';
      self.ctx.detectChanges();
    },
    function (rejection) {
      self.ctx.$scope.error = rejection.status + ': ' + rejection.statusText;
      self.ctx.detectChanges();
    }
  );
}

