descriptor.controllerScript:
self.onInit = function () {
  self.ctx.ngZone.run(function () {
    init();
    self.ctx.detectChanges();
  });
};

self.onDataUpdated = function () {
  self.ctx.ngZone.run(function () {
    if (self.ctx.$scope.isHidden) return;

    refreshOptionsFromLastTelemetry();
    self.ctx.detectChanges();
  });
};

function init() {
  // UI state
  self.ctx.$scope.isHidden = false;
  self.ctx.$scope.camOptions = [];
  self.ctx.$scope.selectedCam = null;

  // Keys
  self.telemetryKey = self.ctx.settings.telemetryKey || 'pass_total';
  self.sharedAttrKey = 'cam';
  self.deviceLabelKey = 'deviceLabel';

  // Cache
  self.sharedCamLoaded = false;
  self.sharedCamValue = null;

  // Services
  self.attributeService = self.ctx.$scope.$injector.get(
    self.ctx.servicesMap.get('attributeService')
  );

  // SAFE: telemetryService có thể không tồn tại -> tránh crash hasOwnProperty
  self.telemetryService = null;
  try {
    const tToken =
      (self.ctx.servicesMap && self.ctx.servicesMap.get && (
        self.ctx.servicesMap.get('telemetryService') ||
        self.ctx.servicesMap.get('telemetry')
      )) || null;

    if (tToken) {
      self.telemetryService = self.ctx.$scope.$injector.get(tToken);
    }
  } catch (e) {
    self.telemetryService = null;
  }

  // Handler
  self.ctx.$scope.onCamSelect = function (camName) {
    if (self.ctx.$scope.isHidden) return;

    self.ctx.$scope.selectedCam = camName;
    self.sharedCamValue = camName;
    self.ctx.detectChanges();
    saveSharedCam(camName);
  };

  // Load shared attributes first (deviceLabel + cam)
  loadSharedAttributes();

  // Try build from subscription data (if already present)
  refreshOptionsFromLastTelemetry();

  // Fallback: fetch latest telemetry directly (only if telemetryService exists)
  fetchLastTelemetryDirectly();
}

/** ---------- EntityId resolver ---------- */
function extractUuid(maybe) {
  if (!maybe) return null;
  if (typeof maybe === 'string') return maybe;
  if (typeof maybe.id === 'string') return maybe.id;
  if (maybe.id && typeof maybe.id.id === 'string') return maybe.id.id;
  if (maybe.entityId) return extractUuid(maybe.entityId);
  if (typeof maybe.targetDeviceId === 'string') return maybe.targetDeviceId;
  return null;
}

function resolveEntityId() {
  let uuid = null;

  if (self.ctx && self.ctx.datasources && self.ctx.datasources.length) {
    const ds = self.ctx.datasources[0];
    uuid =
      extractUuid(ds.entityId) ||
      extractUuid(ds) ||
      extractUuid(ds.datasource) ||
      extractUuid(ds.dataSource);
  }

  if (!uuid && self.ctx && self.ctx.defaultSubscription) {
    uuid =
      extractUuid(self.ctx.defaultSubscription.entityId) ||
      extractUuid(self.ctx.defaultSubscription.targetDeviceId) ||
      extractUuid(self.ctx.defaultSubscription);
  }

  if (!uuid) return null;
  return { entityType: "DEVICE", id: uuid };
}

/** ---------- Read shared attributes (deviceLabel + cam) ---------- */
function loadSharedAttributes() {
  const entityId = resolveEntityId();
  if (!entityId) return;

  self.attributeService
    .getEntityAttributes(entityId, 'SHARED_SCOPE', [self.sharedAttrKey, self.deviceLabelKey])
    .subscribe(
      function (attrs) {
        const map = {};
        (attrs || []).forEach(a => {
          if (a && a.key != null) map[a.key] = a.value;
        });

        // Hide logic
        const deviceLabel = map[self.deviceLabelKey] != null ? String(map[self.deviceLabelKey]) : null;
        if (deviceLabel === 'tablet-type') {
          self.ctx.$scope.isHidden = true;
          self.ctx.detectChanges();
          return;
        }

        // Shared cam
        self.sharedCamLoaded = true;
        self.sharedCamValue = map[self.sharedAttrKey] != null ? String(map[self.sharedAttrKey]) : null;

        // Apply selection if options already available
        applySelectionPolicy(self.ctx.$scope.camOptions || []);
        self.ctx.detectChanges();
      },
      function () {
        // If cannot read deviceLabel -> do not hide
      }
    );
}

/** ---------- Telemetry -> options ---------- */
function getLastTelemetryValueFromCtxData(key) {
  const dataArr = self.ctx.data || [];
  if (!Array.isArray(dataArr) || !dataArr.length) return null;

  const item = dataArr.find(d => d && d.dataKey && d.dataKey.name === key);
  if (!item || !item.data || !item.data.length) return null;

  const last = item.data[item.data.length - 1];
  return last ? last[1] : null;
}

function parseCamOptions(raw) {
  if (raw == null) return [];

  let s = raw;
  if (typeof s !== 'string') s = JSON.stringify(s);
  s = (s || '').trim();

  if ((s.startsWith('"') && s.endsWith('"')) || (s.startsWith("'") && s.endsWith("'"))) {
    s = s.slice(1, -1);
  }
  s = s.replace(/\\"/g, '"');

  let obj;
  try { obj = JSON.parse(s); } catch (e) { return []; }
  if (!obj || typeof obj !== 'object') return [];

  const keys = Object.keys(obj).sort((a, b) => (parseInt(a, 10) || 0) - (parseInt(b, 10) || 0));
  return keys.map(k => `CAM${k}`);
}

function refreshOptionsFromLastTelemetry() {
  if (self.ctx.$scope.isHidden) return;

  const raw = getLastTelemetryValueFromCtxData(self.telemetryKey);
  const options = parseCamOptions(raw);
  if (!options || !options.length) return;

  self.ctx.$scope.camOptions = options;
  applySelectionPolicy(options);
}

/** Fallback: fetch latest telemetry trực tiếp qua API (nếu có telemetryService) */
function fetchLastTelemetryDirectly() {
  if (self.ctx.$scope.isHidden) return;
  if (!self.telemetryService || !self.telemetryService.getLatestTimeseries) return;

  const entityId = resolveEntityId();
  if (!entityId) return;

  self.telemetryService.getLatestTimeseries(entityId, [self.telemetryKey]).subscribe(
    function (data) {
      if (self.ctx.$scope.isHidden) return;

      const arr = data && data[self.telemetryKey];
      if (!arr || !arr.length) return;

      const raw = arr[0].value;
      const options = parseCamOptions(raw);
      if (!options || !options.length) return;

      self.ctx.$scope.camOptions = options;
      applySelectionPolicy(options);
      self.ctx.detectChanges();
    },
    function () {
      // ignore
    }
  );
}

/** ---------- Selection + Save shared cam ---------- */
function applySelectionPolicy(options) {
  if (self.ctx.$scope.isHidden) return;
  if (!options || !options.length) {
    self.ctx.$scope.selectedCam = null;
    return;
  }

  // 1) Prefer shared cam if valid
  if (self.sharedCamValue && options.includes(self.sharedCamValue)) {
    self.ctx.$scope.selectedCam = self.sharedCamValue;
    return;
  }

  // 2) If shared cam not exist (loaded) -> set default and create key
  if (self.sharedCamLoaded && !self.sharedCamValue) {
    self.ctx.$scope.selectedCam = options[0];
    self.sharedCamValue = options[0];
    saveSharedCam(options[0]);
    return;
  }

  // 3) fallback first option
  if (!self.ctx.$scope.selectedCam || !options.includes(self.ctx.$scope.selectedCam)) {
    self.ctx.$scope.selectedCam = options[0];
  }
}

function saveSharedCam(camName) {
  if (self.ctx.$scope.isHidden) return;

  const entityId = resolveEntityId();
  if (!entityId) return;

  const attributes = [{ key: self.sharedAttrKey, value: camName }];
  self.attributeService.saveEntityAttributes(entityId, 'SHARED_SCOPE', attributes).subscribe(
    function () {},
    function () {}
  );
}

