(function () {

  // ===== Cam state from shared attribute =====
  let selectedCamRaw = null; // "CAM10"
  let selectedCamKey = null; // "10"
  let camPollTimer = null;

  const DBG = true;
  const log  = (...a) => { if (DBG) console.log('[TB-AGG-CAM]', ...a); };
  const warn = (...a) => { if (DBG) console.warn('[TB-AGG-CAM]', ...a); };

  // ---------------------------
  // ThingsBoard lifecycle
  // ---------------------------
  self.onInit = function() {
    // patch trước khi widget gốc init
    patchAggregatedValueCardWidget();

    // sync cam lần đầu + poll
    syncCamOnce(true);
    camPollTimer = setInterval(() => syncCamOnce(false), 1000);

    // gọi init gốc
    self.ctx.$scope.aggregatedValueCardWidget.onInit();
  };

  self.onDataUpdated = function() {
    // mỗi lần data cập nhật: bóc JSON -> số
    preprocessSubscriptionDataToNumeric();
    self.ctx.$scope.aggregatedValueCardWidget.onDataUpdated();
  };

  self.onLatestDataUpdated = function() {
    // latest cũng bóc tương tự (nếu widget dùng latest keys)
    preprocessSubscriptionDataToNumeric();
    self.ctx.$scope.aggregatedValueCardWidget.onLatestDataUpdated();
  };

  self.onResize = function() {
    self.ctx.$scope.aggregatedValueCardWidget.onResize();
  };

  self.onEditModeChanged = function() {
    self.ctx.$scope.aggregatedValueCardWidget.onEditModeChanged();
  };

  self.onDestroy = function() {
    try { if (camPollTimer) clearInterval(camPollTimer); } catch (e) {}
    camPollTimer = null;
    self.ctx.$scope.aggregatedValueCardWidget.onDestroy();
  };

  // ---------------------------
  // typeParameters: đổi default key sang pass_total nếu bạn muốn
  // (Bạn có thể giữ nguyên config UI, phần này chỉ default)
  // ---------------------------
  self.typeParameters = function() {
    return {
      maxDatasources: 1,
      maxDataKeys: 1,
      singleEntity: true,
      previewWidth: '400px',
      previewHeight: '300px',
      embedTitlePanel: true,
      supportsUnitConversion: true,
      hasAdditionalLatestDataKeys: true,

      // Default: bạn có thể đổi name/label theo UI sau
      defaultDataKeysFunction: function() {
        return [
          {
            name: 'pass_total',
            label: 'Pass Total',
            type: 'timeseries',
            color: 'rgba(0, 0, 0, 0.87)',
            units: '',
            decimals: 0
          }
        ];
      },

      defaultLatestDataKeysFunction: function(configComponent, configData) {
        // giữ nguyên cơ chế của TB (nếu cần latest)
        return configComponent.createDefaultAggregatedValueLatestDataKeys(
          configData, 'pass_total', '', 0
        );
      }
    };
  };

  // ==========================================================
  // 1) Patch widget gốc: không cần sửa file core, chỉ "wrap"
  // ==========================================================
  function patchAggregatedValueCardWidget() {
    const w = self.ctx && self.ctx.$scope && self.ctx.$scope.aggregatedValueCardWidget;
    if (!w || w.__tb_cam_patched__) return;

    w.__tb_cam_patched__ = true;
    log('Patching aggregatedValueCardWidget...');

    // Wrap thêm preprocess trước khi chạy logic gốc (phòng trường hợp TB gọi trực tiếp)
    const origOnDataUpdated = w.onDataUpdated && w.onDataUpdated.bind(w);
    if (origOnDataUpdated) {
      w.onDataUpdated = function() {
        preprocessSubscriptionDataToNumeric();
        return origOnDataUpdated();
      };
    }

    const origOnLatestDataUpdated = w.onLatestDataUpdated && w.onLatestDataUpdated.bind(w);
    if (origOnLatestDataUpdated) {
      w.onLatestDataUpdated = function() {
        preprocessSubscriptionDataToNumeric();
        return origOnLatestDataUpdated();
      };
    }
  }

  // ==========================================================
  // 2) Đọc shared attribute cam (robust)
  // ==========================================================
  function syncCamOnce(forceRefreshWidget) {
    const attrSvc = getAttributeServiceSafe();
    const entityId = getEntityIdFromDatasource();

    if (!attrSvc || !entityId) {
      warn('No entityId/attrSvc', { entityId, attrSvc });
      return;
    }

    attrSvc.getEntityAttributes(entityId, 'SHARED_SCOPE', ['cam']).subscribe(
      (attrs) => {
        const camAttr = (attrs || []).find(a => a && a.key === 'cam');
        const raw = camAttr ? String(camAttr.value || '').trim() : '';

        if (!raw) return;

        // chỉ đổi khi khác
        if (raw === selectedCamRaw && !forceRefreshWidget) return;

        selectedCamRaw = raw;
        selectedCamKey = extractDigits(raw); // "CAM10" => "10"

        log('Cam changed:', { selectedCamRaw, selectedCamKey });

        // ép widget refresh lại UI
        if (forceRefreshWidget) {
          try { self.ctx.detectChanges(); } catch (e) {}
        } else {
          // trigger re-render: gọi onDataUpdated lại nếu có data sẵn
          try {
            preprocessSubscriptionDataToNumeric();
            self.ctx.$scope.aggregatedValueCardWidget.onDataUpdated();
          } catch (e) {}
        }
      },
      (err) => warn('getEntityAttributes failed:', err)
    );
  }

  function extractDigits(s) {
    const m = String(s || '').match(/(\d+)/);
    return m ? m[1] : null;
  }

  function getAttributeServiceSafe() {
    try {
      if (self.ctx?.$scope?.$injector && self.ctx.servicesMap) {
        return self.ctx.$scope.$injector.get(self.ctx.servicesMap.get('attributeService'));
      }
    } catch (e) {}
    try { if (self.ctx?.attributeService) return self.ctx.attributeService; } catch (e) {}
    return null;
  }

  function getEntityIdFromDatasource() {
    // ✅ datasource alias -> entityId
    try {
      const ds0 = self.ctx?.datasources?.[0];
      const eid = ds0?.entityId;
      if (eid?.entityType && eid?.id) return eid;
    } catch (e) {}

    // ✅ subscription entityId
    try {
      const subEid = self.ctx?.defaultSubscription?.entityId;
      if (subEid?.entityType && subEid?.id) return subEid;
    } catch (e) {}

    // last resort
    try {
      const td = self.ctx?.defaultSubscription?.targetDeviceId;
      if (td) return { entityType: 'DEVICE', id: td };
    } catch (e) {}

    return null;
  }

  // ==========================================================
  // 3) Quan trọng: BÓC JSON -> SỐ để widget gốc aggregation được
  // ==========================================================
  function preprocessSubscriptionDataToNumeric() {
    const sub = self.ctx?.defaultSubscription;
    if (!sub || !Array.isArray(sub.data)) return;

    // Nếu chưa có cam -> không bóc (widget sẽ không hiện đúng)
    if (!selectedCamKey) {
      // không hard fallback sang CAM2 nữa để tránh “vẽ nhầm cam”
      warn('No selectedCamKey yet -> skip preprocess');
      return;
    }

    // dataKey đầu tiên (vì maxDataKeys = 1)
    const dk = sub.data[0];
    if (!dk || !Array.isArray(dk.data)) return;

    // tránh preprocess lặp nhiều lần trên cùng dữ liệu (nếu TB gọi nhiều hook)
    // key dựa trên cam + độ dài data
    const stamp = `${selectedCamKey}:${dk.data.length}`;
    if (dk.__tb_preprocessed_stamp__ === stamp) return;
    dk.__tb_preprocessed_stamp__ = stamp;

    // bóc từng point: [ts, rawValue] => [ts, number]
    const newData = [];
    for (const p of dk.data) {
      if (!p || p.length < 2) continue;
      const ts = Number(p[0]);
      const raw = p[1];

      const num = extractNumericFromJson(raw, selectedCamKey);
      // num có thể null => giữ null để widget gốc xử lý “không có dữ liệu”
      newData.push([ts, num]);
    }

    dk.data = newData;
    // giữ nguyên dk.dataKey.label/name do UI set -> legend/text vẫn đúng
    log('Preprocessed to numeric for cam', selectedCamKey, 'points:', newData.length);
  }

  // lấy item[camId].total_in (bạn có thể đổi sang total_out nếu muốn)
  function extractNumericFromJson(rawValue, camId) {
    if (rawValue == null) return null;

    const obj = coerceToObject(rawValue);
    if (!obj || typeof obj !== 'object') return null;

    const item = obj[String(camId)];
    if (!item) return null;

    const v = item.total_in; // ✅ lấy total_in
    const num = Number(v);
    return Number.isFinite(num) ? num : null;
  }

  function coerceToObject(raw) {
    if (raw && typeof raw === 'object') return raw;

    if (typeof raw === 'string') {
      const s0 = raw.trim().replace(/\r?\n/g, '');

      try { return JSON.parse(s0); } catch (e) {}
      try { return JSON.parse(s0.replace(/'/g, '"')); } catch (e) {}

      // trường hợp bị quote 2 lớp
      try {
        const unquoted = JSON.parse(s0);
        if (typeof unquoted === 'string') {
          try { return JSON.parse(unquoted); } catch (e) {}
          try { return JSON.parse(unquoted.replace(/'/g, '"')); } catch (e) {}
        }
      } catch (e) {}
    }

    return null;
  }

})();

