descriptor.controllerScript:
(function () {
  let chart = null;

  // ===== Shared attributes state =====
  let deviceLabelRaw = null;     // "edge-type" | "tablet-type"
  let activeMode = null;         // 'edge' | 'tablet'
  let selectedCamRaw = null;     // "CAM10"
  let selectedCamKey = null;     // "10"

  // ===== Runtime =====
  let pollTimer = null;
  let lastSub = null;

  // ===== Redraw control =====
  let redrawTimer = null;
  let lastAttrSig = null;
  let lastRenderSig = null;

  // ✅ animate only when there is a real change
  let pendingAnimate = true; // animate first render too

  // ===== Japanese font =====
