  // ============================================================
  // Attribute service + entityId (TB 4.3.x robust)
  // ============================================================
  function getAttributeServiceSafe() {
    try {
      const inj = self.ctx && self.ctx.$scope && self.ctx.$scope.$injector;
      if (inj) {
        try { return inj.get('attributeService'); } catch (e) {}
        try { return inj.get('AttributeService'); } catch (e) {}
        try {
          if (self.ctx.servicesMap && self.ctx.servicesMap.get) {
            const token = self.ctx.servicesMap.get('attributeService');
            if (token) return inj.get(token);
          }
        } catch (e) {}
      }
    } catch (e) {}
    try { if (self.ctx && self.ctx.attributeService) return self.ctx.attributeService; } catch (e) {}
    return null;
  }

  function normalizeEntityId(eid) {
    if (!eid) return null;
    if (eid.entityType && eid.id) return eid;
    if (typeof eid === 'string') return { entityType: 'DEVICE', id: eid };
    if (eid.id && eid.id.id && eid.id.entityType) return { entityType: eid.id.entityType, id: eid.id.id };
    return null;
  }

  function getEntityIdRobust() {
    const ctx = self.ctx || {};

    try {
      const ds0 = ctx.datasources && ctx.datasources[0];
      const eid = ds0 && (ds0.entityId || (ds0.datasource && ds0.datasource.entityId));
      const n = normalizeEntityId(eid);
      if (n) return n;
    } catch (e) {}

    try {
      const d0 = ctx.data && ctx.data[0];
      const eid = d0 && d0.datasource && d0.datasource.entityId;
      const n = normalizeEntityId(eid);
      if (n) return n;
    } catch (e) {}

    try {
      const sub = ctx.defaultSubscription;
      const ds0 = sub && sub.datasources && sub.datasources[0];
      const eid = ds0 && ds0.entityId;
      const n = normalizeEntityId(eid);
      if (n) return n;
    } catch (e) {}

    try {
      const s0 = ctx.subscriptions && ctx.subscriptions[0];
      const ds0 = s0 && s0.datasources && s0.datasources[0];
      const eid = ds0 && ds0.entityId;
      const n = normalizeEntityId(eid);
      if (n) return n;
    } catch (e) {}

    try {
      const eid = ctx.defaultSubscription && ctx.defaultSubscription.entityId;
      const n = normalizeEntityId(eid);
      if (n) return n;
    } catch (e) {}

    try {
      const td = ctx.defaultSubscription && ctx.defaultSubscription.targetDeviceId;
      const n = normalizeEntityId(td);
      if (n) return n;
    } catch (e) {}

    return null;
  }

  // ✅ NEW: dùng state 'default' để lấy entityId đúng khi ALL devices (default = entityList)
  function getEntityIdForAttrs() {
    try {
      const sc = self.ctx && self.ctx.stateController;
      const st = sc && sc.getState ? sc.getState('default') : null;

      // ALL devices: default = [{id, entityType}, ...]
      if (Array.isArray(st) && st.length) {
        const first = st[0];
        const n = normalizeEntityId(first);
        if (n) return n;
        // trường hợp {id:'...', entityType:'DEVICE'} vẫn normalize được, nếu không:
        if (first && first.id && first.entityType) return { id: first.id, entityType: first.entityType };
      }

      // SINGLE: default = { entityId: {id, entityType}, ... }
      if (st && st.entityId) {
        const n = normalizeEntityId(st.entityId);
        if (n) return n;
      }
    } catch (e) {}

    // fallback logic cũ
    return getEntityIdRobust();
  }

  // ============================================================
  // Poll shared attributes (deviceLabel + cam) - redraw only if changed
  // ============================================================
  function syncAttrsOnce(forceRedraw) {
    const attrSvc = getAttributeServiceSafe();
    const entityId = getEntityIdForAttrs(); // ✅ changed: robust for ALL
    if (!attrSvc || !entityId) return;

    attrSvc.getEntityAttributes(entityId, 'SHARED_SCOPE', ['deviceLabel', 'cam']).subscribe(
      (attrs) => {
        const aDevice = (attrs || []).find(x => x && x.key === 'deviceLabel');
        const aCam    = (attrs || []).find(x => x && x.key === 'cam');

        const newDeviceLabel = aDevice ? String(aDevice.value || '').trim() : '';
        const newCamRaw      = aCam ? String(aCam.value || '').trim() : '';

        const newMode = (newDeviceLabel === 'edge-type') ? 'edge'
                     : (newDeviceLabel === 'tablet-type') ? 'tablet'
                     : null;

        const newCamKey = extractDigits(newCamRaw);

        const sig = JSON.stringify({
          deviceLabel: newDeviceLabel || null,
          mode: newMode || null,
          camRaw: newCamRaw || null,
          camKey: newCamKey || null
        });

        if (!forceRedraw && sig === lastAttrSig) return;

        lastAttrSig = sig;
        deviceLabelRaw = newDeviceLabel || null;
        activeMode = newMode || null;

        selectedCamRaw = newCamRaw || null;
        selectedCamKey = newCamKey || null;

        pendingAnimate = true; // ✅ đổi cam/deviceLabel -> animate
        scheduleRedraw();
      },
      () => {}
    );
  }

  function extractDigits(s) {
    const m = String(s || '').match(/(\d+)/);
    return m ? m[1] : null;
  }

  // ============================================================
  // Redraw scheduling (debounce)
  // ============================================================
  function scheduleRedraw() {
    if (!chart || !lastSub) return;
    if (redrawTimer) clearTimeout(redrawTimer);
    redrawTimer = setTimeout(() => {
      redrawTimer = null;
      redrawMerged();
    }, 120);
  }

  function makeRenderSignature() {
    const sub = lastSub;
    const tw = sub?.subscriptionTimewindow;
    const start = tw?.minTime || tw?.fixedWindow?.startTimeMs || null;
    const end   = tw?.maxTime || tw?.fixedWindow?.endTimeMs || null;

    let dataSig = '';
    try {
      const arr = (sub && Array.isArray(sub.data)) ? sub.data : [];
      const parts = arr.map(dk => {
        const n = dk && dk.data ? dk.data.length : 0;
        const lastT = (dk && dk.data && dk.data.length) ? dk.data[dk.data.length - 1][0] : null;
        const name = (dk && dk.dataKey) ? (dk.dataKey.name || dk.dataKey.label || '') : '';
        return `${name}:${n}:${lastT}`;
      });
      dataSig = parts.join('|');
    } catch (e) {
      dataSig = '';
    }

    return JSON.stringify({
      mode: activeMode || null,
      camKey: selectedCamKey || null,
      start, end,
      dataSig
    });
  }

  // ✅ NEW: detect series type from subscription for mixed/all cases
  function hasEdgeSeries(sub) {
    if (!sub || !Array.isArray(sub.data)) return false;
    return sub.data.some(dk => (dk?.dataKey?.name || dk?.dataKey?.label) === 'pass_total');
  }

  function hasTabletSeries(sub) {
    if (!sub || !Array.isArray(sub.data)) return false;
    // numeric: sample few points
    return sub.data.some(dk => {
      const arr = dk?.data || [];
      for (let i = 0; i < Math.min(arr.length, 5); i++) {
        const v = arr[i]?.[1];
        if (typeof v === 'number' && Number.isFinite(v)) return true;
      }
      return false;
    });
  }

  // ============================================================
  // Merged redraw (edge/tablet)
  // ============================================================
  function redrawMerged() {
    if (!chart || !lastSub) return;

    const renderSig = makeRenderSignature();
    if (renderSig === lastRenderSig) {
      pendingAnimate = false; // không animate nếu thật ra không đổi gì
      return;
    }
    lastRenderSig = renderSig;

    // ✅ Always reset datasets before draw (important when mixed + append)
    chart.data.datasets = [];

    // ✅ When activeMode is unreliable (ALL/mixed), detect based on data
    const edgeOk = hasEdgeSeries(lastSub);
    const tabletOk = hasTabletSeries(lastSub);

    if (!activeMode) {
      if (!edgeOk && !tabletOk) {
        chart.data.datasets = [];
        updateChart(pendingAnimate);
        pendingAnimate = false;
        return;
      }

      // draw what exists
      suppressUpdate = true;
      if (edgeOk) redrawEdge();
      if (tabletOk) redrawTablet();
      suppressUpdate = false;

      updateChart(pendingAnimate);
      pendingAnimate = false;
      return;
    }

    // activeMode exists, but ALL devices may be mixed -> draw both if present
    suppressUpdate = true;
    if (activeMode === 'edge') {
      if (edgeOk) redrawEdge();
      if (tabletOk) redrawTablet();
    } else {
      if (tabletOk) redrawTablet();
      if (edgeOk) redrawEdge();
    }
    suppressUpdate = false;

    updateChart(pendingAnimate);
    pendingAnimate = false;
  }

  // ============================================================
  // EDGE logic (JSON pass_total + selected cam)
  // ============================================================
  function redrawEdge() {
    if (!selectedCamKey) {
      // do not clear datasets here because mixed mode may still draw tablet
      return;
    }

    const sub = lastSub;
    const tw = sub?.subscriptionTimewindow;

    let startTime = tw?.minTime || tw?.fixedWindow?.startTimeMs;
    let endTime   = tw?.maxTime || tw?.fixedWindow?.endTimeMs;

    if (isDayMode(tw)) {
      const [s0, e24] = getDayWindowFull(tw);
      startTime = s0; endTime = e24;
    }

    const spanDays = (endTime && startTime) ? (endTime - startTime) / (24 * 60 * 60 * 1000) : 0;
    const isYearMode = spanDays >= 300;
    const isMonthMode = !isYearMode && spanDays > 1;
    const isHourlyGapMode = spanDays <= 1;

    // ✅ ALL vs SINGLE
    const datasets = isAllDevicesMode()
      ? buildDatasetForSelectedCam_EDGE_ALL(sub, startTime, endTime, { isMonthMode, isYearMode, isHourlyGapMode })
      : buildDatasetForSelectedCam_EDGE(sub, startTime, endTime, { isMonthMode, isYearMode, isHourlyGapMode });

    // ✅ append (do not overwrite) to support mixed mode
    chart.data.datasets = (chart.data.datasets || []).concat(datasets);

    applyTimeScaleForWindow(chart, startTime, endTime, { isMonthMode, isYearMode });

    if (!suppressUpdate) updateChart(pendingAnimate);
  }

  function buildDatasetForSelectedCam_EDGE(subscription, startTime, endTime, opts) {
    const results = [];
    if (!subscription || !Array.isArray(subscription.data)) return results;

    const { isMonthMode, isYearMode, isHourlyGapMode } = opts || {};
    const dk = subscription.data.find(x => (x.dataKey?.name || x.dataKey?.label) === 'pass_total');
    if (!dk) return results;

    const bucketMode = isHourlyGapMode ? 'hour' : (isMonthMode ? 'day' : (isYearMode ? 'month' : 'hour'));

    const rawPoints = (dk.data || [])
      .filter(p => p && p.length >= 2)
      .filter(p => (!startTime || p[0] >= startTime) && (!endTime || p[0] <= endTime))
      .map(p => ({ t: Number(p[0]), obj: coerceToObject(p[1]) }))
      .filter(p => p.obj && typeof p.obj === 'object');

    if (!rawPoints.length) return results;

    const sumMap = new Map();
    rawPoints.forEach(p => {
      const bt = normBucketTs(p.t, bucketMode);
      const item = p.obj[selectedCamKey];
      const v = item && item.total_in;
      const num = Number(v);
      if (!Number.isFinite(num)) return;
      sumMap.set(bt, (sumMap.get(bt) || 0) + num);
    });

    let points = [];
    sumMap.forEach((val, t) => points.push({ t: Number(t), y: val }));
    points.sort((a, b) => a.t - b.t);

    points = fillGapsWithNull(points, startTime, endTime, bucketMode);
    points = stitchZeroBeforeData(points);

    const uiSeriesLabel = (dk.dataKey && (dk.dataKey.label || dk.dataKey.name))
      ? (dk.dataKey.label || dk.dataKey.name)
      : 'Series';

    results.push({
      label: uiSeriesLabel,
      data: points,
      borderColor: '#2980b9',
      backgroundColor: '#2980b9',
      fill: false,
      borderWidth: 5,
      lineTension: 0.3,
      spanGaps: false,
      pointRadius: 2,
      pointHitRadius: 6,
      pointHoverRadius: 5,
      pointStyle: 'circle',
      showLine: true
    });

    return results;
  }

  // ✅ NEW: ALL DEVICE aggregator cho EDGE
  function buildDatasetForSelectedCam_EDGE_ALL(subscription, startTime, endTime, opts) {
    const results = [];
    if (!subscription || !Array.isArray(subscription.data)) return results;

    const { isMonthMode, isYearMode, isHourlyGapMode } = opts || {};
    const bucketMode = isHourlyGapMode ? 'hour' : (isMonthMode ? 'day' : (isYearMode ? 'month' : 'hour'));

    const dks = subscription.data.filter(x => (x.dataKey?.name || x.dataKey?.label) === 'pass_total');
    if (!dks.length) return results;

    const sumMap = new Map();

    dks.forEach(dk => {
      const rawPoints = (dk.data || [])
        .filter(p => p && p.length >= 2)
        .filter(p => (!startTime || p[0] >= startTime) && (!endTime || p[0] <= endTime))
        .map(p => ({ t: Number(p[0]), obj: coerceToObject(p[1]) }))
        .filter(p => p.obj && typeof p.obj === 'object');

      rawPoints.forEach(p => {
        const bt = normBucketTs(p.t, bucketMode);
        const item = p.obj[selectedCamKey];
        const v = item && item.total_in;
        const num = Number(v);
        if (!Number.isFinite(num)) return;
        sumMap.set(bt, (sumMap.get(bt) || 0) + num);
      });
    });

    let points = [];
    sumMap.forEach((val, t) => points.push({ t: Number(t), y: val }));
    points.sort((a, b) => a.t - b.t);

    points = fillGapsWithNull(points, startTime, endTime, bucketMode);
    points = stitchZeroBeforeData(points);

    const dk0 = dks[0];
    const baseLabel = (dk0.dataKey && (dk0.dataKey.label || dk0.dataKey.name))
      ? (dk0.dataKey.label || dk0.dataKey.name)
      : 'pass_total';

    results.push({
      label: `${baseLabel} (All devices)`,
      data: points,
      borderColor: '#2980b9',
      backgroundColor: '#2980b9',
      fill: false,
      borderWidth: 5,
      lineTension: 0.3,
      spanGaps: false,
      pointRadius: 2,
      pointHitRadius: 6,
      pointHoverRadius: 5,
      pointStyle: 'circle',
      showLine: true
    });

    return results;
  }

  // ============================================================
  // TABLET logic (numeric series)
  // ============================================================
  function redrawTablet() {
    const sub = lastSub;
    const tw = sub?.subscriptionTimewindow;

    let startTime = tw?.minTime || tw?.fixedWindow?.startTimeMs;
    let endTime   = tw?.maxTime || tw?.fixedWindow?.endTimeMs;

    if (isDayMode(tw)) {
      const [s0, e24] = getDayWindowFull(tw);
      startTime = s0; endTime = e24;
    }

    const spanDays = (endTime && startTime) ? (endTime - startTime) / (24*60*60*1000) : 0;
    const isYearMode      = spanDays >= 300;
    const isMonthMode     = !isYearMode && spanDays > 1;
    const isHourlyGapMode = spanDays <= 1;

    const datasets = isAllDevicesMode()
      ? buildDatasetsFromSubscription_TABLET_ALL(sub, startTime, endTime, { isMonthMode, isYearMode, isHourlyGapMode })
      : buildDatasetsFromSubscription_TABLET(sub, startTime, endTime, { isMonthMode, isYearMode, isHourlyGapMode });

    // ✅ append (do not overwrite) to support mixed mode
    chart.data.datasets = (chart.data.datasets || []).concat(datasets);

    applyTimeScaleForWindow(chart, startTime, endTime, { isMonthMode, isYearMode });

    if (!suppressUpdate) updateChart(pendingAnimate);
  }

  function buildDatasetsFromSubscription_TABLET(subscription, startTime, endTime, opts) {
    const results = [];
    if (!subscription || !Array.isArray(subscription.data)) return results;

    const { isMonthMode, isYearMode, isHourlyGapMode } = opts || {};
    const fallbackColors = ['#e74c3c','#27ae60','#2980b9','#8e44ad','#f39c12','#16a085','#c0392b','#2c3e50'];

    subscription.data.forEach((dk, idx) => {
      const key   = dk.dataKey || {};
      const label = key.label || key.name || `Series ${idx + 1}`;
      const color = key.color || fallbackColors[idx % fallbackColors.length];

      let points = (dk.data || [])
        .filter(p => (!startTime || p[0] >= startTime) && (!endTime || p[0] <= endTime))
        .map(p => ({ t: Number(p[0]), y: p[1] }));

      if (isHourlyGapMode) points = fillGapsWithNull(points, startTime, endTime, 'hour');
      else if (isMonthMode) points = fillGapsWithNull(points, startTime, endTime, 'day');
      else if (isYearMode)  points = fillGapsWithNull(points, startTime, endTime, 'month');

      points = stitchZeroBeforeData(points);

      results.push({
        label,
        data: points,
        borderColor: color,
        backgroundColor: color,
        fill: false,
        borderWidth: 5,
        lineTension: 0.3,
        spanGaps: false,
        pointRadius: 2,
        pointHitRadius: 6,
        pointHoverRadius: 5,
        pointStyle: 'circle',
        showLine: true
      });
    });

    return results;
  }

  // ✅ NEW: ALL DEVICE aggregator cho TABLET (group theo dataKey.name/label)
  function buildDatasetsFromSubscription_TABLET_ALL(subscription, startTime, endTime, opts) {
    const results = [];
    if (!subscription || !Array.isArray(subscription.data)) return results;

    const { isMonthMode, isYearMode, isHourlyGapMode } = opts || {};
    const fallbackColors = ['#e74c3c','#27ae60','#2980b9','#8e44ad','#f39c12','#16a085','#c0392b','#2c3e50'];

    const bucketMode = isHourlyGapMode ? 'hour' : (isMonthMode ? 'day' : (isYearMode ? 'month' : 'hour'));

    const group = new Map(); // keyName -> {label, color, sumMap}

    subscription.data.forEach((dk) => {
      const keyObj = dk.dataKey || {};
      const keyName = keyObj.name || keyObj.label;
      if (!keyName) return;

      if (!group.has(keyName)) {
        group.set(keyName, {
          label: (keyObj.label || keyObj.name || keyName),
          color: keyObj.color || fallbackColors[group.size % fallbackColors.length],
          sumMap: new Map()
        });
      }

      const g = group.get(keyName);

      (dk.data || [])
        .filter(p => p && p.length >= 2)
        .filter(p => (!startTime || p[0] >= startTime) && (!endTime || p[0] <= endTime))
        .forEach(p => {
          const ts = Number(p[0]);
          const y = Number(p[1]);
          if (!Number.isFinite(y)) return;

          const bt = normBucketTs(ts, bucketMode);
          g.sumMap.set(bt, (g.sumMap.get(bt) || 0) + y);
        });
    });

    group.forEach((g) => {
      let points = [];
      g.sumMap.forEach((y, t) => points.push({ t: Number(t), y }));
      points.sort((a, b) => a.t - b.t);

      points = fillGapsWithNull(points, startTime, endTime, bucketMode);
      points = stitchZeroBeforeData(points);

      results.push({
        label: `${g.label} (All devices)`,
        data: points,
        borderColor: g.color,
        backgroundColor: g.color,
        fill: false,
        borderWidth: 5,
        lineTension: 0.3,
        spanGaps: false,
        pointRadius: 2,
        pointHitRadius: 6,
        pointHoverRadius: 5,
        pointStyle: 'circle',
        showLine: true
      });
    });

    return results;
  }

  // ============================================================
  // ✅ Update chart: animate only when requested
  // ============================================================
  function updateChart(animate) {
    if (!chart) return;

    if (animate) {
      chart.options.animation.duration = 800;
      chart.update();
    } else {
      chart.options.animation.duration = 0;
      // Chart.js 2.x: update(0) -> no animation
      try { chart.update(0); } catch (e) { chart.update(); }
    }
  }

  // ============================================================
  // Shared helpers
  // ============================================================
  function applyTimeScaleForWindow(chart, startTime, endTime, opts) {
    const xAxis = chart.options.scales.xAxes[0];
    const { isMonthMode, isYearMode } = opts || {};
    let minMs = startTime ? Number(startTime) : undefined;
    let maxMs = endTime   ? Number(endTime)   : undefined;

    if (isDayMode(self.ctx.defaultSubscription?.subscriptionTimewindow)) {
      const s = new Date(minMs);
      const minDay = new Date(s.getFullYear(), s.getMonth(), s.getDate(), 7, 0, 0, 0).getTime();
      const maxDay = new Date(s.getFullYear(), s.getMonth(), s.getDate(), 19, 0, 0, 0).getTime();
      minMs = minDay;
      maxMs = maxDay;

      xAxis.time.unit = 'hour';
      xAxis.time.stepSize = 1;
      xAxis.time.displayFormats.hour = 'HH:mm';
      xAxis.time.tooltipFormat = 'HH:mm';
      xAxis.offset = false;
    }
    else if (isYearMode) {
      xAxis.time.unit = 'month';
      xAxis.time.stepSize = 1;
      xAxis.time.displayFormats.month = 'MMM';
      xAxis.offset = true;
    }
    else if (isMonthMode) {
      const s = new Date(minMs), e = new Date(maxMs);
      const minDay = new Date(s.getFullYear(), s.getMonth(), s.getDate(), 0, 0, 0, 0).getTime();
      const maxDay = new Date(e.getFullYear(), e.getMonth(), e.getDate(), 23, 59, 59, 999).getTime();
      minMs = minDay; maxMs = maxDay;

      xAxis.time.unit = 'day';
      xAxis.time.stepSize = 1;
      xAxis.time.displayFormats.day = 'MMM DD';
      xAxis.time.tooltipFormat = 'YYYY-MM-DD';
      xAxis.offset = true;
    }
    else {
      xAxis.time.unit = 'hour';
      xAxis.time.stepSize = 1;
      xAxis.time.displayFormats.hour = 'HH:mm';
      xAxis.offset = false;
    }

    xAxis.ticks.min = minMs;
    xAxis.ticks.max = maxMs;
    xAxis.time.min  = minMs;
    xAxis.time.max  = maxMs;
  }

  function normBucketTs(ms, mode) {
    const x = new Date(ms);
    if (mode === 'hour')  return new Date(x.getFullYear(), x.getMonth(), x.getDate(), x.getHours(), 0, 0, 0).getTime();
    if (mode === 'day')   return new Date(x.getFullYear(), x.getMonth(), x.getDate(), 0, 0, 0, 0).getTime();
    if (mode === 'month') return new Date(x.getFullYear(), x.getMonth(), 1, 0, 0, 0, 0).getTime();
    return Number(ms);
  }

  function fillGapsWithNull(data, startTime, endTime, mode) {
    if (!Array.isArray(data) || data.length === 0 || !startTime || !endTime) return data || [];

    const map = {};
    const normKey = (ms) => {
      const x = new Date(ms);
      if (mode === 'hour')  return new Date(x.getFullYear(), x.getMonth(), x.getDate(), x.getHours(), 0, 0, 0).getTime();
      if (mode === 'day')   return new Date(x.getFullYear(), x.getMonth(), x.getDate(), 0, 0, 0, 0).getTime();
      if (mode === 'month') return new Date(x.getFullYear(), x.getMonth(), 1, 0, 0, 0, 0).getTime();
    };

    data.forEach(p => { map[normKey(p.t)] = p.y; });

    const filled = [];

    if (mode === 'hour') {
      const STEP = 60 * 60 * 1000;
      const start = Math.floor(startTime / STEP) * STEP;
      const end   = Math.ceil(endTime   / STEP) * STEP;
      for (let t = start; t <= end; t += STEP) {
        filled.push({ t, y: Object.prototype.hasOwnProperty.call(map, t) ? map[t] : null });
      }
      return filled;
    }

    if (mode === 'day') {
      const DAY = 24 * 60 * 60 * 1000;
      const sDate = new Date(startTime);
      const eDate = new Date(endTime);
      const start = new Date(sDate.getFullYear(), sDate.getMonth(), sDate.getDate()).getTime();
      const end   = new Date(eDate.getFullYear(), eDate.getMonth(), eDate.getDate()).getTime();
      for (let t = start; t <= end; t += DAY) {
        filled.push({ t, y: Object.prototype.hasOwnProperty.call(map, t) ? map[t] : null });
      }
      return filled;
    }

    if (mode === 'month') {
      const s = new Date(startTime);
      const e = new Date(endTime);
      let cur = new Date(s.getFullYear(), s.getMonth(), 1);
      const endM = new Date(e.getFullYear(), e.getMonth(), 1);
      for (; cur.getTime() <= endM.getTime(); cur.setMonth(cur.getMonth() + 1)) {
        const t = cur.getTime();
        filled.push({ t, y: Object.prototype.hasOwnProperty.call(map, t) ? map[t] : null });
      }
      return filled;
    }

    return data;
  }

  function stitchZeroBeforeData(points) {
    if (!Array.isArray(points) || points.length === 0) return points || [];
    const out = [];
    for (let i = 0; i < points.length; i++) {
      const curr = points[i];
      const prev = i > 0 ? points[i - 1] : null;
      if (prev && prev.y == null && curr.y != null) out.push({ t: prev.t, y: 0 });
      out.push(curr);
    }
    return out;
  }

  function isDayMode(tw) {
    if (!tw) return false;
    const start = tw.minTime || tw.fixedWindow?.startTimeMs;
    const end   = tw.maxTime || tw.fixedWindow?.endTimeMs;
    if (!start || !end) return false;
    const ONE_DAY = 24 * 60 * 60 * 1000;
    if (end - start > ONE_DAY + 15 * 60 * 1000) return false;
    const s = new Date(start), e = new Date(end);
    return s.getFullYear() === e.getFullYear() &&
           s.getMonth() === e.getMonth() &&
           s.getDate() === e.getDate();
  }

  function getDayWindowFull(tw) {
    const ref = tw.fixedWindow?.startTimeMs || tw.minTime || Date.now();
    const d = new Date(ref);
    const y = d.getFullYear(), m = d.getMonth(), day = d.getDate();
    const start0 = new Date(y, m, day, 0, 0, 0, 0).getTime();
    const end24  = new Date(y, m, day, 23, 59, 59, 999).getTime();
    return [start0, end24];
  }

  function coerceToObject(raw) {
    if (raw && typeof raw === 'object') return raw;
    if (typeof raw === 'string') {
      const s0 = raw.trim().replace(/\r?\n/g, '');
      try { return JSON.parse(s0); } catch (e) {}
      try { return JSON.parse(s0.replace(/'/g, '"')); } catch (e) {}
      try {
        const unquoted = JSON.parse(s0);
        if (typeof unquoted === 'string') {
          try { return JSON.parse(unquoted); } catch (e) {}
          try { return JSON.parse(unquoted.replace(/'/g, '"')); } catch (e) {}
        }
      } catch (e) {}
    }
    return null;
  }
})();

