descriptor.controllerScript:
(function () {
  let chart = null;

  // ===== MODE + selection state =====
  let deviceLabel = null;          // "tablet-type" | "edge-type" | null
  let selectedCamKey = null;       // cam_X_pass_total_in | pass_total
  let busHandler = null;

  // ===== Const =====
  const DEVICE_LABEL_KEY = 'deviceLabel';  // SERVER_SCOPE or SHARED_SCOPE (fallback)
  const CAM_ATTR_KEY = 'cam';              // SHARED_SCOPE attribute

  const TABLET_KEYS = ['pass_total', 'watching_total', 'payment_total', 'paymented_total'];

  const CAM_KEY_PREFIX = 'cam_';
  const CAM_KEY_SUFFIX = '_pass_total_in';
  const CAM_COUNT = 30;

  // ✅ NEW: special cam values -> show pass_total
  const CAM_SPECIAL_VALUES = ['CAM', 'ALL'];
  const FALLBACK_KEY_WHEN_CAM_SPECIAL = 'pass_total';

  // FIXED colors for tablet
  const FIXED_COLOR_MAP = {
    pass_total: '#86D0FF',
    watching_total: '#4CAF50',
    payment_total: '#ED1C24',
    paymented_total: '#ED1C24'
  };

  // services
  let attributeService = null;

  self.onInit = function () {
    if (typeof moment !== 'undefined') moment.locale('en');

    // init attributeService
    try {
      attributeService = self.ctx.$scope.$injector.get(self.ctx.servicesMap.get('attributeService'));
    } catch (e) {
      attributeService = null;
    }

    // init chart
    const canvas = self.ctx.$container[0].querySelector('#chart');
    if (!canvas) {
      console.error('[LineChart] Missing <canvas id="chart"> in widget HTML');
      return;
    }
    const ctx = canvas.getContext('2d');

    chart = new Chart(ctx, {
      type: 'line',
      data: { datasets: [] },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: { duration: 800, easing: 'easeOutQuart' },
        legend: { display: true, position: 'top', labels: { usePointStyle: true, boxWidth: 3 } },
        tooltips: {
          backgroundColor: '#FFFFFF',
          titleFontColor: '#000000',
          bodyFontColor: '#000000',
          borderColor: 'rgba(0,0,0,0.15)',
          borderWidth: 1,
          displayColors: true,
          intersect: false,
          mode: 'index',
          callbacks: {
            title: function (items, data) {
              const ti = items[0];
              const ds = data.datasets[ti.datasetIndex];
              const pt = ds && ds.data ? ds.data[ti.index] : null;
              const ts = (pt && (pt.t || pt.x)) || ti.xLabel || ti.label;
              const m = (typeof moment !== 'undefined') ? moment(Number(ts)) : null;
              return m && m.isValid()
                ? m.format('YYYY-MM-DD')
                : (ti.label || ti.xLabel || '');
            },
            labelPointStyle: function () { return { PointStyle: 'true', rotation: 0 }; },
            labelColor: function (tooltipItem, chart) {
              const ds = chart.config.data.datasets[tooltipItem.datasetIndex];
              const c = ds.borderColor || '#666';
              return { borderColor: c, backgroundColor: c };
            }
          }
        },
        scales: {
          xAxes: [{
            type: 'time',
            time: {
              tooltipFormat: 'HH:mm',
              displayFormats: { minute: 'HH:mm', hour: 'HH:mm', day: 'YYYY-MM-DD', month: 'MMM' }
            },
            distribution: 'linear',
            scaleLabel: { display: true, labelString: 'Date Time' },
            ticks: { source: 'data' },
            offset: false
          }],
          yAxes: [{ scaleLabel: { display: true, labelString: 'People Count' }, ticks: { beginAtZero: true } }]
        },
        pan: { enabled: true, mode: 'x' },
        zoom: { enabled: true, mode: 'x' },
        elements: { point: { radius: 2, hoverRadius: 5, hitRadius: 6 } }
      }
    });

    // 1) đọc deviceLabel (server attr, fallback shared) -> quyết định mode
    loadDeviceLabelThenMaybeCam().then(() => {
      // 2) listen bus để đổi cam realtime (chỉ edge-type)
      subscribeCamBus();
      // 3) render lần đầu
      self.onDataUpdated();
    });
  };

  self.onResize = function () { if (chart) chart.resize(); };

  self.onDestroy = function () {
    try {
      const bus = (window.top || window).__TB_CAM_BUS__;
      if (bus && bus.off && busHandler) bus.off(busHandler);
    } catch (e) { }
    if (chart) { chart.destroy(); chart = null; }
  };

  self.onDataUpdated = function () {
    if (!chart) return;

    const sub = self.ctx.defaultSubscription;
    const tw = sub?.subscriptionTimewindow;

    let startTime = tw?.minTime || tw?.fixedWindow?.startTimeMs;
    let endTime = tw?.maxTime || tw?.fixedWindow?.endTimeMs;

    // Day mode → dùng full day 00:00–23:59 để không cắt mất data ngoài 7–19h
    if (isDayMode(tw)) {
      const [s0, e24] = getDayWindowFull(tw);
      startTime = s0; endTime = e24;
    }

    const spanDays = (endTime && startTime) ? (endTime - startTime) / (24 * 60 * 60 * 1000) : 0;
    const isYearMode = spanDays >= 300;
    const isMonthMode = !isYearMode && spanDays > 1;
    const isHourlyGapMode = spanDays <= 1;

    let datasets = buildDatasetsFromSubscription(sub, startTime, endTime, {
      isMonthMode, isYearMode, isHourlyGapMode
    });

    // ✅ FILTER
    datasets = filterByDeviceLabelAndCam(datasets);

    chart.data.datasets = datasets;
    applyTimeScaleForWindow(chart, startTime, endTime, { isMonthMode, isYearMode });
    chart.update();
  };

  // =========================
  // Attribute loading
  // =========================

  function resolveEntityId() {
    const ds0 = self.ctx.datasources && self.ctx.datasources[0];
    const ent = ds0 && (ds0.entityId || ds0.entity);
    const uuid = extractUuid(ent) || extractUuid(ds0) || extractUuid(self.ctx.defaultSubscription);
    if (!uuid) return null;
    return { entityType: 'DEVICE', id: uuid };
  }

  function extractUuid(maybe) {
    if (!maybe) return null;
    if (typeof maybe === 'string') return maybe;
    if (typeof maybe.id === 'string') return maybe.id;
    if (maybe.id && typeof maybe.id.id === 'string') return maybe.id.id;
    if (maybe.entityId) return extractUuid(maybe.entityId);
    if (typeof maybe.targetDeviceId === 'string') return maybe.targetDeviceId;
    return null;
  }

  function loadDeviceLabelThenMaybeCam() {
    const entityId = resolveEntityId();
    if (!entityId || !attributeService || !attributeService.getEntityAttributes) {
      return Promise.resolve();
    }

    // ✅ try SERVER_SCOPE first, then SHARED_SCOPE
    return loadDeviceLabel(entityId)
      .then(dl => {
        deviceLabel = dl ? String(dl) : null;

        // edge-type -> đọc cam lần đầu (shared)
        if (deviceLabel === 'edge-type') {
          return loadSharedCam(entityId).then(camVal => {
            selectedCamKey = camVal ? pickCamKeyFromAttrValue(camVal) : null;
          });
        }
      })
      .catch(() => { });
  }

  function loadDeviceLabel(entityId) {
    // 1) server scope
    return attributeService
      .getEntityAttributes(entityId, 'SERVER_SCOPE', [DEVICE_LABEL_KEY])
      .toPromise()
      .then(attrs => {
        const a = (attrs || []).find(x => x && x.key === DEVICE_LABEL_KEY);
        if (a && a.value != null && String(a.value).trim() !== '') return String(a.value);
        // 2) fallback shared scope
        return attributeService
          .getEntityAttributes(entityId, 'SHARED_SCOPE', [DEVICE_LABEL_KEY])
          .toPromise()
          .then(attrs2 => {
            const b = (attrs2 || []).find(x => x && x.key === DEVICE_LABEL_KEY);
            return b ? String(b.value) : null;
          })
          .catch(() => null);
      })
      .catch(() => {
        // if server failed, still try shared
        return attributeService
          .getEntityAttributes(entityId, 'SHARED_SCOPE', [DEVICE_LABEL_KEY])
          .toPromise()
          .then(attrs2 => {
            const b = (attrs2 || []).find(x => x && x.key === DEVICE_LABEL_KEY);
            return b ? String(b.value) : null;
          })
          .catch(() => null);
      });
  }

  function loadSharedCam(entityId) {
    if (!attributeService || !attributeService.getEntityAttributes) return Promise.resolve(null);
    return attributeService
      .getEntityAttributes(entityId, 'SHARED_SCOPE', [CAM_ATTR_KEY])
      .toPromise()
      .then(attrs => {
        const a = (attrs || []).find(x => x && x.key === CAM_ATTR_KEY);
        return a ? String(a.value) : null;
      })
      .catch(() => null);
  }

  // =========================
  // Bus listen for realtime cam changes (NO REST, NO LAG)
  // =========================
  function ensureCamBus() {
    const topWin = window.top || window;
    if (topWin.__TB_CAM_BUS__) return topWin.__TB_CAM_BUS__;

    const listeners = [];
    const bus = {
      last: null,
      on: function (fn) {
        if (typeof fn !== 'function') return;
        listeners.push(fn);
      },
      off: function (fn) {
        const i = listeners.indexOf(fn);
        if (i >= 0) listeners.splice(i, 1);
      },
      emit: function (cam) {
        bus.last = cam;
        listeners.slice().forEach(fn => {
          try { fn({ cam }); } catch (e) { }
        });
      }
    };
    topWin.__TB_CAM_BUS__ = bus;
    return bus;
  }

  function subscribeCamBus() {
    if (deviceLabel !== 'edge-type') return;

    try {
      const bus = ensureCamBus();

      // nhận cam mới nhất nếu có
      if (bus.last != null) {
        selectedCamKey = pickCamKeyFromAttrValue(bus.last);
      }

      busHandler = function (payload) {
        const camVal = payload && payload.cam ? payload.cam : null;
        selectedCamKey = pickCamKeyFromAttrValue(camVal);

        // re-render ngay
        if (chart) {
          chart.data.datasets = [];
          chart.update();
        }
        self.onDataUpdated();
      };

      bus.on(busHandler);
    } catch (e) { }
  }

  // =========================
  // Filtering logic (MAIN)
  // =========================
  function normalizeKeyName(s) {
    return String(s || '')
      .trim()
      .toLowerCase()
      .replace(/\s+/g, '');
  }

  function filterByDeviceLabelAndCam(datasets) {
    if (!Array.isArray(datasets)) return [];

    // tablet-type: vẽ 4 key cố định
    if (deviceLabel === 'tablet-type') {
      const allowed = TABLET_KEYS.map(normalizeKeyName);
      return datasets.filter(ds => allowed.includes(normalizeKeyName(ds.__tbKeyName || ds.label)));
    }

    // edge-type: vẽ theo cam đã chọn (ALL/CAM -> pass_total)
    if (deviceLabel === 'edge-type') {
      if (!selectedCamKey) return [];
      const target = normalizeKeyName(selectedCamKey);
      return datasets.filter(ds => normalizeKeyName(ds.__tbKeyName || ds.label) === target);
    }

    return [];
  }

  // =========================
  // CAM helpers
  // =========================
  function isSpecialCamValue(v) {
    if (v == null) return false;
    const s = String(v).trim().toUpperCase();
    return CAM_SPECIAL_VALUES.includes(s); // "CAM" or "ALL"
  }

  function parseCamNumber(v) {
    if (v == null) return null;

    // ✅ special -> no number
    if (isSpecialCamValue(v)) return null;

    const s = String(v).trim(); // CAM2 / cam2 / 2 / "cam 2"
    const m = s.match(/(\d+)/);
    if (!m) return null;
    const n = Number(m[1]);
    if (!Number.isFinite(n) || n < 1 || n > CAM_COUNT) return null;
    return n;
  }

  function pickCamKeyFromAttrValue(camAttrValue) {
    // ✅ NEW: cam = "ALL" or "CAM" -> hiển thị pass_total
    if (isSpecialCamValue(camAttrValue)) {
      return FALLBACK_KEY_WHEN_CAM_SPECIAL; // "pass_total"
    }

    const n = parseCamNumber(camAttrValue);
    if (!n) return null;
    return `${CAM_KEY_PREFIX}${n}${CAM_KEY_SUFFIX}`;
  }

  // =========================
  // Original helpers (keep same draw style)
  // =========================
  function buildDatasetsFromSubscription(subscription, startTime, endTime, opts) {
    const results = [];
    if (!subscription || !Array.isArray(subscription.data)) return results;

    const { isMonthMode, isYearMode, isHourlyGapMode } = opts || {};
    const fallbackColors = ['#e74c3c', '#27ae60', '#2980b9', '#8e44ad', '#f39c12', '#16a085', '#c0392b', '#2c3e50'];

    subscription.data.forEach((dk, idx) => {
      const key = dk.dataKey || {};
      const label = key.label || key.name || `Series ${idx + 1}`;

      const keyName = (key.name || key.label || label || '').trim();
      const keyNameLower = keyName.toLowerCase();

      const fixedColor =
        FIXED_COLOR_MAP[keyNameLower] ||
        FIXED_COLOR_MAP[keyNameLower.replace(/\s+/g, '')];

      const color = fixedColor || key.color || fallbackColors[idx % fallbackColors.length];

      let points = (dk.data || [])
        .filter(p => (!startTime || p[0] >= startTime) && (!endTime || p[0] <= endTime))
        .map(p => ({ t: Number(p[0]), y: p[1] }));

      if (isHourlyGapMode) {
        points = fillGapsWithNull(points, startTime, endTime, 'hour');
      } else if (isMonthMode) {
        points = fillGapsWithNull(points, startTime, endTime, 'day');
      } else if (isYearMode) {
        points = fillGapsWithNull(points, startTime, endTime, 'month');
      }
      points = stitchZeroBeforeData(points);

      results.push({
        label,
        __tbKeyName: keyName,
        data: points,
        borderColor: color,
        backgroundColor: color,
        fill: false,
        borderWidth: 5,
        lineTension: 0.3,
        spanGaps: false,
        pointRadius: 2,
        pointHitRadius: 6,
        pointHoverRadius: 5,
        pointStyle: 'circle',
        showLine: true
      });
    });

    return results;
  }

  function fillGapsWithNull(data, startTime, endTime, mode) {
    if (!Array.isArray(data) || data.length === 0 || !startTime || !endTime) return data || [];

    const map = {};
    const normKey = (ms) => {
      const x = new Date(ms);
      if (mode === 'hour') return new Date(x.getFullYear(), x.getMonth(), x.getDate(), x.getHours(), 0, 0, 0).getTime();
      if (mode === 'day') return new Date(x.getFullYear(), x.getMonth(), x.getDate(), 0, 0, 0, 0).getTime();
      if (mode === 'month') return new Date(x.getFullYear(), x.getMonth(), 1, 0, 0, 0, 0).getTime();
    };

    data.forEach(p => {
      const ts = normKey(p.t);
      map[ts] = p.y;
    });

    const filled = [];

    if (mode === 'hour') {
      const STEP = 60 * 60 * 1000;
      const start = Math.floor(startTime / STEP) * STEP;
      const end = Math.ceil(endTime / STEP) * STEP;
      for (let t = start; t <= end; t += STEP) {
        filled.push({ t, y: Object.prototype.hasOwnProperty.call(map, t) ? map[t] : null });
      }
      return filled;
    }

    if (mode === 'day') {
      const DAY = 24 * 60 * 60 * 1000;
      const sDate = new Date(startTime);
      const eDate = new Date(endTime);
      const start = new Date(sDate.getFullYear(), sDate.getMonth(), sDate.getDate()).getTime();
      const end = new Date(eDate.getFullYear(), eDate.getMonth(), eDate.getDate()).getTime();
      for (let t = start; t <= end; t += DAY) {
        filled.push({ t, y: Object.prototype.hasOwnProperty.call(map, t) ? map[t] : null });
      }
      return filled;
    }

    if (mode === 'month') {
      const s = new Date(startTime);
      const e = new Date(endTime);
      let cur = new Date(s.getFullYear(), s.getMonth(), 1);
      const endM = new Date(e.getFullYear(), e.getMonth(), 1);
      for (; cur.getTime() <= endM.getTime(); cur.setMonth(cur.getMonth() + 1)) {
        const t = cur.getTime();
        filled.push({ t, y: Object.prototype.hasOwnProperty.call(map, t) ? map[t] : null });
      }
      return filled;
    }

    return data;
  }

  function stitchZeroBeforeData(points) {
    if (!Array.isArray(points) || points.length === 0) return points || [];
    const out = [];
    for (let i = 0; i < points.length; i++) {
      const curr = points[i];
      const prev = i > 0 ? points[i - 1] : null;
      if (prev && prev.y == null && curr.y != null) {
        out.push({ t: prev.t, y: 0 });
      }
      out.push(curr);
    }
    return out;
  }

  function applyTimeScaleForWindow(chart, startTime, endTime, opts) {
    const xAxis = chart.options.scales.xAxes[0];
    const { isMonthMode, isYearMode } = opts || {};
    let minMs = startTime ? Number(startTime) : undefined;
    let maxMs = endTime ? Number(endTime) : undefined;

    if (isDayMode(self.ctx.defaultSubscription?.subscriptionTimewindow)) {
      const s = new Date(minMs);
      const e = new Date(minMs);
      const minDay = new Date(s.getFullYear(), s.getMonth(), s.getDate(), 7, 0, 0, 0).getTime();
      const maxDay = new Date(e.getFullYear(), e.getMonth(), e.getDate(), 19, 0, 0, 0).getTime();
      minMs = minDay;
      maxMs = maxDay;

      xAxis.time.unit = 'hour';
      xAxis.time.stepSize = 1;
      xAxis.time.displayFormats.hour = 'HH:mm';
      xAxis.time.tooltipFormat = 'HH:mm';
      xAxis.offset = false;
    }
    else if (isYearMode) {
      xAxis.time.unit = 'month';
      xAxis.time.stepSize = 1;
      xAxis.time.displayFormats.month = 'MMM';
      xAxis.offset = true;
    }
    else if (isMonthMode) {
      const s = new Date(minMs), e = new Date(maxMs);
      const minDay = new Date(s.getFullYear(), s.getMonth(), s.getDate(), 0, 0, 0, 0).getTime();
      const maxDay = new Date(e.getFullYear(), e.getMonth(), e.getDate(), 23, 59, 59, 999).getTime();
      minMs = minDay; maxMs = maxDay;

      xAxis.time.unit = 'day';
      xAxis.time.stepSize = 1;
      xAxis.time.displayFormats.day = 'MMM DD';
      xAxis.time.tooltipFormat = 'YYYY-MM-DD';
      xAxis.offset = true;
    }
    else {
      xAxis.time.unit = 'hour';
      xAxis.time.stepSize = 1;
      xAxis.time.displayFormats.hour = 'HH:mm';
      xAxis.offset = false;
    }

    xAxis.ticks.min = minMs;
    xAxis.ticks.max = maxMs;
    xAxis.time.min = minMs;
    xAxis.time.max = maxMs;
  }

  function isDayMode(tw) {
    if (!tw) return false;
    const start = tw.minTime || tw.fixedWindow?.startTimeMs;
    const end = tw.maxTime || tw.fixedWindow?.endTimeMs;
    if (!start || !end) return false;
    const ONE_DAY = 24 * 60 * 60 * 1000;
    if (end - start > ONE_DAY + 15 * 60 * 1000) return false;
    const s = new Date(start), e = new Date(end);
    return s.getFullYear() === e.getFullYear() &&
      s.getMonth() === e.getMonth() &&
      s.getDate() === e.getDate();
  }

  function getDayWindowFull(tw) {
    const ref = tw.fixedWindow?.startTimeMs || tw.minTime || Date.now();
    const d = new Date(ref);
    const y = d.getFullYear(), m = d.getMonth(), day = d.getDate();
    const start0 = new Date(y, m, day, 0, 0, 0, 0).getTime();
    const end24 = new Date(y, m, day, 23, 59, 59, 999).getTime();
    return [start0, end24];
  }

})();

