(function ensureCamBus() {
  var topWin = window.top || window;
  if (topWin.__TB_CAM_BUS__) return;

  topWin.__TB_CAM_BUS__ = {
    last: null,
    _listeners: [],
    emit: function (camName) {
      this.last = camName;
      var payload = { cam: camName, ts: Date.now() };
      this._listeners.forEach(function (fn) { try { fn(payload); } catch (e) {} });
    },
    on: function (fn) { if (typeof fn === "function") this._listeners.push(fn); },
    off: function (fn) { this._listeners = this._listeners.filter(function (x) { return x !== fn; }); }
  };
})();

let watchTimer = null;
let activeDeviceId = null;
let seq = 0;

self.onInit = function () {
  self.ctx.ngZone.run(function () {
    initServices();
    initScope();
    startWatchDevice();
    reloadForCurrentDevice();
    self.ctx.detectChanges();
  });
};

self.onDestroy = function () {
  try { if (watchTimer) clearInterval(watchTimer); } catch (e) {}
  watchTimer = null;
};

self.onDataUpdated = function () {
  // ❌ Không build options từ ctx.data để tránh dính device cũ
};

/* ---------------- services ---------------- */

function initServices() {
  const inj = self.ctx.$scope.$injector;

  // attributeService instance
  self.attributeService = inj.get(self.ctx.servicesMap.get("attributeService"));

  // telemetryService instance (tùy version)
  self.telemetryService = null;
  try {
    const tToken =
      (self.ctx.servicesMap && self.ctx.servicesMap.get && (
        self.ctx.servicesMap.get("telemetryService") ||
        self.ctx.servicesMap.get("telemetry")
      )) || null;
    if (tToken) self.telemetryService = inj.get(tToken);
  } catch (e) {
    self.telemetryService = null;
  }

  self.telemetryKey = self.ctx.settings.telemetryKey || "pass_cam";
  self.serverAttrKey = "current_cam";
  self.deviceLabelKey = "deviceLabel";
}

/* ---------------- ui ---------------- */

function initScope() {
  const $s = self.ctx.$scope;

  $s.isHidden = false;
  $s.camOptions = [];
  $s.selectedCam = null;

  $s.onCamSelect = function (camName) {
    if ($s.isHidden) return;
    if (!camName) return;

    // ✅ set ngay UI
    $s.selectedCam = camName;
    self.ctx.detectChanges();

    // ✅ save server + emit bus
    saveServerCam(camName, true);
  };
}

function hideWidget() {
  self.ctx.$scope.isHidden = true;
  try { self.ctx.$container[0].style.display = "none"; } catch (e) {}
  self.ctx.detectChanges();
}

function showWidget() {
  self.ctx.$scope.isHidden = false;
  try { self.ctx.$container[0].style.display = ""; } catch (e) {}
}

/* ---------------- device detect ---------------- */

function resolveEntityIdObj() {
  // Ưu tiên entityId từ defaultSubscription (thường là device đang được state controller chọn)
  const sub = self.ctx.defaultSubscription;
  const id =
    sub?.entityId?.id ||
    sub?.entityId ||
    self.ctx.datasources?.[0]?.entityId?.id ||
    self.ctx.datasources?.[0]?.entityId;

  return id ? { entityType: "DEVICE", id: id } : null;
}

function startWatchDevice() {
  if (watchTimer) clearInterval(watchTimer);

  watchTimer = setInterval(function () {
    try {
      const e = resolveEntityIdObj();
      const id = e?.id || null;
      if (id && id !== activeDeviceId) {
        activeDeviceId = id;
        self.ctx.ngZone.run(function () {
          reloadForCurrentDevice();
          self.ctx.detectChanges();
        });
      }
    } catch (e) {}
  }, 300);
}

/* ---------------- helpers ---------------- */

function normalizeCam(v) {
  if (v == null) return null;
  const s = String(v).trim();
  if (!s) return null;

  // accept: "3", "CAM3", "CAM_3", "CAM 3", "cam_3" -> "CAM_3"
  const m = s.match(/(\d+)/);
  if (!m) return null;
  return "CAM_" + String(parseInt(m[1], 10));
}

/**
 * ✅ Fix mat-select: phải set selected sau khi options đã render
 */
function setSelectedCamAfterOptions(camName) {
  // clear trước để material select không “giữ” selection cũ
  self.ctx.$scope.selectedCam = null;
  self.ctx.detectChanges();

  setTimeout(function () {
    self.ctx.ngZone.run(function () {
      self.ctx.$scope.selectedCam = camName;
      self.ctx.detectChanges();
    });
  }, 0);
}

function clearOptions() {
  self.ctx.$scope.camOptions = [];
  self.ctx.$scope.selectedCam = null;
  self.ctx.detectChanges();
}

/* ---------------- main reload ---------------- */

function reloadForCurrentDevice() {
  const entityId = resolveEntityIdObj();
  if (!entityId) return;

  const curSeq = ++seq;

  // 1) clear ngay khi đổi device
  clearOptions();
  showWidget();

  // 2) đọc SERVER attrs: deviceLabel + current_cam
  self.attributeService
    .getEntityAttributes(entityId, "SERVER_SCOPE", [self.deviceLabelKey, self.serverAttrKey])
    .subscribe(
      function (attrs) {
        if (curSeq !== seq) return;

        const map = {};
        (attrs || []).forEach(a => { if (a && a.key != null) map[a.key] = a.value; });

        const label = map[self.deviceLabelKey] != null ? String(map[self.deviceLabelKey]) : null;
        const currentCam = normalizeCam(map[self.serverAttrKey]);

        // tablet -> ẩn hẳn
        if (label === "tablet-type") {
          hideWidget();
          return;
        }

        // 3) đọc latest telemetry pass_cam -> build options
        fetchLatestPassCam(entityId, curSeq, function (options) {
          if (curSeq !== seq) return;

          self.ctx.ngZone.run(function () {
            self.ctx.$scope.camOptions = options || [];

            if (!self.ctx.$scope.camOptions.length) {
              self.ctx.$scope.selectedCam = null; // dropdown disable
              self.ctx.detectChanges();
              return;
            }

            // 4) default theo current_cam nếu hợp lệ, không thì chọn cam đầu
            const sel = (currentCam && options.includes(currentCam)) ? currentCam : options[0];

            // ✅ FIX: dropdown hiển thị đúng active cam (không rơi về option đầu)
            setSelectedCamAfterOptions(sel);

            // 5) sync server + bus
            if (!currentCam || currentCam !== sel) {
              saveServerCam(sel, true, entityId);
            } else {
              emitBus(sel);
            }
          });
        });
      },
      function () {
        // không đọc được attrs -> vẫn thử telemetry để build list
        fetchLatestPassCam(entityId, curSeq, function (options) {
          if (curSeq !== seq) return;

          self.ctx.ngZone.run(function () {
            self.ctx.$scope.camOptions = options || [];
            if (options && options.length) {
              const sel = options[0];
              setSelectedCamAfterOptions(sel);
              saveServerCam(sel, true, entityId);
            } else {
              self.ctx.$scope.selectedCam = null;
              self.ctx.detectChanges();
            }
          });
        });
      }
    );
}

/* ---------------- telemetry ---------------- */

function fetchLatestPassCam(entityId, curSeq, cb) {
  // ưu tiên telemetryService.getLatestTimeseries
  if (self.telemetryService && self.telemetryService.getLatestTimeseries) {
    self.telemetryService.getLatestTimeseries(entityId, [self.telemetryKey]).subscribe(
      function (data) {
        if (curSeq !== seq) return;
        const arr = data && data[self.telemetryKey];
        const raw = (arr && arr.length) ? arr[0].value : null;
        cb(parseCamOptions(raw));
      },
      function () { cb([]); }
    );
    return;
  }

  // fallback REST
  const key = encodeURIComponent(self.telemetryKey);
  const url = `/api/plugins/telemetry/DEVICE/${entityId.id}/values/timeseries?keys=${key}&limit=1`;
  self.ctx.http.get(url).subscribe(
    function (res) {
      if (curSeq !== seq) return;
      const data = res?.data || res;
      const arr = data && data[self.telemetryKey];
      const raw = (arr && arr.length) ? arr[0].value : null;
      cb(parseCamOptions(raw));
    },
    function () { cb([]); }
  );
}

function parseCamOptions(raw) {
  if (raw == null) return [];

  let obj;
  try { obj = (typeof raw === "string") ? JSON.parse(raw) : raw; }
  catch (e) { return []; }

  if (!obj || typeof obj !== "object") return [];

  return Object.keys(obj)
    .sort((a, b) => (parseInt(a, 10) || 0) - (parseInt(b, 10) || 0))
    .map(k => `CAM_${k}`);
}

/* ---------------- save + bus ---------------- */

function saveServerCam(camName, shouldEmit, entityIdOverride) {
  const entityId = entityIdOverride || resolveEntityIdObj();
  if (!entityId) return;

  self.attributeService
    .saveEntityAttributes(entityId, "SERVER_SCOPE", [{ key: self.serverAttrKey, value: camName }])
    .subscribe(
      function () { if (shouldEmit) emitBus(camName); },
      function () { if (shouldEmit) emitBus(camName); }
    );
}

function emitBus(camName) {
  try {
    var bus = (window.top || window).__TB_CAM_BUS__;
    if (bus && bus.emit) bus.emit(camName);
  } catch (e) {}
}

