.tb-config-merge {
    width: 100%;
    height: 100%;
    background: #ffffff;   /* 👈 đảm bảo nền trắng ngay từ lúc init */
    z-index: 10;
}

.tb-config-merge .title-container {
    font-weight: 500;
    white-space: nowrap;
    margin: 10px 0;
}

.tb-config-merge .form-container {
    width: 100%;
}

.tb-config-merge .mat-mdc-button {
    margin: 0;
}

.tb-config-merge .tablet-widget,
.tb-config-merge .edge-widget {
    width: 100%;
}

/* Unknown Device Styling */
.tb-config-merge .unknown-device-container {
    display: flex;
    justify-content: center;
    align-items: center;
    padding: 24px;
    min-height: 300px;
}

/* 👇 Thêm hiệu ứng delay 0.25s + fade-in */
.tb-config-merge .unknown-device-card {
    background: #fff;
    border: 2px solid #ff9800;
    border-radius: 12px;
    padding: 32px;
    max-width: 600px;
    width: 100%;
    box-shadow: 0 4px 12px rgba(255, 152, 0, 0.1);

    opacity: 0;                       /* ban đầu ẩn */
    animation: unknownFadeIn 0.25s ease forwards;
    animation-delay: 0.25s;           /* ⏱ xuất hiện sau 0.25s */
}

@keyframes unknownFadeIn {
    from { opacity: 0; }
    to   { opacity: 1; }
}

.tb-config-merge .icon-container {
    display: flex;
    justify-content: center;
    margin-bottom: 16px;
}

.tb-config-merge .warning-icon {
    font-size: 64px;
    width: 64px;
    height: 64px;
    color: #ff9800;
}

.tb-config-merge .error-title {
    text-align: center;
    color: #333;
    font-size: 24px;
    font-weight: 600;
    margin: 0 0 16px 0;
}

.tb-config-merge .error-message {
    text-align: center;
    color: #666;
    font-size: 16px;
    margin-bottom: 24px;
    line-height: 1.6;
}

.tb-config-merge .error-message p {
    margin: 8px 0;
}

