self.onInit = function () {
  const ctx = self.ctx;

  const IFRAME_URL = "https://skds1x9p-8009.asse.devtunnels.ms/";
  const PROFILE_KEY = "default";

  const iframe = ctx.$container[0].querySelector("#remoteFrame");
  iframe.src = IFRAME_URL;

  let iframeReady = false;
  let lastDeviceId = null;
  let lastCfgHash = null;

  function getDeviceFromDatasource() {
    const sub = ctx.defaultSubscription;
    const ds = sub && sub.datasources && sub.datasources[0];
    if (!ds) return null;

    let id = null;
    if (ds.entityId) {
      if (typeof ds.entityId === "string") id = ds.entityId;
      else id = ds.entityId.id || ds.entityId.entityId || null;
    }
    const name = ds.entityName || ds.name || (ds.entity && ds.entity.name) || id;
    if (!id) return null;
    return { id, name: name || id };
  }

  function hashString(s) {
    let h = 0;
    for (let i = 0; i < s.length; i++) h = ((h << 5) - h) + s.charCodeAt(i) | 0;
    return String(h);
  }

  function post(payload) {
    if (!iframeReady) return;
    try { iframe.contentWindow.postMessage(payload, "*"); } catch (e) {}
  }

  function fetchStatisticConfig(deviceId, cb) {
    const url =
      `/api/plugins/telemetry/DEVICE/${deviceId}` +
      `/values/attributes/SHARED_SCOPE?keys=statistic_config`;

    ctx.http.get(url).subscribe(
      (resp) => {
        const data = resp.data || resp;
        let raw = null;
        if (Array.isArray(data)) {
          const found = data.find(it => it && it.key === "statistic_config");
          raw = found ? found.value : null;
        }
        cb(null, raw);
      },
      (err) => cb(err, null)
    );
  }

  function sendConfigOnce() {
    const dev = getDeviceFromDatasource();
    if (!dev) return;

    const deviceChanged = dev.id !== lastDeviceId;
    if (deviceChanged) {
      lastDeviceId = dev.id;
      lastCfgHash = null;
    }

    fetchStatisticConfig(dev.id, (err, raw) => {
      if (err || !raw) return;

      const h = hashString(String(raw));
      if (h === lastCfgHash) return;
      lastCfgHash = h;

      // ✅ chỉ gửi 1 message có statistic_config
      post({
        type: "TB_DEVICE_SELECTED",
        profile: PROFILE_KEY,
        deviceId: dev.id,
        deviceName: dev.name,
        statistic_config: raw
      });
    });
  }

  iframe.addEventListener("load", () => {
    iframeReady = true;

    // gửi 3 lần để bắt tay (nhưng chỉ khi có config)
    let tries = 0;
    const t = setInterval(() => {
      sendConfigOnce();
      tries++;
      if (tries >= 3) clearInterval(t);
    }, 600);
  });

  self.onDataUpdated = function () {
    sendConfigOnce();
  };

  self.onDestroy = function () {
    iframeReady = false;
  };
};

