descriptor.templateCss:
.wrapper{
  height:100%;
  display:flex;
  flex-direction:column;
  background:#fff;
  font-family: Inter, system-ui, -apple-system, Segoe UI, Roboto, Arial, sans-serif;
}

/* ===== Toolbar layout (CRUD + Camera + ROI same row) ===== */
.toolbar{
  background:#fff;
  border-bottom:1px solid #eee;
  padding:10px 12px;
}

.toolbar-row{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:12px;
  flex-wrap:wrap;
}

.toolbar-left{
  display:flex;
  align-items:center;
  gap:10px;
  flex-wrap:wrap;
}

.toolbar-right{
  display:flex;
  align-items:center;
  justify-content:flex-end;
  gap:10px;
  flex-wrap:wrap;
}

.cam-box{
  display:flex;
  align-items:center;
  gap:8px;
  padding:6px 8px;
  border:1px solid #eee;
  border-radius:10px;
  background:#fff;
}
.cam-label{ font-size:13px; color:#111827; }

.cam-dd{
  min-width:150px;
  height:34px;
  border:1px solid #e5e7eb;
  border-radius:8px;
  padding:0 10px;
  background:#fff;
  outline:none;
}
.cam-dd:focus{
  border-color:#2563eb;
  box-shadow:0 0 0 3px rgba(37,99,235,.15);
}

/* ROI switch inline with toolbar */
.roi-switch{
  display:none;
  gap:6px;
  padding:6px;
  border:1px solid #eee;
  border-radius:10px;
  background:#fff;
}
.roi-btn{
  height:32px;
  padding:0 12px;
  border:1px solid #e5e7eb;
  background:#fff;
  border-radius:999px;
  cursor:pointer;
  font-size:13px;
}
.roi-btn.active{
  border-color:#2563eb;
  box-shadow:0 0 0 3px rgba(37,99,235,.15);
}

/* ===== Stage ===== */
.stage{
  flex:1;
  position:relative;
  min-height:0;
  background:#fff;
}
.stage canvas{
  position:absolute;
  inset:0;
  width:100%;
  height:100%;
  display:block;
  cursor:crosshair;
  background:#fff;
}

/* ===== Loading overlay ===== */
.loading-overlay{
  position:absolute;
  inset:0;
  display:none;
  align-items:center;
  justify-content:center;
  background:rgba(17,24,39,.28);
  z-index:25;
  pointer-events:none;
}
.stage.is-loading .loading-overlay{
  display:flex;
}
.loading-card{
  display:flex;
  align-items:center;
  gap:12px;
  padding:14px 16px;
  border-radius:14px;
  background:rgba(255,255,255,.92);
  box-shadow:0 14px 30px rgba(0,0,0,.18);
  color:#111827;
  font-size:14px;
  font-weight:600;
}
.spinner{
  width:18px;
  height:18px;
  border-radius:999px;
  border:3px solid rgba(17,24,39,.20);
  border-top-color: rgba(17,24,39,.80);
  animation: spin .8s linear infinite;
}
@keyframes spin{ from{transform:rotate(0deg)} to{transform:rotate(360deg)} }

/* ===== Button animation ===== */
.tb-btn{ transition: transform .12s ease, box-shadow .12s ease; }
.tb-btn.is-working{ animation: tbPulse .7s ease-in-out infinite; }
.tb-btn.is-success{ animation: tbPop .25s ease-out, tbGlowSuccess .9s ease-out; }
.tb-btn.is-error{ animation: tbShake .25s ease-in-out, tbGlowError .9s ease-out; }

@keyframes tbPulse{ 0%{transform:scale(1)} 50%{transform:scale(1.03)} 100%{transform:scale(1)} }
@keyframes tbPop{ 0%{transform:scale(1)} 60%{transform:scale(1.06)} 100%{transform:scale(1)} }
@keyframes tbShake{ 0%{transform:translateX(0)} 25%{transform:translateX(-3px)} 50%{transform:translateX(3px)} 75%{transform:translateX(-2px)} 100%{transform:translateX(0)} }
@keyframes tbGlowSuccess{ 0%{box-shadow:0 0 0 rgba(0,0,0,0)} 30%{box-shadow:0 0 0 3px rgba(34,197,94,.28)} 100%{box-shadow:0 0 0 rgba(0,0,0,0)} }
@keyframes tbGlowError{ 0%{box-shadow:0 0 0 rgba(0,0,0,0)} 30%{box-shadow:0 0 0 3px rgba(239,68,68,.28)} 100%{box-shadow:0 0 0 rgba(0,0,0,0)} }

/* ===== Toast ===== */
.toast-center{
  position:absolute;
  left:50%;
  top:25%;
  transform:translateX(-50%);
  z-index: 30;
  pointer-events:none;
}
.toast{
  min-width: 460px;
  max-width: 720px;
  padding:14px 18px;
  border-radius:14px;
  color:#fff;
  font-size:14px;
  line-height:1.35;
  text-align:center;
  box-shadow: 0 12px 28px rgba(0,0,0,.18);
  opacity:0;
  transform: translate(-50%, 12px) scale(1.02);
  animation: toastIn .18s ease-out forwards, toastOut 1.0s ease-in forwards;
  animation-delay: 0s, 1.55s;
  position: relative;
  left: 50%;
}
.toast.success{ background: rgba(34,197,94,.92); }
.toast.error{ background: rgba(239,68,68,.92); }
.toast.info{ background: rgba(59,130,246,.92); }
.toast.warn{ background: rgba(245,158,11,.92); }

@keyframes toastIn{ from {opacity:0; transform: translate(-50%, 14px) scale(1.02);} to {opacity:1; transform: translate(-50%, 0) scale(1.04);} }
@keyframes toastOut{ from {opacity:1; transform: translate(-50%, 0) scale(1.04);} to {opacity:0; transform: translate(-50%, -18px) scale(1.00);} }

descriptor.controllerScript:
self.onInit = function () {
  const $injector = self.ctx.$scope.$injector;
  const attributeService = $injector.get(self.ctx.servicesMap.get('attributeService'));

  const ds = self.ctx.datasources?.[0];
  self._entityId = ds?.entity?.id;
  if (!self._entityId) {
    console.error('No datasource entity. Please select Entity alias.');
    return;
  }

  const $c = self.ctx.$container;
  const stageEl = $c.find('.stage')[0];
  const canvasEl = $c.find('canvas')[0];
  const camBoxEl = $c.find('.cam-box')[0];
  const selectEl = $c.find('.cam-dd')[0];
  const roiSwitchEl = $c.find('.roi-switch')[0];
  const roiBtns = Array.from($c.find('.roi-btn'));
  const toastCenter = $c.find('.toast-center')[0];

  const btnSaveEl   = $c.find('.btn-save')[0];
  const btnUndoEl   = $c.find('.btn-undo')[0];
  const btnClearEl  = $c.find('.btn-clear')[0];
  const btnReloadEl = $c.find('.btn-reload')[0];

  const g = canvasEl.getContext('2d');

  self._mode = 'default'; // tablet | edge | default
  self._deviceLabel = null;

  self._cams = [];
  self._activeCam = null; // only for edge

  self._bgImg = new Image();
  self._bgReady = false;
  self._lastSrc = null;

  self._imgDraw = { offX: 0, offY: 0, drawW: 0, drawH: 0 };

  self._tabletPair = []; // [{x,y}] or [{x,y},{x,y}]

  self._roisNorm = { Detect: [], Region1: [], Region2: [] };
  self._activeRoiName = 'Detect';

  self._pending = null;

  const ROI_COLOR = { Detect:'#FFD400', Region1:'#22C55E', Region2:'#EF4444' };

  // Poll control (avoid concurrent polls)
  self._pollToken = 0;

  /* ===== Toast ===== */
  function toast(type, msg) {
    if (!toastCenter) return;
    const el = document.createElement('div');
    el.className = `toast ${type || 'info'}`;
    el.textContent = msg;
    toastCenter.appendChild(el);
    setTimeout(() => { try { toastCenter.removeChild(el); } catch (e) {} }, 2700);
  }

  /* ===== Loading ===== */
  function setLoading(on) {
    if (!stageEl) return;
    stageEl.classList.toggle('is-loading', !!on);
  }
  function sleep(ms){ return new Promise(r => setTimeout(r, ms)); }

  function getStageWH() { return { w: stageEl.clientWidth, h: stageEl.clientHeight }; }

  // trắng ngay khi chờ cam khác
  function blankWhite() {
    const { w: stageW, h: stageH } = getStageWH();
    g.save();
    g.clearRect(0, 0, stageW, stageH);
    g.fillStyle = '#fff';
    g.fillRect(0, 0, stageW, stageH);
    g.restore();
  }

  /* ===== Button feedback (Undo silent) ===== */
  function setBtnState(btn, state) {
    if (!btn) return;
    btn.classList.remove('is-working','is-success','is-error');
    if (state) {
      btn.classList.add(state);
      if (state === 'is-success' || state === 'is-error') {
        setTimeout(() => btn.classList.remove(state), 900);
      }
    }
  }

  function runWithFeedback(btn, actionName, fn, opts) {
    const silent = !!(opts && opts.silent);
    try {
      setBtnState(btn, 'is-working');
      const res = fn();
      if (res && typeof res.then === 'function') {
        return res.then(() => {
          setBtnState(btn, null);
          setBtnState(btn, 'is-success');
          if (!silent) toast('success', `${actionName} succeeded.`);
        }).catch((e) => {
          setBtnState(btn, null);
          setBtnState(btn, 'is-error');
          if (!silent) toast('error', e?.message ? e.message : `${actionName} failed.`);
        });
      } else {
        setBtnState(btn, null);
        setBtnState(btn, 'is-success');
        if (!silent) toast('success', `${actionName} succeeded.`);
      }
    } catch (e) {
      setBtnState(btn, null);
      setBtnState(btn, 'is-error');
      if (!silent) toast('error', e?.message ? e.message : `${actionName} failed.`);
    }
  }

  /* ===== Utils ===== */
  function clamp01(n) { return Math.max(0, Math.min(1, n)); }

  function computeImageDrawRect(stageW, stageH) {
    if (!self._bgReady) return self._imgDraw = { offX: 0, offY: 0, drawW: 0, drawH: 0 };
    const imgW = self._bgImg.naturalWidth || 1;
    const imgH = self._bgImg.naturalHeight || 1;
    const scale = Math.min(stageW / imgW, stageH / imgH);
    const drawW = imgW * scale;
    const drawH = imgH * scale;
    const offX = (stageW - drawW) / 2;
    const offY = (stageH - drawH) / 2;
    return self._imgDraw = { offX, offY, drawW, drawH };
  }

  function evToPointOnImageNorm(ev) {
    const { w: stageW, h: stageH } = getStageWH();
    const r = canvasEl.getBoundingClientRect();
    const xCss = ev.clientX - r.left;
    const yCss = ev.clientY - r.top;
    const { offX, offY, drawW, drawH } = computeImageDrawRect(stageW, stageH);
    if (drawW <= 0 || drawH <= 0) return null;
    if (xCss < offX || xCss > offX + drawW || yCss < offY || yCss > offY + drawH) return null;
    return { x: clamp01((xCss - offX) / drawW), y: clamp01((yCss - offY) / drawH) };
  }

  function normToPixelFlat(pointsNorm) {
    const imgW = self._bgImg.naturalWidth || 1;
    const imgH = self._bgImg.naturalHeight || 1;
    const flat = [];
    for (const p of pointsNorm) flat.push(Math.round(p.x * imgW), Math.round(p.y * imgH));
    return flat;
  }

  function pixelFlatToNorm(flat) {
    const imgW = self._bgImg.naturalWidth || 1;
    const imgH = self._bgImg.naturalHeight || 1;
    const pts = [];
    for (let i = 0; i + 1 < flat.length; i += 2) {
      pts.push({ x: clamp01(Number(flat[i]) / imgW), y: clamp01(Number(flat[i + 1]) / imgH) });
    }
    return pts;
  }

  /* ===== Mode UI ===== */
  function applyModeUI() {
    camBoxEl.style.display = (self._mode === 'tablet') ? 'none' : 'flex';

    if (self._mode === 'edge') {
      roiSwitchEl.style.display = 'flex';
      setActiveRoi(self._activeRoiName || 'Detect');
    } else {
      roiSwitchEl.style.display = 'none';
    }
  }

  function setActiveRoi(name) {
    self._activeRoiName = name;
    roiBtns.forEach(btn => btn.classList.toggle('active', btn.dataset.roi === name));
    redraw();
  }

  roiBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      if (self._mode !== 'edge') return;
      setActiveRoi(btn.dataset.roi);
    });
  });

  /* ===== Render ===== */
  function redraw() {
    const { w: stageW, h: stageH } = getStageWH();
    g.clearRect(0, 0, stageW, stageH);
    if (!self._bgReady) return;

    const rect = computeImageDrawRect(stageW, stageH);
    g.drawImage(self._bgImg, rect.offX, rect.offY, rect.drawW, rect.drawH);

    if (self._mode === 'edge') {
      drawRoi(self._roisNorm.Detect,  'Detect',  self._activeRoiName === 'Detect');
      drawRoi(self._roisNorm.Region1, 'Region1', self._activeRoiName === 'Region1');
      drawRoi(self._roisNorm.Region2, 'Region2', self._activeRoiName === 'Region2');
    } else {
      drawTabletSingleLine(self._tabletPair);
    }
  }

  function drawTabletSingleLine(pair) {
    if (!pair || !pair.length) return;
    const r = self._imgDraw;

    g.save();
    g.strokeStyle = 'red';
    g.fillStyle = 'red';
    g.lineWidth = 2.6;

    if (pair.length === 2) {
      const p1 = pair[0], p2 = pair[1];
      g.beginPath();
      g.moveTo(r.offX + p1.x * r.drawW, r.offY + p1.y * r.drawH);
      g.lineTo(r.offX + p2.x * r.drawW, r.offY + p2.y * r.drawH);
      g.stroke();
    }

    for (let i = 0; i < pair.length; i++) {
      const p = pair[i];
      const cx = r.offX + p.x * r.drawW;
      const cy = r.offY + p.y * r.drawH;
      g.beginPath();
      g.arc(cx, cy, 4.5, 0, Math.PI * 2);
      g.fill();
    }

    g.restore();
  }

  function drawRoi(pointsNorm, name, isActive) {
    if (!pointsNorm || !pointsNorm.length) return;
    const r = self._imgDraw;
    const color = ROI_COLOR[name] || 'red';

    g.save();
    g.strokeStyle = color;
    g.fillStyle = color;
    g.lineWidth = isActive ? 2.8 : 1.6;
    g.globalAlpha = isActive ? 1 : 0.55;

    if (pointsNorm.length >= 3) {
      g.save();
      g.globalAlpha = isActive ? 0.18 : 0.10;
      g.beginPath();
      g.moveTo(r.offX + pointsNorm[0].x * r.drawW, r.offY + pointsNorm[0].y * r.drawH);
      for (let i = 1; i < pointsNorm.length; i++) {
        g.lineTo(r.offX + pointsNorm[i].x * r.drawW, r.offY + pointsNorm[i].y * r.drawH);
      }
      g.closePath();
      g.fill();
      g.restore();
    }

    if (pointsNorm.length >= 2) {
      g.beginPath();
      g.moveTo(r.offX + pointsNorm[0].x * r.drawW, r.offY + pointsNorm[0].y * r.drawH);
      for (let i = 1; i < pointsNorm.length; i++) {
        g.lineTo(r.offX + pointsNorm[i].x * r.drawW, r.offY + pointsNorm[i].y * r.drawH);
      }
      g.stroke();
    }

    for (let i = 0; i < pointsNorm.length; i++) {
      const p = pointsNorm[i];
      const cx = r.offX + p.x * r.drawW;
      const cy = r.offY + p.y * r.drawH;
      g.beginPath();
      g.arc(cx, cy, 4, 0, Math.PI * 2);
      g.fill();
    }
    g.restore();
  }

  /* ===== Resize (DPR) ===== */
  const resize = () => {
    const rect = stageEl.getBoundingClientRect();
    const dpr = window.devicePixelRatio || 1;
    canvasEl.width = Math.max(1, Math.floor(rect.width * dpr));
    canvasEl.height = Math.max(1, Math.floor(rect.height * dpr));
    g.setTransform(dpr, 0, 0, dpr, 0, 0);
    redraw();
  };
  self._ro = new ResizeObserver(resize);
  self._ro.observe(stageEl);
  resize();

  /* ===== Telemetry pass_cam (edge only) ===== */
  function readPassCamFromTelemetry() {
    const dataArr = self.ctx.data || [];
    const entry = dataArr.find(d => d?.dataKey?.name === 'pass_cam');
    if (!entry || !entry.data || !entry.data.length) return null;
    let v = entry.data[0][1];
    if (v == null || v === '') return null;
    if (typeof v === 'string') { try { v = JSON.parse(v); } catch { return null; } }
    return v;
  }

  function updateCamsFromTelemetry() {
    const obj = readPassCamFromTelemetry();
    if (!obj || typeof obj !== 'object') {
      self._cams = [];
      selectEl.innerHTML = '<option value="">No camera</option>';
      return;
    }
    const camIds = Object.keys(obj).sort((a,b)=>Number(a)-Number(b));
    self._cams = camIds;

    selectEl.innerHTML = '';
    camIds.forEach(id => {
      const opt = document.createElement('option');
      opt.value = id;
      opt.textContent = `Cam ${id}`;
      selectEl.appendChild(opt);
    });

    const next = (self._activeCam && camIds.includes(self._activeCam)) ? self._activeCam : camIds[0];
    selectEl.value = next;
    if (next && next !== self._activeCam) setActiveCam(next);
  }

  selectEl.addEventListener('change', () => {
    const camId = selectEl.value;
    if (camId) setActiveCam(camId);
  });

  /* ===== Trigger + wait + fetch latest (tablet/default) ===== */
  function triggerGetFrameTimestamp() {
    const ts = Date.now();
    return new Promise((resolve, reject) => {
      attributeService.saveEntityAttributes(self._entityId, 'SHARED_SCOPE', [
        { key: 'get_frame_cam', value: ts }
      ]).subscribe(() => resolve(ts), err => reject(err));
    });
  }

  async function refreshLatestFrameTabletDefault() {
    setLoading(true);
    try {
      await triggerGetFrameTimestamp();
      await sleep(2000);
      fetchFrame(); // read SERVER_SCOPE once
    } catch (e) {
      setLoading(false);
      toast('error', e?.message || 'Failed to request frame.');
    }
  }

  /* ===== NEW: edge switch cam -> send camId to get_frame_cam and wait for new frame ===== */
  function triggerGetFrameByCamId(camId) {
    return new Promise((resolve, reject) => {
      attributeService.saveEntityAttributes(self._entityId, 'SHARED_SCOPE', [
        { key: 'get_frame_cam', value: String(camId) }
      ]).subscribe(() => resolve(), err => reject(err));
    });
  }

  function readFrameValueOnce(camId) {
    return new Promise((resolve, reject) => {
      const key = `frame_cam${camId}`;
      attributeService.getEntityAttributes(self._entityId, 'SERVER_SCOPE', [key])
        .subscribe(attrs => {
          const a = (attrs || []).find(x => x.key === key);
          resolve(a?.value || null);
        }, err => reject(err));
    });
  }

  async function requestAndWaitFrameEdge(camId, prevValue) {
    const myToken = ++self._pollToken;

    // show white + loading immediately
    self._bgReady = false;
    setLoading(true);
    blankWhite();

    try {
      await triggerGetFrameByCamId(camId);
    } catch (e) {
      setLoading(false);
      throw new Error(e?.message || 'Failed to request frame.');
    }

    // poll until value changes (or first non-empty if prev empty)
    const maxWaitMs = 12000;
    const intervalMs = 400;
    const start = Date.now();

    while (true) {
      if (myToken !== self._pollToken) return; // cancelled by newer switch

      let v = null;
      try { v = await readFrameValueOnce(camId); } catch (e) { v = null; }

      if (v && (!prevValue || v !== prevValue)) {
        fetchFrame(); // will setFrameSrc() and turn off loading on onload
        return;
      }

      if (Date.now() - start >= maxWaitMs) {
        setLoading(false);
        throw new Error('Timeout waiting for new frame from selected camera.');
      }

      await sleep(intervalMs);
    }
  }

  /* ===== deviceLabel ===== */
  function loadDeviceLabel() {
    attributeService.getEntityAttributes(self._entityId, 'SERVER_SCOPE', ['deviceLabel'])
      .subscribe(attrs => {
        const a = (attrs || []).find(x => x.key === 'deviceLabel');
        const label = a?.value;

        self._deviceLabel = label;
        if (label === 'tablet-type') self._mode = 'tablet';
        else if (label === 'edge-type') self._mode = 'edge';
        else self._mode = 'default';

        applyModeUI();

        if (self._mode === 'edge') {
          updateCamsFromTelemetry(); // will setActiveCam(first cam)
        } else {
          refreshLatestFrameTabletDefault();
        }
      }, () => {});
  }

  /* =======================================================================================
   *  statistic_config (SHARED_SCOPE)
   * ======================================================================================= */
  function getCamStatId() {
    return self._activeCam ? `CAM_${self._activeCam}` : null;
  }

  function readStatisticConfigShared() {
    return new Promise((resolve, reject) => {
      attributeService.getEntityAttributes(self._entityId, 'SHARED_SCOPE', ['statistic_config'])
        .subscribe(attrs => {
          const a = (attrs || []).find(x => x.key === 'statistic_config');
          if (!a || a.value == null || a.value === '') { resolve(null); return; }
          let v = a.value;
          if (typeof v === 'string') { try { v = JSON.parse(v); } catch { /* keep raw */ } }
          resolve(v);
        }, err => reject(err));
    });
  }

  function writeStatisticConfigShared(cfg) {
    return new Promise((resolve, reject) => {
      attributeService.saveEntityAttributes(self._entityId, 'SHARED_SCOPE', [
        { key: 'statistic_config', value: cfg }
      ]).subscribe(() => resolve(), err => reject(err));
    });
  }

  function applyLoadedFromStatisticConfig(cfg) {
    if (self._mode === 'edge') {
      const camStatId = getCamStatId();
      if (!camStatId || !Array.isArray(cfg)) {
        self._roisNorm = { Detect: [], Region1: [], Region2: [] };
        redraw();
        return;
      }

      const item = cfg.find(x => x && x.id === camStatId) || cfg.find(x => x && x.id === String(camStatId));
      const p = item?.point;

      if (Array.isArray(p) && Array.isArray(p[0])) {
        const d  = Array.isArray(p[0]) ? p[0] : [];
        const r1 = Array.isArray(p[1]) ? p[1] : [];
        const r2 = Array.isArray(p[2]) ? p[2] : [];
        self._roisNorm.Detect  = pixelFlatToNorm(d);
        self._roisNorm.Region1 = pixelFlatToNorm(r1);
        self._roisNorm.Region2 = pixelFlatToNorm(r2);
      } else {
        self._roisNorm = { Detect: [], Region1: [], Region2: [] };
      }

      redraw();
      return;
    }

    if (cfg && typeof cfg === 'object' && !Array.isArray(cfg)) {
      const flat = Array.isArray(cfg.points) ? cfg.points : [];
      const pts = pixelFlatToNorm(flat);
      self._tabletPair = pts.slice(0, 2);
    } else {
      self._tabletPair = [];
    }
    redraw();
  }

  function loadShared() {
    return new Promise((resolve, reject) => {
      readStatisticConfigShared().then(cfg => {
        if (!cfg) {
          self._tabletPair = [];
          self._roisNorm = { Detect: [], Region1: [], Region2: [] };
          self._pending = null;
          redraw();
          resolve();
          return;
        }

        if (!self._bgReady) { self._pending = cfg; resolve(); return; }

        applyLoadedFromStatisticConfig(cfg);
        resolve();
      }).catch(reject);
    });
  }

  function saveShared() {
    return new Promise((resolve, reject) => {
      if (self._mode === 'edge') {
        if (!self._activeCam) { reject(new Error('No camera selected.')); return; }
      }

      if (!self._bgReady) {
        reject(new Error('Frame is loading. Please try again.'));
        return;
      }

      readStatisticConfigShared().then(cfg => {
        // EDGE
        if (self._mode === 'edge') {
          const ok =
            (self._roisNorm.Detect.length >= 3) &&
            (self._roisNorm.Region1.length >= 3) &&
            (self._roisNorm.Region2.length >= 3);

          if (!ok) {
            reject(new Error('You must draw 3 ROIs (Detect, Region1, Region2), each with at least 3 points.'));
            return;
          }

          const camStatId = getCamStatId();
          const newPoint = [
            normToPixelFlat(self._roisNorm.Detect),
            normToPixelFlat(self._roisNorm.Region1),
            normToPixelFlat(self._roisNorm.Region2)
          ];

          // ✅ missing/empty => create array
          if (cfg == null || cfg === '') cfg = [];
          if (typeof cfg === 'string') { try { cfg = JSON.parse(cfg); } catch { /* ignore */ } }
          if (!Array.isArray(cfg)) cfg = [];

          let idx = cfg.findIndex(x => x && x.id === camStatId);
          if (idx < 0) cfg.push({ id: camStatId, point: newPoint });
          else cfg[idx].point = newPoint;

          writeStatisticConfigShared(cfg).then(resolve).catch(reject);
          return;
        }

        // TABLET/DEFAULT
        if (!self._tabletPair || self._tabletPair.length !== 2) {
          reject(new Error('Please select 2 points to create a line.'));
          return;
        }

        const newPoints = normToPixelFlat(self._tabletPair);

        if (cfg == null || cfg === '') cfg = {};
        if (typeof cfg === 'string') { try { cfg = JSON.parse(cfg); } catch { cfg = {}; } }
        if (Array.isArray(cfg) || typeof cfg !== 'object') cfg = {};

        cfg.points = newPoints;

        writeStatisticConfigShared(cfg).then(resolve).catch(reject);
      }).catch(reject);
    });
  }

  /* ===== Frame fetch ===== */
  function setFrameSrc(val) {
    let src = val;
    if (typeof val === 'string' && !val.startsWith('data:image')) {
      src = 'data:image/jpeg;base64,' + val;
    }
    if (self._lastSrc === src) {
      setLoading(false);
      return;
    }

    self._lastSrc = src;
    self._bgReady = false;

    self._bgImg.onload = () => {
      self._bgReady = true;
      setLoading(false);

      if (self._pending != null) {
        applyLoadedFromStatisticConfig(self._pending);
        self._pending = null;
      }

      redraw();
    };

    self._bgImg.onerror = () => {
      self._bgReady = false;
      setLoading(false);
      toast('error', 'Failed to load frame image.');
    };

    self._bgImg.src = src;
  }

  function fetchFrame() {
    if (self._mode === 'tablet' || self._mode === 'default') {
      attributeService.getEntityAttributes(self._entityId, 'SERVER_SCOPE', ['frame_base64'])
        .subscribe(attrs => {
          const a = (attrs || []).find(x => x.key === 'frame_base64');
          if (a?.value) setFrameSrc(a.value);
          else setLoading(false);
        }, () => setLoading(false));
      return;
    }

    if (!self._activeCam) { setLoading(false); return; }
    const key = `frame_cam${self._activeCam}`;
    attributeService.getEntityAttributes(self._entityId, 'SERVER_SCOPE', [key])
      .subscribe(attrs => {
        const a = (attrs || []).find(x => x.key === key);
        if (a?.value) setFrameSrc(a.value);
        else setLoading(false);
      }, () => setLoading(false));
  }

  async function setActiveCam(camId) {
    if (!camId || self._activeCam === camId) return;

    // cancel any previous waiting
    self._pollToken++;

    // store previous frame value for that cam (optional to detect change)
    let prev = null;
    try { prev = await readFrameValueOnce(camId); } catch (e) { prev = null; }

    self._activeCam = camId;

    self._tabletPair = [];
    self._roisNorm = { Detect: [], Region1: [], Region2: [] };
    self._pending = null;
    self._lastSrc = null;

    // show white + loading immediately
    self._bgReady = false;
    setLoading(true);
    blankWhite();

    loadShared().catch(() => {});

    if (self._mode === 'edge') {
      // ✅ NEW: send camId to get_frame_cam and wait until frame_cam{camId} updates
      try {
        await requestAndWaitFrameEdge(camId, prev);
      } catch (e) {
        toast('error', e?.message || 'Failed to load new frame.');
      }
      return;
    }

    // tablet/default: original behavior
    refreshLatestFrameTabletDefault();
  }

  /* ===== Click add point ===== */
  function onClickAddPoint(ev) {
    const p = evToPointOnImageNorm(ev);
    if (!p) return;

    if (self._mode === 'edge') {
      self._roisNorm[self._activeRoiName].push(p);
      redraw();
      return;
    }

    if (!self._tabletPair) self._tabletPair = [];
    if (self._tabletPair.length === 0) self._tabletPair = [p];
    else if (self._tabletPair.length === 1) self._tabletPair = [self._tabletPair[0], p];
    else self._tabletPair = [p];

    redraw();
  }

  canvasEl.addEventListener('click', onClickAddPoint);
  self._onClickAddPoint = onClickAddPoint;

  /* ===== Toolbar actions ===== */
  self.ctx.$scope.savePolygon = () => runWithFeedback(btnSaveEl, 'Save', () => saveShared());

  self.ctx.$scope.undoPoint = () => runWithFeedback(btnUndoEl, 'Undo', () => {
    if (self._mode === 'edge') {
      const arr = self._roisNorm[self._activeRoiName];
      if (arr.length) arr.pop();
    } else {
      if (self._tabletPair && self._tabletPair.length) self._tabletPair.pop();
    }
    redraw();
  }, { silent: true });

  self.ctx.$scope.clearAll = () => runWithFeedback(btnClearEl, 'Clear', () => {
    if (self._mode === 'edge') self._roisNorm[self._activeRoiName] = [];
    else self._tabletPair = [];
    redraw();
  });

  self.ctx.$scope.reloadSaved = () => runWithFeedback(btnReloadEl, 'Reload', async () => {
    await loadShared();

    if (self._mode === 'edge') {
      // reload means request current cam frame again
      try {
        let prev = null;
        try { prev = await readFrameValueOnce(self._activeCam); } catch (e) { prev = null; }
        await requestAndWaitFrameEdge(self._activeCam, prev);
      } catch (e) {
        toast('error', e?.message || 'Failed to load new frame.');
      }
    } else {
      await refreshLatestFrameTabletDefault();
    }
  });

  /* ===== Start ===== */
  loadDeviceLabel();
  loadShared().catch(() => {});
};

self.onDataUpdated = function () {
  try {
    if (self._mode !== 'edge') return;

    const dataArr = self.ctx.data || [];
    const entry = dataArr.find(d => d?.dataKey?.name === 'pass_cam');
    if (!entry || !entry.data?.length) return;

    let v = entry.data[0][1];
    if (typeof v === 'string') { try { v = JSON.parse(v); } catch { return; } }
    if (!v || typeof v !== 'object') return;

    const camIds = Object.keys(v).sort((a,b)=>Number(a)-Number(b));
    const sel = self.ctx.$container.find('.cam-dd')[0];
    if (!sel) return;

    sel.innerHTML = '';
    if (!camIds.length) {
      sel.innerHTML = '<option value="">No camera</option>';
      self._activeCam = null;
      return;
    }

    camIds.forEach(id => {
      const opt = document.createElement('option');
      opt.value = id;
      opt.textContent = `Cam ${id}`;
      sel.appendChild(opt);
    });

    const next = (self._activeCam && camIds.includes(self._activeCam)) ? self._activeCam : camIds[0];
    sel.value = next;

    if (next !== self._activeCam) {
      self._activeCam = null;
      sel.dispatchEvent(new Event('change'));
    }
  } catch (e) {}
};

self.onDestroy = function () {
  try {
    if (self._ro) self._ro.disconnect();
    if (self._onClickAddPoint) {
      self.ctx.$container.find('canvas')[0].removeEventListener('click', self._onClickAddPoint);
    }
    self._pollToken++; // cancel poll
  } catch (e) {}
};

