descriptor.controllerScript:
self.onInit = function () {
  const el = self.ctx.$container[0];
  self.$img = el.querySelector('#img');
  self.$info = el.querySelector('#info');
  self.$btnRender = el.querySelector('#btnRender');
  self.$btnClear = el.querySelector('#btnClear');

  self._lastObjectUrl = null;
  self._latestKv = {};

  function setInfo(msg) { self.$info.textContent = msg; }

  function clearImage() {
    self.$img.removeAttribute('src');
    if (self._lastObjectUrl) {
      URL.revokeObjectURL(self._lastObjectUrl);
      self._lastObjectUrl = null;
    }
  }

  // ✅ Khi ảnh load xong, lấy resolution
  self.$img.onload = function () {
    const w = self.$img.naturalWidth;
    const h = self.$img.naturalHeight;
    setInfo(self.$info.textContent + `\nResolution: ${w} x ${h}`);
  };

  self.$img.onerror = function () {
    setInfo(self.$info.textContent + "\n\n<img> failed to render (broken/truncated JPEG).");
  };

  function hexToUint8Array(hex) {
    const clean = (hex || '').replace(/\s+/g, '').toLowerCase();
    if (!clean) throw new Error('Empty hex string.');
    if (clean.length % 2 !== 0) throw new Error('Hex length is odd.');
    if (!/^[0-9a-f]+$/.test(clean)) throw new Error('Hex has invalid chars.');
    const out = new Uint8Array(clean.length / 2);
    for (let i = 0; i < clean.length; i += 2) out[i / 2] = parseInt(clean.substr(i, 2), 16);
    return out;
  }

  function getHex() {
    const v = self._latestKv['frame_hex_full'] || self._latestKv['frame_hex'];
    if (!v) throw new Error('Missing attribute: frame_hex_full (or frame_hex).');
    return v;
  }

  function render() {
    try {
      const hex = getHex();
      const clean = hex.replace(/\s+/g, '');
      const head16 = clean.slice(0, 16);
      const tail16 = clean.slice(-16);

      let msg =
        `Key found: ${self._latestKv['frame_hex_full'] ? 'frame_hex_full' : 'frame_hex'}\n` +
        `Hex chars (widget): ${clean.length}\n` +
        `Head16: ${head16}\n` +
        `Tail16: ${tail16}\n` +
        `SOI ffd8: ${head16.startsWith('ffd8')}\n` +
        `EOI ffd9: ${tail16.endsWith('ffd9')}\n`;

      const bytes = hexToUint8Array(clean);
      msg += `Bytes: ${bytes.length}\n`;
      msg += `Loading image...\n`;

      const blob = new Blob([bytes], { type: 'image/jpeg' });

      clearImage();
      self._lastObjectUrl = URL.createObjectURL(blob);

      // set text trước, rồi ảnh load xong sẽ append resolution ở onload
      setInfo(msg);
      self.$img.src = self._lastObjectUrl;

    } catch (e) {
      clearImage();
      setInfo(`Decode failed:\n${e && e.message ? e.message : e}`);
    }
  }

  function clearAll() {
    clearImage();
    self._latestKv = {};
    setInfo("Cleared.");
  }

  self.$btnRender.addEventListener('click', render);
  self.$btnClear.addEventListener('click', clearAll);

  setInfo("Waiting for data…");
};

function extractLatestKv(ctxData) {
  const kv = {};

  // flat array
  if (Array.isArray(ctxData) && ctxData.length && ctxData[0].dataKey && ctxData[0].data) {
    for (const item of ctxData) {
      const key = item.dataKey && item.dataKey.name;
      const series = item.data;
      if (!key || !Array.isArray(series) || !series.length) continue;
      const last = series[series.length - 1];
      const val = last && last.length >= 2 ? last[1] : null;
      if (val !== null && val !== undefined) kv[key] = String(val);
    }
    return kv;
  }

  // nested by datasource
  if (Array.isArray(ctxData)) {
    for (const ds of ctxData) {
      const rows = ds && ds.data;
      if (!Array.isArray(rows)) continue;
      for (const row of rows) {
        const key = row.dataKey && row.dataKey.name;
        const series = row.data;
        if (!key || !Array.isArray(series) || !series.length) continue;
        const last = series[series.length - 1];
        const val = last && last.length >= 2 ? last[1] : null;
        if (val !== null && val !== undefined) kv[key] = String(val);
      }
    }
  }

  return kv;
}

self.onDataUpdated = function () {
  try {
    self._latestKv = extractLatestKv(self.ctx.data || []);
    const keys = Object.keys(self._latestKv).sort();
    self.ctx.$container[0].querySelector('#info').textContent =
      keys.length
        ? `Received keys:\n- ${keys.join('\n- ')}\n\nClick Render.`
        : `No keys received in widget datasource.`;
  } catch (e) {
    self.ctx.$container[0].querySelector('#info').textContent =
      `onDataUpdated error: ${e && e.message ? e.message : e}`;
  }
};

self.onDestroy = function () {
  try {
    if (self._lastObjectUrl) URL.revokeObjectURL(self._lastObjectUrl);
  } catch (e) {}
};

