descriptor.templateCss:
.wrapper{
  height:100%;
  display:flex;
  flex-direction:column;
  background:#fff;
  font-family: Inter, system-ui, -apple-system, Segoe UI, Roboto, Arial, sans-serif;
}

/* ===== Toolbar layout (CRUD + Camera + ROI same row) ===== */
.toolbar{
  background:#fff;
  border-bottom:1px solid #eee;
  padding:10px 12px;
}

.toolbar-row{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:12px;
  flex-wrap:wrap;
}

.toolbar-left{
  display:flex;
  align-items:center;
  gap:10px;
  flex-wrap:wrap;
}

.toolbar-right{
  display:flex;
  align-items:center;
  justify-content:flex-end;
  gap:10px;
  flex-wrap:wrap;
}

.cam-box{
  display:flex;
  align-items:center;
  gap:8px;
  padding:6px 8px;
  border:1px solid #eee;
  border-radius:10px;
  background:#fff;
}
.cam-label{ font-size:13px; color:#111827; }

.cam-dd{
  min-width:150px;
  height:34px;
  border:1px solid #e5e7eb;
  border-radius:8px;
  padding:0 10px;
  background:#fff;
  outline:none;
}
.cam-dd:focus{
  border-color:#2563eb;
  box-shadow:0 0 0 3px rgba(37,99,235,.15);
}

/* ROI switch inline with toolbar */
.roi-switch{
  display:none;
  gap:6px;
  padding:6px;
  border:1px solid #eee;
  border-radius:10px;
  background:#fff;
}
.roi-btn{
  height:32px;
  padding:0 12px;
  border:1px solid #e5e7eb;
  background:#fff;
  border-radius:999px;
  cursor:pointer;
  font-size:13px;
}
.roi-btn.active{
  border-color:#2563eb;
  box-shadow:0 0 0 3px rgba(37,99,235,.15);
}

/* ===== Stage ===== */
.stage{
  flex:1;
  position:relative;
  min-height:0;
  background:#fff;
}
.stage canvas{
  position:absolute;
  inset:0;
  width:100%;
  height:100%;
  display:block;
  cursor:crosshair;
  background:#fff;
}

/* ===== Loading overlay ===== */
.loading-overlay{
  position:absolute;
  inset:0;
  display:none;
  align-items:center;
  justify-content:center;
  background:rgba(17,24,39,.28);
  z-index:25;
  pointer-events:none;
}
.stage.is-loading .loading-overlay{
  display:flex;
}
.loading-card{
  display:flex;
  align-items:center;
  gap:12px;
  padding:14px 16px;
  border-radius:14px;
  background:rgba(255,255,255,.92);
  box-shadow:0 14px 30px rgba(0,0,0,.18);
  color:#111827;
  font-size:14px;
  font-weight:600;
}
.spinner{
  width:18px;
  height:18px;
  border-radius:999px;
  border:3px solid rgba(17,24,39,.20);
  border-top-color: rgba(17,24,39,.80);
  animation: spin .8s linear infinite;
}
@keyframes spin{ from{transform:rotate(0deg)} to{transform:rotate(360deg)} }

/* ===== Button animation ===== */
.tb-btn{ transition: transform .12s ease, box-shadow .12s ease; }
.tb-btn.is-working{ animation: tbPulse .7s ease-in-out infinite; }
.tb-btn.is-success{ animation: tbPop .25s ease-out, tbGlowSuccess .9s ease-out; }
.tb-btn.is-error{ animation: tbShake .25s ease-in-out, tbGlowError .9s ease-out; }

@keyframes tbPulse{ 0%{transform:scale(1)} 50%{transform:scale(1.03)} 100%{transform:scale(1)} }
@keyframes tbPop{ 0%{transform:scale(1)} 60%{transform:scale(1.06)} 100%{transform:scale(1)} }
@keyframes tbShake{ 0%{transform:translateX(0)} 25%{transform:translateX(-3px)} 50%{transform:translateX(3px)} 75%{transform:translateX(-2px)} 100%{transform:translateX(0)} }
@keyframes tbGlowSuccess{ 0%{box-shadow:0 0 0 rgba(0,0,0,0)} 30%{box-shadow:0 0 0 3px rgba(34,197,94,.28)} 100%{box-shadow:0 0 0 rgba(0,0,0,0)} }
@keyframes tbGlowError{ 0%{box-shadow:0 0 0 rgba(0,0,0,0)} 30%{box-shadow:0 0 0 3px rgba(239,68,68,.28)} 100%{box-shadow:0 0 0 rgba(0,0,0,0)} }

/* ===== Toast ===== */
.toast-center{
  position:absolute;
  left:50%;
  top:25%;
  transform:translateX(-50%);
  z-index: 30;
  pointer-events:none;
}
.toast{
  min-width: 460px;
  max-width: 720px;
  padding:14px 18px;
  border-radius:14px;
  color:#fff;
  font-size:14px;
  line-height:1.35;
  text-align:center;
  box-shadow: 0 12px 28px rgba(0,0,0,.18);
  opacity:0;
  transform: translate(-50%, 12px) scale(1.02);
  animation: toastIn .18s ease-out forwards, toastOut 1.0s ease-in forwards;
  animation-delay: 0s, 1.55s;
  position: relative;
  left: 50%;
}
.toast.success{ background: rgba(34,197,94,.92); }
.toast.error{ background: rgba(239,68,68,.92); }
.toast.info{ background: rgba(59,130,246,.92); }
.toast.warn{ background: rgba(245,158,11,.92); }

@keyframes toastIn{ from {opacity:0; transform: translate(-50%, 14px) scale(1.02);} to {opacity:1; transform: translate(-50%, 0) scale(1.04);} }
@keyframes toastOut{ from {opacity:1; transform: translate(-50%, 0) scale(1.04);} to {opacity:0; transform: translate(-50%, -18px) scale(1.00);} }

descriptor.controllerScript:
self.onInit = function () {
  var $injector = self.ctx.$scope.$injector;
  var attributeService = $injector.get(self.ctx.servicesMap.get('attributeService'));

  // AngularJS i18n services (robust)
  var $translate = null;
  var $rootScope = null;
  try { $translate = $injector.get('$translate'); } catch (e) {}
  try { $rootScope = $injector.get('$rootScope'); } catch (e) {}

  var dsArr = self.ctx.datasources || [];
  var ds = dsArr.length ? dsArr[0] : null;
  self._entityId = ds && ds.entity ? ds.entity.id : null;
  if (!self._entityId) {
    console.error('No datasource entity. Please select Entity alias.');
    return;
  }

  var $c = self.ctx.$container;
  var stageEl = $c.find('.stage')[0];
  var canvasEl = $c.find('canvas')[0];
  var camBoxEl = $c.find('.cam-box')[0];
  var selectEl = $c.find('.cam-dd')[0];
  var roiSwitchEl = $c.find('.roi-switch')[0];
  var roiBtns = Array.prototype.slice.call($c.find('.roi-btn') || []);
  var toastCenter = $c.find('.toast-center')[0];

  var btnSaveEl   = $c.find('.btn-save')[0];
  var btnUndoEl   = $c.find('.btn-undo')[0];
  var btnClearEl  = $c.find('.btn-clear')[0];
  var btnReloadEl = $c.find('.btn-reload')[0];

  var loadingTextEl = $c.find('.loading-text')[0];
  var camLabelEl = $c.find('.cam-label')[0];

  var g = canvasEl.getContext('2d');

  self._mode = 'default'; // tablet | edge | default
  self._deviceLabel = null;

  self._cams = [];
  self._activeCam = null;

  self._bgImg = new Image();
  self._bgReady = false;
  self._lastSrc = null;
  self._imgDraw = { offX: 0, offY: 0, drawW: 0, drawH: 0 };

  self._tabletPair = [];
  self._roisNorm = { Detect: [], Region1: [], Region2: [] };
  self._activeRoiName = 'Detect';
  self._pending = null;

  // edge poll control (cancel previous waits)
  self._pollToken = 0;

  // i18n state
  self._lang = 'en';
  self._camPrefixText = 'Cam';
  self._unsubTranslate = null;

  // NEW: frame update throttle to avoid too many reloads
  self._lastFrameUpdateAt = 0;

  var ROI_COLOR = { Detect:'#FFD400', Region1:'#22C55E', Region2:'#EF4444' };

  /* =========================
   * i18n (NO English in JA UI)
   * ========================= */
  var I18N = {
    en: {
      save: 'Save',
      undo: 'Undo',
      clear: 'Clear',
      reload: 'Reload',
      camera: 'Camera',
      detect: 'Detect',
      region1: 'Region1',
      region2: 'Region2',
      loading: 'Loading latest frame...',
      noCamera: 'No camera',
      camPrefix: 'Cam',

      toast_success: 'Succeeded.',
      toast_failed: 'Failed.',

      err_no_cam_selected: 'No camera selected.',
      err_frame_loading_try_again: 'Frame is loading. Please try again.',
      err_need_3_rois: 'You must draw 3 ROIs (Detect, Region1, Region2), each with at least 3 points.',
      err_need_2_points: 'Please select 2 points to create a line.',
      err_failed_request_frame: 'Failed to request frame.',
      err_failed_load_image: 'Failed to load frame image.',
      err_timeout_wait_frame: 'Timeout waiting for new frame from selected camera.',
      err_failed_load_new_frame: 'Failed to load new frame.'
    },
    ja: {
      save: '保存',
      undo: '元に戻す',
      clear: 'クリア',
      reload: '再読み込み',
      camera: 'カメラ',
      detect: '検出',
      region1: '領域1',
      region2: '領域2',
      loading: '最新フレームを読み込み中...',
      noCamera: 'カメラなし',
      camPrefix: 'カメラ',

      toast_success: '成功しました。',
      toast_failed: '失敗しました。',

      err_no_cam_selected: 'カメラが選択されていません。',
      err_frame_loading_try_again: 'フレームを読み込み中です。もう一度お試しください。',
      err_need_3_rois: '3つのROI（検出・領域1・領域2）をそれぞれ3点以上で描画してください。',
      err_need_2_points: '線を作成するには2点を選択してください。',
      err_failed_request_frame: 'フレーム要求に失敗しました。',
      err_failed_load_image: 'フレーム画像の読み込みに失敗しました。',
      err_timeout_wait_frame: '選択したカメラの新しいフレーム待機がタイムアウトしました。',
      err_failed_load_new_frame: '新しいフレームの読み込みに失敗しました。'
    }
  };

  function normLang(l) {
    if (!l) return 'en';
    l = String(l).toLowerCase();
    if (l.indexOf('ja') === 0) return 'ja';
    return 'en';
  }

  function t(key) {
    var d = I18N[self._lang] || I18N.en;
    if (d && d[key] != null) return d[key];
    return '';
  }

  function detectLang() {
    try {
      if ($translate && typeof $translate.use === 'function') {
        var used = $translate.use();
        if (used) return normLang(used);
      }
    } catch (e) {}

    try {
      var ls = localStorage.getItem('tb.lang') ||
               localStorage.getItem('tbLang') ||
               localStorage.getItem('language') ||
               localStorage.getItem('lang');
      if (ls) return normLang(ls);
    } catch (e) {}

    try {
      var hl = document && document.documentElement ? document.documentElement.lang : '';
      if (hl) return normLang(hl);
    } catch (e) {}

    try { return normLang(navigator.language); } catch (e) {}
    return 'en';
  }

  function applyI18nToUI() {
    if (btnSaveEl) btnSaveEl.textContent = t('save');
    if (btnUndoEl) btnUndoEl.textContent = t('undo');
    if (btnClearEl) btnClearEl.textContent = t('clear');
    if (btnReloadEl) btnReloadEl.textContent = t('reload');

    if (camLabelEl) camLabelEl.textContent = t('camera');
    if (loadingTextEl) loadingTextEl.textContent = t('loading');

    for (var i = 0; i < roiBtns.length; i++) {
      var b = roiBtns[i];
      if (!b) continue;
      var roiName = b.dataset ? b.dataset.roi : null;
      if (roiName === 'Detect') b.textContent = t('detect');
      else if (roiName === 'Region1') b.textContent = t('region1');
      else if (roiName === 'Region2') b.textContent = t('region2');
    }

    self._camPrefixText = t('camPrefix') || 'Cam';

    try {
      var opts = selectEl ? selectEl.options : null;
      if (opts) {
        for (var j = 0; j < opts.length; j++) {
          var opt = opts[j];
          if (!opt) continue;
          if (opt.value === '') opt.textContent = t('noCamera');
          else opt.textContent = self._camPrefixText + ' ' + opt.value;
        }
      }
    } catch (e) {}
  }

  function setLang(nextLang) {
    var n = normLang(nextLang);
    if (n === self._lang) return;
    self._lang = n;
    applyI18nToUI();
  }

  function initI18n() {
    self._lang = detectLang();
    applyI18nToUI();

    try { if (typeof self._unsubTranslate === 'function') self._unsubTranslate(); } catch (e) {}
    self._unsubTranslate = null;

    if ($rootScope && typeof $rootScope.$on === 'function') {
      self._unsubTranslate = $rootScope.$on('$translateChangeSuccess', function () {
        var used2 = null;
        try { used2 = ($translate && typeof $translate.use === 'function') ? $translate.use() : null; } catch (e) {}
        setLang(used2 || detectLang());
      });
    }
  }

  /* ===== Toast ===== */
  function toast(type, msg) {
    if (!toastCenter) return;
    var el = document.createElement('div');
    el.className = 'toast ' + (type || 'info');
    el.textContent = msg;
    toastCenter.appendChild(el);
    setTimeout(function () {
      try { toastCenter.removeChild(el); } catch (e) {}
    }, 2700);
  }

  /* ===== Loading ===== */
  function setLoading(on) {
    if (!stageEl) return;
    if (on) stageEl.classList.add('is-loading');
    else stageEl.classList.remove('is-loading');
  }
  function sleep(ms) { return new Promise(function (r) { setTimeout(r, ms); }); }
  function getStageWH() { return { w: stageEl.clientWidth, h: stageEl.clientHeight }; }

  function blankWhite() {
    var wh = getStageWH();
    g.save();
    g.clearRect(0, 0, wh.w, wh.h);
    g.fillStyle = '#fff';
    g.fillRect(0, 0, wh.w, wh.h);
    g.restore();
  }

  /* ===== Button feedback (Undo silent) ===== */
  function setBtnState(btn, state) {
    if (!btn) return;
    btn.classList.remove('is-working','is-success','is-error');
    if (state) {
      btn.classList.add(state);
      if (state === 'is-success' || state === 'is-error') {
        setTimeout(function () { btn.classList.remove(state); }, 900);
      }
    }
  }

  function runWithFeedback(btn, fn, opts) {
    var silent = !!(opts && opts.silent);
    try {
      setBtnState(btn, 'is-working');
      var res = fn();
      if (res && typeof res.then === 'function') {
        return res.then(function () {
          setBtnState(btn, null);
          setBtnState(btn, 'is-success');
          if (!silent) toast('success', t('toast_success'));
        }).catch(function (e) {
          setBtnState(btn, null);
          setBtnState(btn, 'is-error');
          if (!silent) toast('error', (e && e.message) ? e.message : t('toast_failed'));
        });
      } else {
        setBtnState(btn, null);
        setBtnState(btn, 'is-success');
        if (!silent) toast('success', t('toast_success'));
      }
    } catch (e) {
      setBtnState(btn, null);
      setBtnState(btn, 'is-error');
      if (!silent) toast('error', (e && e.message) ? e.message : t('toast_failed'));
    }
  }

  /* ===== Utils ===== */
  function clamp01(n) { return Math.max(0, Math.min(1, n)); }

  // ✅ Treat all-zero flat arrays as "empty"
  function isAllZeroFlat(arr) {
    if (!arr || !arr.length) return true;
    for (var i = 0; i < arr.length; i++) {
      if (Number(arr[i]) !== 0) return false;
    }
    return true;
  }

  function computeImageDrawRect(stageW, stageH) {
    if (!self._bgReady) {
      self._imgDraw = { offX: 0, offY: 0, drawW: 0, drawH: 0 };
      return self._imgDraw;
    }
    var imgW = self._bgImg.naturalWidth || 1;
    var imgH = self._bgImg.naturalHeight || 1;
    var scale = Math.min(stageW / imgW, stageH / imgH);
    var drawW = imgW * scale;
    var drawH = imgH * scale;
    var offX = (stageW - drawW) / 2;
    var offY = (stageH - drawH) / 2;
    self._imgDraw = { offX: offX, offY: offY, drawW: drawW, drawH: drawH };
    return self._imgDraw;
  }

  function evToPointOnImageNorm(ev) {
    var wh = getStageWH();
    var r = canvasEl.getBoundingClientRect();
    var xCss = ev.clientX - r.left;
    var yCss = ev.clientY - r.top;

    var rect = computeImageDrawRect(wh.w, wh.h);
    if (rect.drawW <= 0 || rect.drawH <= 0) return null;
    if (xCss < rect.offX || xCss > rect.offX + rect.drawW) return null;
    if (yCss < rect.offY || yCss > rect.offY + rect.drawH) return null;

    return {
      x: clamp01((xCss - rect.offX) / rect.drawW),
      y: clamp01((yCss - rect.offY) / rect.drawH)
    };
  }

  function normToPixelFlat(pointsNorm) {
    var imgW = self._bgImg.naturalWidth || 1;
    var imgH = self._bgImg.naturalHeight || 1;
    var flat = [];
    for (var i = 0; i < pointsNorm.length; i++) {
      var p = pointsNorm[i];
      flat.push(Math.round(p.x * imgW));
      flat.push(Math.round(p.y * imgH));
    }
    return flat;
  }

  function pixelFlatToNorm(flat) {
    var imgW = self._bgImg.naturalWidth || 1;
    var imgH = self._bgImg.naturalHeight || 1;
    var pts = [];
    for (var i = 0; i + 1 < flat.length; i += 2) {
      pts.push({
        x: clamp01(Number(flat[i]) / imgW),
        y: clamp01(Number(flat[i + 1]) / imgH)
      });
    }
    return pts;
  }

  /* ===== Mode UI ===== */
  function applyModeUI() {
    if (camBoxEl) camBoxEl.style.display = (self._mode === 'tablet') ? 'none' : 'flex';

    if (self._mode === 'edge') {
      if (roiSwitchEl) roiSwitchEl.style.display = 'flex';
      setActiveRoi(self._activeRoiName || 'Detect');
    } else {
      if (roiSwitchEl) roiSwitchEl.style.display = 'none';
    }
  }

  function setActiveRoi(name) {
    self._activeRoiName = name;
    for (var i = 0; i < roiBtns.length; i++) {
      var btn = roiBtns[i];
      if (!btn) continue;
      btn.classList.toggle('active', btn.dataset && btn.dataset.roi === name);
    }
    redraw();
  }

  for (var iBtn = 0; iBtn < roiBtns.length; iBtn++) {
    (function (btn) {
      btn.addEventListener('click', function () {
        if (self._mode !== 'edge') return;
        setActiveRoi(btn.dataset.roi);
      });
    })(roiBtns[iBtn]);
  }

  /* ===== Render ===== */
  function redraw() {
    var wh = getStageWH();
    g.clearRect(0, 0, wh.w, wh.h);
    if (!self._bgReady) return;

    var rect = computeImageDrawRect(wh.w, wh.h);
    g.drawImage(self._bgImg, rect.offX, rect.offY, rect.drawW, rect.drawH);

    if (self._mode === 'edge') {
      drawRoi(self._roisNorm.Detect,  'Detect',  self._activeRoiName === 'Detect');
      drawRoi(self._roisNorm.Region1, 'Region1', self._activeRoiName === 'Region1');
      drawRoi(self._roisNorm.Region2, 'Region2', self._activeRoiName === 'Region2');
    } else {
      drawTabletSingleLine(self._tabletPair);
    }
  }

  function drawTabletSingleLine(pair) {
    if (!pair || !pair.length) return;
    var r = self._imgDraw;

    g.save();
    g.strokeStyle = 'red';
    g.fillStyle = 'red';
    g.lineWidth = 2.6;

    if (pair.length === 2) {
      var p1 = pair[0], p2 = pair[1];
      g.beginPath();
      g.moveTo(r.offX + p1.x * r.drawW, r.offY + p1.y * r.drawH);
      g.lineTo(r.offX + p2.x * r.drawW, r.offY + p2.y * r.drawH);
      g.stroke();
    }

    for (var i = 0; i < pair.length; i++) {
      var p = pair[i];
      var cx = r.offX + p.x * r.drawW;
      var cy = r.offY + p.y * r.drawH;
      g.beginPath();
      g.arc(cx, cy, 4.5, 0, Math.PI * 2);
      g.fill();
    }

    g.restore();
  }

  function drawRoi(pointsNorm, name, isActive) {
    if (!pointsNorm || !pointsNorm.length) return;
    var r = self._imgDraw;
    var color = ROI_COLOR[name] || 'red';

    g.save();
    g.strokeStyle = color;
    g.fillStyle = color;
    g.lineWidth = isActive ? 2.8 : 1.6;
    g.globalAlpha = isActive ? 1 : 0.55;

    if (pointsNorm.length >= 3) {
      g.save();
      g.globalAlpha = isActive ? 0.18 : 0.10;
      g.beginPath();
      g.moveTo(r.offX + pointsNorm[0].x * r.drawW, r.offY + pointsNorm[0].y * r.drawH);
      for (var i = 1; i < pointsNorm.length; i++) {
        g.lineTo(r.offX + pointsNorm[i].x * r.drawW, r.offY + pointsNorm[i].y * r.drawH);
      }
      g.closePath();
      g.fill();
      g.restore();
    }

    if (pointsNorm.length >= 2) {
      g.beginPath();
      g.moveTo(r.offX + pointsNorm[0].x * r.drawW, r.offY + pointsNorm[0].y * r.drawH);
      for (var j = 1; j < pointsNorm.length; j++) {
        g.lineTo(r.offX + pointsNorm[j].x * r.drawW, r.offY + pointsNorm[j].y * r.drawH);
      }
      g.stroke();
    }

    for (var k = 0; k < pointsNorm.length; k++) {
      var p = pointsNorm[k];
      var cx = r.offX + p.x * r.drawW;
      var cy = r.offY + p.y * r.drawH;
      g.beginPath();
      g.arc(cx, cy, 4, 0, Math.PI * 2);
      g.fill();
    }

    g.restore();
  }

  /* ===== Resize (DPR) ===== */
  var resize = function () {
    var rect = stageEl.getBoundingClientRect();
    var dpr = window.devicePixelRatio || 1;
    canvasEl.width = Math.max(1, Math.floor(rect.width * dpr));
    canvasEl.height = Math.max(1, Math.floor(rect.height * dpr));
    g.setTransform(dpr, 0, 0, dpr, 0, 0);
    redraw();
  };
  self._ro = new ResizeObserver(resize);
  self._ro.observe(stageEl);
  resize();

  /* ===== Telemetry pass_cam (edge only) ===== */
  function readPassCamFromTelemetry() {
    var dataArr = self.ctx.data || [];
    var entry = null;
    for (var i = 0; i < dataArr.length; i++) {
      if (dataArr[i] && dataArr[i].dataKey && dataArr[i].dataKey.name === 'pass_cam') {
        entry = dataArr[i];
        break;
      }
    }
    if (!entry || !entry.data || !entry.data.length) return null;
    var v = entry.data[0][1];
    if (v == null || v === '') return null;
    if (typeof v === 'string') { try { v = JSON.parse(v); } catch (e) { return null; } }
    return v;
  }

  function updateCamsFromTelemetry() {
    if (!selectEl) return;

    var obj = readPassCamFromTelemetry();
    if (!obj || typeof obj !== 'object') {
      self._cams = [];
      selectEl.innerHTML = '<option value="">' + t('noCamera') + '</option>';
      return;
    }

    var camIds = Object.keys(obj).sort(function (a, b) { return Number(a) - Number(b); });
    self._cams = camIds;

    selectEl.innerHTML = '';
    for (var i = 0; i < camIds.length; i++) {
      var id = camIds[i];
      var opt = document.createElement('option');
      opt.value = id;
      opt.textContent = self._camPrefixText + ' ' + id;
      selectEl.appendChild(opt);
    }

    var next = (self._activeCam && camIds.indexOf(self._activeCam) >= 0) ? self._activeCam : camIds[0];
    selectEl.value = next;
    if (next && next !== self._activeCam) setActiveCam(next);
  }

  if (selectEl) {
    selectEl.addEventListener('change', function () {
      var camId = selectEl.value;
      if (camId) setActiveCam(camId);
    });
  }

  /* ===== Tablet/default: trigger timestamp ===== */
  function triggerGetFrameTimestamp() {
    var ts = Date.now();
    return new Promise(function (resolve, reject) {
      attributeService.saveEntityAttributes(self._entityId, 'SHARED_SCOPE', [
        { key: 'get_frame_cam', value: ts }
      ]).subscribe(function () { resolve(ts); }, function (err) { reject(err); });
    });
  }

  function refreshLatestFrameTabletDefault() {
    setLoading(true);
    return triggerGetFrameTimestamp().then(function () {
      return sleep(2000);
    }).then(function () {
      fetchFrame();
    }).catch(function () {
      setLoading(false);
      toast('error', t('err_failed_request_frame'));
    });
  }

  /* ===== Edge: switch cam -> send camId to get_frame_cam and wait frame_camX update ===== */
  function triggerGetFrameByCamId(camId) {
    return new Promise(function (resolve, reject) {
      attributeService.saveEntityAttributes(self._entityId, 'SHARED_SCOPE', [
        { key: 'get_frame_cam', value: String(camId) }
      ]).subscribe(function () { resolve(); }, function (err) { reject(err); });
    });
  }

//   function readFrameValueOnce(camId) {
//     return new Promise(function (resolve, reject) {
//       var key = 'frame_cam' + camId;
//       attributeService.getEntityAttributes(self._entityId, 'SERVER_SCOPE', [key])
//         .subscribe(function (attrs) {
//           var a = null;
//           for (var i = 0; i < (attrs || []).length; i++) {
//             if (attrs[i] && attrs[i].key === key) { a = attrs[i]; break; }
//           }
//           resolve(a && a.value ? a.value : null);
//         }, function (err) { reject(err); });
//     });
//   }
function readFrameValueOnce(camId) {
  return new Promise(function (resolve, reject) {
    var key = 'frame_cam' + camId;

    function pick(attrs) {
      var a = null;
      for (var i = 0; i < (attrs || []).length; i++) {
        if (attrs[i] && attrs[i].key === key) { a = attrs[i]; break; }
      }
      return (a && a.value) ? a.value : null;
    }

    // 1) Try CLIENT_SCOPE first (most common for widget display)
    attributeService.getEntityAttributes(self._entityId, 'CLIENT_SCOPE', [key])
      .subscribe(function (attrsC) {
        var vC = pick(attrsC);
        if (vC) { resolve(vC); return; }

        // 2) Fallback SERVER_SCOPE
        attributeService.getEntityAttributes(self._entityId, 'SERVER_SCOPE', [key])
          .subscribe(function (attrsS) {
            resolve(pick(attrsS));
          }, function (err2) { reject(err2); });
      }, function (err1) {
        // If CLIENT fails, still try SERVER
        attributeService.getEntityAttributes(self._entityId, 'SERVER_SCOPE', [key])
          .subscribe(function (attrsS2) {
            var vS2 = pick(attrsS2);
            resolve(vS2);
          }, function (err2) { reject(err2); });
      });
  });
}


  function requestAndWaitFrameEdge(camId, prevValue) {
    var myToken = ++self._pollToken;

    self._bgReady = false;
    setLoading(true);
    blankWhite();

    return triggerGetFrameByCamId(camId).then(function () {
      var maxWaitMs = 12000;
      var intervalMs = 400;
      var start = Date.now();

      function loop() {
        if (myToken !== self._pollToken) return Promise.resolve();

        return readFrameValueOnce(camId).then(function (v) {
          if (v && (!prevValue || v !== prevValue)) {
            fetchFrame();
            return;
          }
          if (Date.now() - start >= maxWaitMs) {
            setLoading(false);
            throw new Error(t('err_timeout_wait_frame'));
          }
          return sleep(intervalMs).then(loop);
        }).catch(function () {
          if (Date.now() - start >= maxWaitMs) {
            setLoading(false);
            throw new Error(t('err_timeout_wait_frame'));
          }
          return sleep(intervalMs).then(loop);
        });
      }

      return loop();
    });
  }

  /* ===== deviceLabel ===== */
  function loadDeviceLabel() {
    attributeService.getEntityAttributes(self._entityId, 'SERVER_SCOPE', ['deviceLabel'])
      .subscribe(function (attrs) {
        var a = null;
        for (var i = 0; i < (attrs || []).length; i++) {
          if (attrs[i] && attrs[i].key === 'deviceLabel') { a = attrs[i]; break; }
        }
        var label = a ? a.value : null;

        self._deviceLabel = label;
