descriptor.templateCss:
/* ===================================
   MODERN LINEAR STYLE WIDGET (3 columns)
   =================================== */

.store-selector-widget {
  width: 100%;
  height: 100%;
  padding: 12px;
  background: #ffffff;
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  font-size: clamp(11px, min(2vw, 3vh), 15px);
  color: #111827;
}

.selector-row {
  display: flex;
  gap: 12px;
  width: 100%;
  align-items: flex-start;
}

/* 3 fields in one row: Store (3) - Device (5) - Cam (4) */
.form-field {
  display: flex;
  flex-direction: column;
  min-width: 0;
}
.store-field { flex: 3; }
.device-field { flex: 5; }
.cam-field { flex: 4; }

/* Reserve space always; hide by visibility (not display) when inactive */
.cam-field--reserved.cam-hidden {
  visibility: hidden;     /* keep space */
  pointer-events: none;   /* avoid hover/click */
}

.field-label {
  display: block;
  font-size: 0.75em;
  font-weight: 600;
  color: #374151;
  margin-bottom: 6px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  letter-spacing: 0.01em;
}

.select-wrapper {
  position: relative;
  width: 100%;
  min-height: 36px;
  max-height: 48px;
  background: #ffffff;
  border: 1px solid #E5E7EB;
  border-radius: 6px;
  box-shadow: 0 1px 2px 0 rgba(0,0,0,0.05);
  transition: all 0.2s ease;
  display: flex;
  align-items: center;
}

.select-wrapper:hover {
  border-color: #D1D5DB;
  background: #F9FAFB;
  box-shadow: 0 2px 4px 0 rgba(0,0,0,0.05);
}

.select-wrapper:focus-within {
  border-color: #000000;
  box-shadow: 0 0 0 1px #000000, 0 1px 2px 0 rgba(0,0,0,0.05);
  background: #ffffff;
}

.mat-select {
  width: 100%;
  height: 100%;
  padding: 0 32px 0 12px;
  font-size: 1em;
  font-weight: 500;
  color: #111827;
  background: transparent;
  border: none;
  outline: none;
  cursor: pointer;
  appearance: none;
  -webkit-appearance: none;
  -moz-appearance: none;
  line-height: 1.5;
  border-radius: 6px;
}

.select-wrapper::after {
  content: '';
  position: absolute;
  right: 10px;
  top: 50%;
  transform: translateY(-50%);
  width: 16px;
  height: 16px;
  background-image: url("data:image/svg+xml,%3Csvg width='16' height='16' viewBox='0 0 16 16' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M4 6L8 10L12 6' stroke='%236B7280' stroke-width='1.5' stroke-linecap='round' stroke-linejoin='round'/%3E%3C/svg%3E");
  background-repeat: no-repeat;
  background-position: center;
  pointer-events: none;
  opacity: 0.7;
  transition: opacity 0.2s;
}
.select-wrapper:hover::after { opacity: 1; }

.mat-select option {
  color: #111827;
  background: #ffffff;
  padding: 8px;
}

/* Disabled */
.mat-select:disabled {
  color: #9CA3AF;
  cursor: not-allowed;
}
.select-wrapper:has(.mat-select:disabled) {
  background: #F3F4F6;
  border-color: #E5E7EB;
  box-shadow: none;
}

/* Status */
.status-container { margin-top: 8px; }
.status-text {
  font-size: 0.8em;
  color: #6B7280;
  font-weight: 500;
}

/* Responsive */
@media (max-width: 520px) {
  .selector-row {
    flex-direction: column;
    gap: 8px;
  }
  .store-field, .device-field, .cam-field { flex: auto; width: 100%; }
  /* On stacked layout, we can hide cam completely if you want; but you asked keep space,
     so we keep it reserved even stacked. */
}

