(function ensureCamBus() {
  var topWin = window.top || window;
  if (topWin.__TB_CAM_BUS__) return;

  topWin.__TB_CAM_BUS__ = {
    last: null,
    _listeners: [],
    emit: function (camName) {
      this.last = camName;
      var payload = { cam: camName, ts: Date.now() };
      this._listeners.forEach(function (fn) {
        try { fn(payload); } catch (e) {}
      });
    },
    on: function (fn) {
      if (typeof fn !== 'function') return;
      this._listeners.push(fn);
    },
    off: function (fn) {
      this._listeners = this._listeners.filter(function (x) { return x !== fn; });
    }
  };
})();

(function () {

  const STORAGE_KEY = 'store_type_selection';

  const DEVICE_LABEL_KEY = 'deviceLabel';
  const CAM_SHARED_ATTR_KEY = 'cam';

  const PASS_CAM_TELEMETRY_KEY = 'pass_cam';
  const CAM_FALLBACK_MAX = 30;

  let attributeService = null;
  let telemetryService = null;

  self.typeSelect = null;
  self.deviceSelect = null;
  self.camSelect = null;
  self.camFieldEl = null;

  self.statusEl = null;
  self.statusContainer = null;

  self.currentDevices = [];

  let camEmitGuard = false;

  self.onInit = function () {
    self.typeSelect = document.getElementById('typeSelect');
    self.deviceSelect = document.getElementById('deviceSelect');
    self.camSelect = document.getElementById('camSelect');
    self.camFieldEl = document.getElementById('camField');
    self.statusEl = document.getElementById('status');
    self.statusContainer = document.getElementById('statusContainer');

    try {
      attributeService = self.ctx.$scope.$injector.get(self.ctx.servicesMap.get('attributeService'));
    } catch (e) { attributeService = null; }

    try {
      const tToken =
        (self.ctx.servicesMap && self.ctx.servicesMap.get && (
          self.ctx.servicesMap.get('telemetryService') ||
          self.ctx.servicesMap.get('telemetry')
        )) || null;
      telemetryService = tToken ? self.ctx.$scope.$injector.get(tToken) : null;
    } catch (e) { telemetryService = null; }

    self.typeSelect.addEventListener('change', async () => {
      const type = self.typeSelect.value;
      await loadDevicesByType(type);
      persistSelection();
      await refreshCamUI();
    });

    self.deviceSelect.addEventListener('change', async () => {
      persistSelection();
      await refreshCamUI();
    });

    self.camSelect.addEventListener('change', async () => {
      const camName = self.camSelect.value;
      await onCamSelect(camName);
    });

    // Start with cam reserved but hidden
    setCamVisible(false);

    self.ctx.ngZone.run(function () {
      init().catch(err => {
        console.error('[store_device_cam] init error:', err);
        setStatus('Error: ' + (err.message || err));
      });
      try { self.ctx.detectChanges(); } catch (e) {}
    });
  };

  self.onDataUpdated = function () {
    self.ctx.ngZone.run(function () {
      refreshCamOptionsFromCtxData();
      try { self.ctx.detectChanges(); } catch (e) {}
    });
  };

  self.onDestroy = function () {};
  self.onResize = function () {};

  function setStatus(msg) {
    const text = msg || '';
    if (self.statusEl) self.statusEl.textContent = text;
    if (self.statusContainer) self.statusContainer.style.display = text ? 'block' : 'none';
  }

  function getToken() {
    return localStorage.getItem('jwt_token') || localStorage.getItem('token') || '';
  }

  async function apiGet(url) {
    const token = getToken();
    const res = await fetch(url, {
      method: 'GET',
      headers: {
        'Content-Type': 'application/json',
        ...(token ? { 'X-Authorization': 'Bearer ' + token } : {})
      }
    });

    if (!res.ok) {
      const errorText = await res.text().catch(() => '');
      throw new Error(`HTTP ${res.status} when GET ${url}: ${errorText}`);
    }
    return res.json();
  }

  function fillSelect(selectEl, items, placeholder) {
    if (!selectEl) return;
    selectEl.innerHTML = '';

    if (placeholder != null) {
      const ph = document.createElement('option');
      ph.value = '';
      ph.textContent = placeholder;
      selectEl.appendChild(ph);
    }

    (items || []).forEach(it => {
      const opt = document.createElement('option');
      if (typeof it === 'string') {
        opt.value = it;
        opt.textContent = it;
      } else {
        opt.value = it.value;
        opt.textContent = it.label;
      }
      selectEl.appendChild(opt);
    });
  }

  function saveSelection(selection) {
    try { localStorage.setItem(STORAGE_KEY, JSON.stringify(selection)); } catch (e) {}
  }

  function restoreSelection() {
    try {
      const s = localStorage.getItem(STORAGE_KEY);
      return s ? JSON.parse(s) : null;
    } catch (e) { return null; }
  }

  async function fetchDeviceTypes() {
    const user = self.ctx.currentUser;

    if (user && user.authority === 'CUSTOMER_USER') {
      const customerId = (user.customerId && user.customerId.id) ? user.customerId.id : user.customerId;
      if (!customerId) return [];

      const pageSize = 1000;
      const url = `/api/customer/${customerId}/deviceInfos?pageSize=${pageSize}&page=0`;
      const r = await apiGet(url);
      const data = r.data || [];
      return [...new Set(data.map(d => d.type))].filter(Boolean).sort();
    }

    const r = await apiGet('/api/device/types');
    let types = Array.isArray(r) ? r : (r.deviceTypes || []);
    if (types.length > 0 && typeof types[0] === 'object') {
      types = types.map(t => t.type || t.name || t.deviceType || t.label || JSON.stringify(t));
    }
    return types.filter(Boolean).sort();
  }

  async function fetchDevices(deviceType) {
    const pageSize = 100;
    const page = 0;

    const user = self.ctx.currentUser;
    let url;

    if (user && user.authority === 'CUSTOMER_USER') {
      const customerId = (user.customerId && user.customerId.id) ? user.customerId.id : user.customerId;
      if (!customerId) throw new Error('Customer ID not found');
      url = `/api/customer/${customerId}/deviceInfos?pageSize=${pageSize}&page=${page}&type=${encodeURIComponent(deviceType)}`;
    } else {
      url = `/api/tenant/deviceInfos?pageSize=${pageSize}&page=${page}&type=${encodeURIComponent(deviceType)}`;
    }

    const r = await apiGet(url);
    const data = r.data || [];

    return data
      .filter(x => x.type === deviceType)
      .map(x => ({
        id: (x.id && (x.id.id || x.id)) || x.id,
        name: x.name || x.label || x.deviceName || '(unnamed)',
        type: x.type
      }));
  }

  async function loadDevicesByType(type) {
    if (!type) {
      fillSelect(self.deviceSelect, [], '-- Select device --');
      self.currentDevices = [];
      return;
    }

    setStatus('Loading devices...');
    const devices = await fetchDevices(type);
    self.currentDevices = devices;

    let deviceOptions = [];
    let defaultSelection = '';

    if (devices.length === 1) {
      deviceOptions = devices.map(d => ({ value: d.id, label: d.name }));
      defaultSelection = devices[0].id;
    } else {
      deviceOptions = [
        { value: '__ALL__', label: `All devices (${devices.length})` },
        ...devices.map(d => ({ value: d.id, label: d.name }))
      ];
      defaultSelection = '__ALL__';
    }

    fillSelect(self.deviceSelect, deviceOptions, null);
    self.deviceSelect.value = defaultSelection;
    setStatus('');
  }

  function persistSelection() {
    const selectedType = self.typeSelect.value;
    const selectedDeviceId = self.deviceSelect.value;
    const selectedDeviceName = self.deviceSelect.options[self.deviceSelect.selectedIndex]?.text || '';

    if (!self.ctx || !self.ctx.stateController) return;

    if (selectedDeviceId === '__ALL__') {
      const devices = self.currentDevices || [];
      const entityList = devices.map(d => ({ entityType: 'DEVICE', id: d.id }));

      const stateParams = {
        entities: entityList,
        entityIds: entityList,
        entityId: entityList.length ? { entityType: 'DEVICE', id: entityList[0].id } : null,
        entityType: 'DEVICE',
        id: entityList.length ? entityList[0].id : null,

        selectedDeviceMode: 'ALL',
        selectedDeviceType: selectedType,
        selectedDeviceId: '__ALL__',
        selectedDeviceName: selectedDeviceName,

        name: selectedDeviceName,
        label: selectedDeviceName,
        type: selectedType,
        mode: 'ALL',
        count: entityList.length
      };

      self.ctx.stateController.updateState(null, stateParams, true);

      saveSelection({
        deviceType: selectedType,
        deviceId: '__ALL__',
        deviceName: selectedDeviceName,
        mode: 'ALL',
        timestamp: Date.now()
      });

      // reserved slot stays, but hidden
      setCamVisible(false);
      return;
    }

    if (selectedDeviceId) {
      const stateParams = {
        entityType: 'DEVICE',
        id: selectedDeviceId,
        entityId: { entityType: 'DEVICE', id: selectedDeviceId },

        name: selectedDeviceName,
        label: selectedDeviceName,

        selectedDeviceMode: 'SINGLE',
        selectedDeviceType: selectedType,
        selectedDeviceId: selectedDeviceId,
        selectedDeviceName: selectedDeviceName,

        mode: 'SINGLE',
        type: selectedType
      };

      self.ctx.stateController.updateState(null, stateParams, true);

      saveSelection({
        deviceType: selectedType,
        deviceId: selectedDeviceId,
        deviceName: selectedDeviceName,
        mode: 'SINGLE',
        timestamp: Date.now()
      });

      return;
    }

    const stateParams = {
      entityType: null,
      id: null,
      name: null,
      label: null,
      entities: null,

      selectedDeviceMode: 'NONE',
      selectedDeviceType: selectedType || null,
      selectedDeviceId: null,
      selectedDeviceName: null,

      mode: 'NONE',
      type: selectedType || null,
      count: 0
    };
    self.ctx.stateController.updateState(null, stateParams, true);
    setCamVisible(false);
  }

  function resolveEntityIdForSelectedDevice(deviceId) {
    if (!deviceId) return null;
    return { entityType: 'DEVICE', id: deviceId };
  }

  async function readDeviceLabel(deviceId) {
    if (!attributeService || !deviceId) return null;
    const entityId = resolveEntityIdForSelectedDevice(deviceId);

    try {
      const attrs = await attributeService.getEntityAttributes(entityId, 'SERVER_SCOPE', ['deviceLabel']).toPromise();
      const a = (attrs || []).find(x => x && x.key === 'deviceLabel');
      if (a && a.value != null && String(a.value).trim() !== '') return String(a.value);
    } catch (e) {}

    try {
      const attrs2 = await attributeService.getEntityAttributes(entityId, 'SHARED_SCOPE', ['deviceLabel']).toPromise();
      const b = (attrs2 || []).find(x => x && x.key === 'deviceLabel');
      if (b && b.value != null && String(b.value).trim() !== '') return String(b.value);
    } catch (e) {}

    return null;
  }

  async function loadSharedCam(deviceId) {
    if (!attributeService || !deviceId) return null;
    const entityId = resolveEntityIdForSelectedDevice(deviceId);

    try {
      const attrs = await attributeService.getEntityAttributes(entityId, 'SHARED_SCOPE', [CAM_SHARED_ATTR_KEY]).toPromise();
      const a = (attrs || []).find(x => x && x.key === CAM_SHARED_ATTR_KEY);
      return a && a.value != null ? String(a.value) : null;
    } catch (e) {
      return null;
    }
  }

  async function saveSharedCam(deviceId, camName) {
    if (!attributeService || !deviceId) return;
    const entityId = resolveEntityIdForSelectedDevice(deviceId);
    const attributes = [{ key: CAM_SHARED_ATTR_KEY, value: camName }];

    try {
      await attributeService.saveEntityAttributes(entityId, 'SHARED_SCOPE', attributes).toPromise();
    } catch (e) {
      console.warn('[store_device_cam] saveSharedCam failed:', e);
    }
  }

  function parseCamOptions(raw) {
    if (raw == null) return [];
    let obj = raw;

    if (typeof obj === 'string') {
      let s = obj.trim();
      if ((s.startsWith('"') && s.endsWith('"')) || (s.startsWith("'") && s.endsWith("'"))) s = s.slice(1, -1);
      s = s.replace(/\\"/g, '"');
      try { obj = JSON.parse(s); } catch (e) { obj = null; }
    }

    if (!obj || typeof obj !== 'object') return [];

    const keys = Object.keys(obj).sort((a, b) => (parseInt(a, 10) || 0) - (parseInt(b, 10) || 0));
    const cams = keys.map(k => `CAM${k}`);
    return ['ALL', ...cams];
  }

  function buildFallbackCamOptions(maxN) {
    const out = ['ALL'];
    for (let i = 1; i <= maxN; i++) out.push(`CAM${i}`);
    return out;
  }

  function getLastTelemetryValueFromCtxData(keyName) {
    const dataArr = self.ctx.data || [];
    if (!Array.isArray(dataArr) || !dataArr.length) return null;

    const item = dataArr.find(d => d && d.dataKey && d.dataKey.name === keyName);
    if (!item || !item.data || !item.data.length) return null;

    const last = item.data[item.data.length - 1];
    return last ? last[1] : null;
  }

  async function fetchLatestPassCamDirectly(deviceId) {
    if (!telemetryService || !telemetryService.getLatestTimeseries || !deviceId) return null;
    const entityId = resolveEntityIdForSelectedDevice(deviceId);

    try {
      const data = await telemetryService.getLatestTimeseries(entityId, [PASS_CAM_TELEMETRY_KEY]).toPromise();
      const arr = data && data[PASS_CAM_TELEMETRY_KEY];
      if (!arr || !arr.length) return null;
      return arr[0].value;
    } catch (e) {
      return null;
    }
  }

  function applyCamOptionsToSelect(options) {
    if (!self.camSelect) return;
    const cur = self.camSelect.value;

    self.camSelect.innerHTML = '';
    options.forEach(v => {
      const opt = document.createElement('option');
      opt.value = v;
      opt.textContent = v;
      self.camSelect.appendChild(opt);
    });

    if (cur && options.includes(cur)) self.camSelect.value = cur;
    else self.camSelect.value = options[0] || 'ALL';
  }

  function refreshCamOptionsFromCtxData() {
    // only if cam visually active
    if (!self.camFieldEl || self.camFieldEl.classList.contains('cam-hidden')) return;

    const raw = getLastTelemetryValueFromCtxData(PASS_CAM_TELEMETRY_KEY);
    const options = parseCamOptions(raw);

    if (options && options.length) {
      self._camOptions = options;
      applyCamOptionsToSelect(options);

      if (!self.camSelect.value || !options.includes(self.camSelect.value)) {
        self.camSelect.value = options[0];
      }
    }
  }

  function setCamVisible(isVisible) {
    if (!self.camFieldEl) return;
    // keep space always, just hide visually
    if (isVisible) {
      self.camFieldEl.classList.remove('cam-hidden');
      self.camSelect.disabled = false;
    } else {
      self.camFieldEl.classList.add('cam-hidden');
      self.camSelect.disabled = true;
    }
  }

  async function refreshCamUI() {
    const selectedDeviceId = self.deviceSelect.value;

    // Not single / all / none => hide (but keep space)
    if (!selectedDeviceId || selectedDeviceId === '__ALL__') {
      setCamVisible(false);
      return;
    }

    const deviceLabel = await readDeviceLabel(selectedDeviceId);
    const isEdge = String(deviceLabel || '').trim() === 'edge-type';

    if (!isEdge) {
      setCamVisible(false);
      return;
    }

    // edge-type single => show cam
    setCamVisible(true);

    // options: ctx first
    refreshCamOptionsFromCtxData();
    let options = (self._camOptions || []).slice();

    if (!options.length) {
      // immediate fallback to avoid empty UX
      options = buildFallbackCamOptions(CAM_FALLBACK_MAX);
      self._camOptions = options;
      applyCamOptionsToSelect(options);
    }

    // direct fetch attempt
    const raw = await fetchLatestPassCamDirectly(selectedDeviceId);
    const parsed = parseCamOptions(raw);
    if (parsed && parsed.length) {
      self._camOptions = parsed;
      applyCamOptionsToSelect(parsed);
    }

    // choose selected: shared > bus > first
    const sharedCam = await loadSharedCam(selectedDeviceId);
    const bus = (window.top || window).__TB_CAM_BUS__;
    const busLast = bus && bus.last != null ? String(bus.last) : null;

    let selected = null;
    if (sharedCam && (self._camOptions || []).includes(sharedCam)) selected = sharedCam;
    else if (busLast && (self._camOptions || []).includes(busLast)) selected = busLast;
    else selected = (self._camOptions && self._camOptions.length) ? self._camOptions[0] : 'ALL';

    self.camSelect.value = selected;
  }

  async function onCamSelect(camName) {
    const selectedDeviceId = self.deviceSelect.value;
    if (!selectedDeviceId || selectedDeviceId === '__ALL__') return;
    if (!camName) return;

    await saveSharedCam(selectedDeviceId, camName);

    try {
      const bus = (window.top || window).__TB_CAM_BUS__;
      if (bus && bus.emit && !camEmitGuard) {
        camEmitGuard = true;
        bus.emit(camName);
        setTimeout(() => { camEmitGuard = false; }, 50);
      }
    } catch (e) {}
  }

  async function init() {
    setStatus('Loading device types...');

    const types = await fetchDeviceTypes();
    fillSelect(self.typeSelect, types, null);
    setStatus('');

    const saved = restoreSelection();

    if (saved && saved.deviceType && types.includes(saved.deviceType)) {
      self.typeSelect.value = saved.deviceType;
      await loadDevicesByType(saved.deviceType);

      if (saved.deviceId) self.deviceSelect.value = saved.deviceId;

      persistSelection();
      await refreshCamUI();
      return;
    }

    if (types.length) {
      self.typeSelect.value = types[0];
      await loadDevicesByType(types[0]);
      persistSelection();
      await refreshCamUI();
    } else {
      setStatus('No device types available');
    }
  }

})();

