descriptor.controllerScript:
(function () {
  let chart = null;

  // ====== Debounce & fetch guard ======
  let pendingUpdateTimeout = null;
  let isFetchingAllDevices = false;

  // ====== REQUIREMENT: ONLY these 3 keys in ALL + SINGLE ======
  const KEYS_WHITELIST = ['pass_total', 'watching_total', 'payment_total'];

  // ====== Legend labels ======
  const KEY_LABEL_MAP = {
    pass_total: 'Pass',
    watching_total: 'Watching',
    payment_total: 'Approach'
  };

  // ====== Colors ======
  const KEY_COLOR_MAP = {
    pass_total: '#86D0FF',
    watching_total: '#4CAF50',
    payment_total: '#ED1C24'
  };

  // ====== Utils ======
  function safeGetToken() {
    return localStorage.getItem('jwt_token') || localStorage.getItem('token') || '';
  }

  function normalizeKeyName(s) {
    return String(s || '').trim().toLowerCase().replace(/\s+/g, '');
  }

  function dedupe(arr) {
    const out = [];
    const set = new Set();
    (arr || []).forEach(x => {
      const v = String(x || '').trim();
      if (v && !set.has(v)) {
        set.add(v);
        out.push(v);
      }
    });
    return out;
  }

  function extractDeviceId(ent) {
    if (!ent) return null;
    if (typeof ent === 'string') return ent;
    if (typeof ent.id === 'string') return ent.id;
    if (ent.id && typeof ent.id.id === 'string') return ent.id.id;
    return null;
  }

  // Read state params robustly
  function readStateParams() {
    const sc = self.ctx.stateController;
    if (!sc) return {};
    try {
      const p = sc.getStateParams();
      if (p && typeof p === 'object') return p;
    } catch (e) { }
    try {
      const p2 = sc.getStateParams('default');
      if (p2 && typeof p2 === 'object') return p2;
    } catch (e) { }
    return {};
  }

  function getAllDeviceIdsFromState(stateParams) {
    const list = stateParams.entities || stateParams.entityIds || [];
    const ids = [];

    if (Array.isArray(list)) {
      list.forEach(e => {
        const id = extractDeviceId(e);
        if (id) ids.push(id);
      });
    } else {
      const id = extractDeviceId(list);
      if (id) ids.push(id);
    }
    return dedupe(ids);
  }

  function getSingleDeviceIdFromStateOrDs(stateParams) {
    const fromState =
      stateParams.selectedDeviceId ||
      stateParams.id ||
      extractDeviceId(stateParams.entityId);

    if (fromState && fromState !== '__ALL__') return fromState;

    // fallback from datasources
    const ds0 = self.ctx.datasources && self.ctx.datasources[0];
    const ent = ds0 && (ds0.entityId || ds0.entity);
    const uuid = extractDeviceId(ent);
    if (uuid) return uuid;

    // fallback from subscription
    const sub = self.ctx.defaultSubscription;
    if (sub && Array.isArray(sub.data) && sub.data.length) {
      const dk0 = sub.data[0];
      const e = dk0?.datasource?.entityId || dk0?.dataKey?.datasource?.entityId || dk0?.datasource?.entity;
      const u2 = extractDeviceId(e);
      if (u2) return u2;
    }
    return null;
  }

  // ====== Time window helpers ======
  function isDayMode(tw) {
    if (!tw) return false;
    const start = tw.minTime || tw.fixedWindow?.startTimeMs;
    const end = tw.maxTime || tw.fixedWindow?.endTimeMs;
    if (!start || !end) return false;
    const ONE_DAY = 24 * 60 * 60 * 1000;
    if (end - start > ONE_DAY + 15 * 60 * 1000) return false;
    const s = new Date(start), e = new Date(end);
    return s.getFullYear() === e.getFullYear() &&
      s.getMonth() === e.getMonth() &&
      s.getDate() === e.getDate();
  }

  function getDayWindowFull(tw) {
    const ref = tw.fixedWindow?.startTimeMs || tw.minTime || Date.now();
    const d = new Date(ref);
    const y = d.getFullYear(), m = d.getMonth(), day = d.getDate();
    const start0 = new Date(y, m, day, 0, 0, 0, 0).getTime();
    const end24 = new Date(y, m, day, 23, 59, 59, 999).getTime();
    return [start0, end24];
  }

  function normalizeTimestamp(ms, opts) {
    const { isMonthMode, isYearMode, isHourlyGapMode } = opts || {};
    const x = new Date(ms);

    if (isYearMode) return new Date(x.getFullYear(), x.getMonth(), 1, 0, 0, 0, 0).getTime();
    if (isMonthMode) return new Date(x.getFullYear(), x.getMonth(), x.getDate(), 0, 0, 0, 0).getTime();
    if (isHourlyGapMode) return new Date(x.getFullYear(), x.getMonth(), x.getDate(), x.getHours(), 0, 0, 0).getTime();

    return new Date(x.getFullYear(), x.getMonth(), x.getDate(), 0, 0, 0, 0).getTime();
  }

  function fillGapsWithNull(data, startTime, endTime, mode) {
    if (!Array.isArray(data) || data.length === 0 || !startTime || !endTime) return data || [];

    const map = {};
    const normKey = (ms) => {
      const x = new Date(ms);
      if (mode === 'hour') return new Date(x.getFullYear(), x.getMonth(), x.getDate(), x.getHours(), 0, 0, 0).getTime();
      if (mode === 'day') return new Date(x.getFullYear(), x.getMonth(), x.getDate(), 0, 0, 0, 0).getTime();
      if (mode === 'month') return new Date(x.getFullYear(), x.getMonth(), 1, 0, 0, 0, 0).getTime();
      return ms;
    };

    data.forEach(p => { map[normKey(p.t)] = p.y; });

    const filled = [];

    if (mode === 'hour') {
      const STEP = 60 * 60 * 1000;
      const start = Math.floor(startTime / STEP) * STEP;
      const end = Math.ceil(endTime / STEP) * STEP;
      for (let t = start; t <= end; t += STEP) {
        filled.push({ t, y: Object.prototype.hasOwnProperty.call(map, t) ? map[t] : null });
      }
      return filled;
    }

    if (mode === 'day') {
      const DAY = 24 * 60 * 60 * 1000;
      const sDate = new Date(startTime);
      const eDate = new Date(endTime);
      const start = new Date(sDate.getFullYear(), sDate.getMonth(), sDate.getDate()).getTime();
      const end = new Date(eDate.getFullYear(), eDate.getMonth(), eDate.getDate()).getTime();
      for (let t = start; t <= end; t += DAY) {
        filled.push({ t, y: Object.prototype.hasOwnProperty.call(map, t) ? map[t] : null });
      }
      return filled;
    }

    if (mode === 'month') {
      const s = new Date(startTime);
      const e = new Date(endTime);
      let cur = new Date(s.getFullYear(), s.getMonth(), 1);
      const endM = new Date(e.getFullYear(), e.getMonth(), 1);
      for (; cur.getTime() <= endM.getTime(); cur.setMonth(cur.getMonth() + 1)) {
        const t = cur.getTime();
        filled.push({ t, y: Object.prototype.hasOwnProperty.call(map, t) ? map[t] : null });
      }
      return filled;
    }

    return data;
  }

  function stitchZeroBeforeData(points) {
    if (!Array.isArray(points) || points.length === 0) return points || [];
    const out = [];
    for (let i = 0; i < points.length; i++) {
      const curr = points[i];
      const prev = i > 0 ? points[i - 1] : null;
      if (prev && prev.y == null && curr.y != null) out.push({ t: prev.t, y: 0 });
      out.push(curr);
    }
    return out;
  }

  function applyTimeScaleForWindow(chart, startTime, endTime, opts) {
    const xAxis = chart.options.scales.xAxes[0];
    const { isMonthMode, isYearMode } = opts || {};
    let minMs = startTime ? Number(startTime) : undefined;
    let maxMs = endTime ? Number(endTime) : undefined;

    if (isDayMode(self.ctx.defaultSubscription?.subscriptionTimewindow)) {
      const s = new Date(minMs);
      const e = new Date(minMs);
      minMs = new Date(s.getFullYear(), s.getMonth(), s.getDate(), 7, 0, 0, 0).getTime();
      maxMs = new Date(e.getFullYear(), e.getMonth(), e.getDate(), 19, 0, 0, 0).getTime();

      xAxis.time.unit = 'hour';
      xAxis.time.stepSize = 1;
      xAxis.time.displayFormats.hour = 'HH:mm';
      xAxis.time.tooltipFormat = 'HH:mm';
      xAxis.offset = false;
    } else if (isYearMode) {
      xAxis.time.unit = 'month';
      xAxis.time.stepSize = 1;
      xAxis.time.displayFormats.month = 'MMM';
      xAxis.offset = true;
    } else if (isMonthMode) {
      const s = new Date(minMs), e = new Date(maxMs);
      minMs = new Date(s.getFullYear(), s.getMonth(), s.getDate(), 0, 0, 0, 0).getTime();
      maxMs = new Date(e.getFullYear(), e.getMonth(), e.getDate(), 23, 59, 59, 999).getTime();

      xAxis.time.unit = 'day';
      xAxis.time.stepSize = 1;
      xAxis.time.displayFormats.day = 'MMM DD';
      xAxis.time.tooltipFormat = 'YYYY-MM-DD';
      xAxis.offset = true;
    } else {
      xAxis.time.unit = 'hour';
      xAxis.time.stepSize = 1;
      xAxis.time.displayFormats.hour = 'HH:mm';
      xAxis.offset = false;
    }

    xAxis.ticks.min = minMs;
    xAxis.ticks.max = maxMs;
    xAxis.time.min = minMs;
    xAxis.time.max = maxMs;
  }

  // ====== Build datasets from subscription (SINGLE) - only 3 keys ======
  function buildDatasetsFromSubscription(subscription, startTime, endTime, opts) {
    const results = [];
    if (!subscription || !Array.isArray(subscription.data)) return results;

    const { isMonthMode, isYearMode, isHourlyGapMode } = opts || {};
    const want = new Set(KEYS_WHITELIST.map(normalizeKeyName));

    subscription.data.forEach((dk) => {
      const key = dk.dataKey || {};
      const rawKeyName = (key.name || key.label || '').trim();
      const keyNorm = normalizeKeyName(rawKeyName);

      // only keep 3 keys
      if (!want.has(keyNorm)) return;

      const keyName =
        KEYS_WHITELIST.find(k => normalizeKeyName(k) === keyNorm) || rawKeyName;

      let points = (dk.data || [])
        .filter(p => (!startTime || p[0] >= startTime) && (!endTime || p[0] <= endTime))
        .map(p => ({ t: Number(p[0]), y: Number(p[1]) }));

      if (!points || points.length === 0) return;

      if (isHourlyGapMode) points = fillGapsWithNull(points, startTime, endTime, 'hour');
      else if (isMonthMode) points = fillGapsWithNull(points, startTime, endTime, 'day');
      else if (isYearMode) points = fillGapsWithNull(points, startTime, endTime, 'month');

      points = stitchZeroBeforeData(points);

      const hasRealValue = points.some(pt => pt && pt.y != null && Number.isFinite(pt.y));
      if (!hasRealValue) return;

      results.push({
        label: KEY_LABEL_MAP[keyName] || keyName,
        __tbKeyName: keyName,
        data: points,
        borderColor: KEY_COLOR_MAP[keyName] || '#666',
        backgroundColor: KEY_COLOR_MAP[keyName] || '#666',
        fill: false,
        borderWidth: 5,
        lineTension: 0.3,
        spanGaps: false,
        pointRadius: 2,
        pointHitRadius: 6,
        pointHoverRadius: 5,
        pointStyle: 'circle',
        showLine: true
      });
    });

    // Ensure stable order: Pass, Watching, Approach
    results.sort((a, b) => {
      const ia = KEYS_WHITELIST.indexOf(a.__tbKeyName);
      const ib = KEYS_WHITELIST.indexOf(b.__tbKeyName);
      return ia - ib;
    });

    return results;
  }

  // ====== ALL mode: fetch & SUM across devices for 3 keys ======
  async function fetchAllDevicesTelemetry(deviceIds, keys, startTime, endTime, opts) {
    const aggregated = {};
    keys.forEach(k => { aggregated[k] = {}; });

    const token = safeGetToken();
    const keysStr = keys.join(',');

    await Promise.all(deviceIds.map(async (deviceId) => {
      const url =
        `/api/plugins/telemetry/DEVICE/${deviceId}/values/timeseries` +
        `?keys=${encodeURIComponent(keysStr)}` +
        `&startTs=${Number(startTime)}` +
        `&endTs=${Number(endTime)}` +
        `&limit=100000&agg=NONE`;

      const res = await fetch(url, {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
          ...(token ? { 'X-Authorization': 'Bearer ' + token } : {})
        }
      });

      if (!res.ok) return;

      const data = await res.json();

      keys.forEach((keyName) => {
        const points = (data && data[keyName]) ? data[keyName] : [];
        points.forEach(p => {
          const ts = Number(p.ts);
          const val = Number(p.value) || 0;
          const nts = normalizeTimestamp(ts, opts);
          aggregated[keyName][nts] = (aggregated[keyName][nts] || 0) + val;
        });
      });
    }));

    return aggregated;
  }

  function buildDatasetsFromAggregatedData(aggregatedData, startTime, endTime, opts) {
    const results = [];
    const { isMonthMode, isYearMode, isHourlyGapMode } = opts || {};

    KEYS_WHITELIST.forEach((keyName) => {
      const dataMap = aggregatedData[keyName] || {};
      const tsKeys = Object.keys(dataMap);
      if (tsKeys.length === 0) return;

      let points = tsKeys
        .map(ts => ({ t: Number(ts), y: Number(dataMap[ts]) }))
        .sort((a, b) => a.t - b.t);

      if (isHourlyGapMode) points = fillGapsWithNull(points, startTime, endTime, 'hour');
      else if (isMonthMode) points = fillGapsWithNull(points, startTime, endTime, 'day');
      else if (isYearMode) points = fillGapsWithNull(points, startTime, endTime, 'month');

      points = stitchZeroBeforeData(points);

      const hasRealValue = points.some(pt => pt && pt.y != null && Number.isFinite(pt.y));
      if (!hasRealValue) return;

      results.push({
        label: KEY_LABEL_MAP[keyName] || keyName,
        __tbKeyName: keyName,
        data: points,
        borderColor: KEY_COLOR_MAP[keyName] || '#666',
        backgroundColor: KEY_COLOR_MAP[keyName] || '#666',
        fill: false,
        borderWidth: 5,
        lineTension: 0.3,
        spanGaps: false,
        pointRadius: 2,
        pointHitRadius: 6,
        pointHoverRadius: 5,
        pointStyle: 'circle',
        showLine: true
      });
    });

    return results;
  }

  // ====== Widget lifecycle ======
  self.onInit = function () {
    if (typeof moment !== 'undefined') moment.locale('en');

    const canvas = self.ctx.$container[0].querySelector('#chart');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');

    chart = new Chart(ctx, {
      type: 'line',
      data: { datasets: [] },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: { duration: 800, easing: 'easeOutQuart' },
        legend: { display: true, position: 'top', labels: { usePointStyle: true, boxWidth: 3 } },
        tooltips: {
          backgroundColor: '#FFFFFF',
          titleFontColor: '#000000',
          bodyFontColor: '#000000',
          borderColor: 'rgba(0,0,0,0.15)',
          borderWidth: 1,
          displayColors: true,
          intersect: false,
          mode: 'index',
          callbacks: {
            title: function (items, data) {
              const ti = items[0];
              const ds = data.datasets[ti.datasetIndex];
              const pt = ds && ds.data ? ds.data[ti.index] : null;
              const ts = (pt && (pt.t || pt.x)) || ti.xLabel || ti.label;
              const m = (typeof moment !== 'undefined') ? moment(Number(ts)) : null;
              // giữ như code cũ: title theo ngày
              return m && m.isValid() ? m.format('YYYY-MM-DD') : (ti.label || ti.xLabel || '');
            },
            labelPointStyle: function () { return { PointStyle: 'true', rotation: 0 }; },
            labelColor: function (tooltipItem, chart) {
              const ds = chart.config.data.datasets[tooltipItem.datasetIndex];
              const c = ds.borderColor || '#666';
              return { borderColor: c, backgroundColor: c };
            }
          }
        },
        scales: {
          xAxes: [{
            type: 'time',
            time: {
              tooltipFormat: 'HH:mm',
              displayFormats: { minute: 'HH:mm', hour: 'HH:mm', day: 'YYYY-MM-DD', month: 'MMM' }
            },
            distribution: 'linear',
            scaleLabel: { display: true, labelString: 'Date Time' },
            ticks: { source: 'data' },
            offset: false
          }],
          yAxes: [{ scaleLabel: { display: true, labelString: 'People Count' }, ticks: { beginAtZero: true } }]
        },
        pan: { enabled: true, mode: 'x' },
        zoom: { enabled: true, mode: 'x' },
        elements: { point: { radius: 2, hoverRadius: 5, hitRadius: 6 } }
      }
    });

    // refresh on state change
    if (self.ctx.stateController && self.ctx.stateController.stateChanged) {
      let stateDebounce = null;
      self.stateSubscription = self.ctx.stateController.stateChanged().subscribe(function () {
        if (stateDebounce) clearTimeout(stateDebounce);
        stateDebounce = setTimeout(() => self.onDataUpdated && self.onDataUpdated(), 150);
      });
    }

    self.onDataUpdated();
  };

  self.onResize = function () { if (chart) chart.resize(); };

  self.onDestroy = function () {
    if (self.stateSubscription) {
      self.stateSubscription.unsubscribe();
      self.stateSubscription = null;
    }
    if (chart) {
      chart.destroy();
      chart = null;
    }
  };

  self.onDataUpdated = function () {
    if (!chart) return;
    if (pendingUpdateTimeout) clearTimeout(pendingUpdateTimeout);
    pendingUpdateTimeout = setTimeout(processDataUpdate, 50);
  };

  async function processDataUpdate() {
    if (!chart) return;

    const sub = self.ctx.defaultSubscription;
    const tw = sub?.subscriptionTimewindow;

    let startTime = tw?.minTime || tw?.fixedWindow?.startTimeMs;
    let endTime = tw?.maxTime || tw?.fixedWindow?.endTimeMs;

    if (isDayMode(tw)) {
      const [s0, e24] = getDayWindowFull(tw);
      startTime = s0; endTime = e24;
    }

    const spanDays = (endTime && startTime) ? (endTime - startTime) / (24 * 60 * 60 * 1000) : 0;
    const isYearMode = spanDays >= 300;
    const isMonthMode = !isYearMode && spanDays > 1;
    const isHourlyGapMode = spanDays <= 1;

    const stateParams = readStateParams();
    const deviceMode = stateParams.selectedDeviceMode || stateParams.mode;
    const isAllMode = deviceMode === 'ALL';

    // =========================
    // ALL MODE: sum across selected devices
    // =========================
    if (isAllMode) {
      const allDeviceIds = getAllDeviceIdsFromState(stateParams);
      const canFetch = allDeviceIds.length >= 1 && startTime && endTime;

      if (canFetch) {
        if (isFetchingAllDevices) return;
        isFetchingAllDevices = true;

        try {
          const aggregated = await fetchAllDevicesTelemetry(
            allDeviceIds,
            KEYS_WHITELIST.slice(),
            startTime,
            endTime,
            { isMonthMode, isYearMode, isHourlyGapMode }
          );

          const datasets = buildDatasetsFromAggregatedData(
            aggregated,
            startTime,
            endTime,
            { isMonthMode, isYearMode, isHourlyGapMode }
          );

          chart.data.datasets = datasets;
          applyTimeScaleForWindow(chart, startTime, endTime, { isMonthMode, isYearMode });
          chart.update();
        } finally {
          isFetchingAllDevices = false;
        }
        return;
      }

      // fallback if cannot fetch
      const dsFallback = buildDatasetsFromSubscription(sub, startTime, endTime, {
        isMonthMode, isYearMode, isHourlyGapMode
      });
      chart.data.datasets = dsFallback;
      applyTimeScaleForWindow(chart, startTime, endTime, { isMonthMode, isYearMode });
      chart.update();
      return;
    }

    // =========================
    // SINGLE MODE: show only 3 keys from subscription
    // =========================
    // (singleDeviceId kept only for parity; not used for CAM/attrs anymore)
    getSingleDeviceIdFromStateOrDs(stateParams);

    const datasets = buildDatasetsFromSubscription(sub, startTime, endTime, {
      isMonthMode, isYearMode, isHourlyGapMode
    });

    chart.data.datasets = datasets;
    applyTimeScaleForWindow(chart, startTime, endTime, { isMonthMode, isYearMode });
    chart.update();
  }
})();

