descriptor.templateCss:
/* energy-heatmap.css */

/* ==== Card ==== */
#eh2-root .eh-card{
  display:flex; flex-direction:column; gap:12px;
  height:100%; box-sizing:border-box; overflow:hidden;
}

/* ==== Header ==== */
#eh2-header.eh-header{
  display:flex; align-items:center; gap:12px; flex:0 0 auto;
}
#eh2-range-group{ display:flex; gap:8px; margin-left:70px; margin-right:auto; }
#eh2-key-wrap{margin-right:73px;margin-left:auto;}
#eh2-hour-mode-group{ display:flex; gap:8px; margin-left:auto; }

.eh-btn--chip{
  padding:6px 12px; border-radius:6px;
  background:#f1f5f9; border:1px solid #d8e0ea;
  font-weight:600; color:#0f172a; cursor:pointer; transition:.2s;
}
.eh-btn--chip:hover{ background:#e2e8f0; }
/* đổi hồng -> #ED1C24 */
.eh-btn--chip.active{
  background:#ED1C24; color:#fff; border-color:#ED1C24;
  box-shadow:0 2px 8px rgba(250,115,102,.25);
}

/* ==== Scroll container + Canvas ==== */
.eh-scroll-wrap{ flex:1 1 auto; min-height:0; display:flex; align-items:stretch; justify-content:center;
  width:100%; height:100%; overflow-x:auto; overflow-y:hidden; border-radius:12px; }
.eh-scroll-wrap::-webkit-scrollbar{ height:8px; }
.eh-scroll-wrap::-webkit-scrollbar-thumb{ background:#cbd5e1; border-radius:4px; }

.eh-canvas,#eh2-canvas{
  flex:1 1 auto; width:100% !important; height:100% !important;
  display:block; background:#fff; border:none; border-radius:12px;
  box-sizing:border-box; min-height:260px;
}

/* ==== Legend & Tooltip ==== */
#eh2-root .eh-legend{ flex:0 0 auto; display:flex; justify-content:center; align-items:center;
  gap:10px 14px; flex-wrap:wrap; padding-top:6px; min-height:32px; }
#eh2-root .eh-tooltip{ position:absolute; pointer-events:none; display:none; z-index:20;
  background:#0f172a; color:#fff; font-size:12px; line-height:1.35; padding:8px 10px; border-radius:8px;
  box-shadow:0 8px 24px rgba(0,0,0,.18); }
#eh2-legend{
    margin-top:27px;
}

/* ===== Modal (2 calendars) ===== */
.eh2-modal-overlay{ position:fixed; inset:0; background:rgba(15,23,42,.45); display:none; z-index:9999; }
.eh2-modal{
  position:absolute; left:50%; top:50%; transform:translate(-50%,-50%);
  background:#fff; border-radius:12px; box-shadow:0 10px 30px rgba(2,6,23,.25);
  min-width:640px; max-width:96vw; padding:14px;
}

.eh2-modal-head{ display:flex; justify-content:space-between; align-items:center; margin-bottom:12px; }
.eh2-modal-head .title{ font:600 16px/1.2 Arial; color:#0f172a; }
.eh2-iconbtn{ width:28px; height:28px; border-radius:6px; border:1px solid #cbd5e1; background:#f8fafc; cursor:pointer; }

.eh2-modal-body{ display:flex; flex-direction:column; gap:12px; }

.eh2-cal-wrap{ display:flex; gap:16px; align-items:flex-start; }
.eh2-cal{ background:#fff; border-radius:10px; padding:10px 10px 12px;
  border:1px solid #e2e8f0; min-width:280px; }
.eh2-cal-head{ display:flex; justify-content:space-between; align-items:center; margin-bottom:8px; }
.eh2-cal-head .title{ font:600 14px/1.2 Arial; color:#0f172a; }

.eh2-week,.eh2-grid{ display:grid; grid-template-columns:repeat(7,32px); gap:4px; justify-content:center; }
.eh2-week{ font:600 11px/28px Arial; color:#64748b; text-align:center; margin-bottom:2px; }
.eh2-day{
  width:32px; height:32px; line-height:32px; text-align:center; border-radius:8px; cursor:pointer;
  user-select:none; font:13px Arial; color:#0f172a; transition:background .15s ease;
}
/* đổi light pink */
.eh2-day:hover{ background:#fde2de; }
.eh2-day.out{ opacity:.35; cursor:default; }
.eh2-day.in{ background:#fde2de; }
/* đổi #EC407A -> #ED1C24 */
.eh2-day.sel{ background:#ED1C24; color:#fff; }
/* đổi #E91E63 -> #ED1C24 */
.eh2-day.edge{ background:#ED1C24; color:#fff; }

.eh2-quick{ display:flex; gap:8px; align-items:center; margin-top:6px; }
.eh2-btn{ padding:8px 12px; border-radius:10px; border:1px solid #e2e8f0; background:#f8fafc; cursor:pointer; }
.eh2-btn.ghost{ background:#fff; }
/* đổi #E91E63 -> #ED1C24 */
.eh2-btn.primary{ background:#ED1C24; color:#fff; border-color:#ED1C24; }
.eh2-modal-actions{ display:flex; justify-content:flex-end; gap:10px; margin-top:10px; }
#eh2-main {
  gap: 0.5px; /* Giảm khoảng cách giữa heatmap và legend */
}

descriptor.controllerScript:
// energy-heatmap.js  (FULL + FIX: listen device switch, loading overlay,
//                     supports SINGLE (subscription) + ALL (fetch & sum),
//                     range chips work, legend works, y-axis not overlap)

(function () {
/*************** STATE & CONST ***************/
var heatmapCanvas, heatmapCtx;
var lastHeatmapMap = null;

var startMs = null, endMs = null;     // range đang áp dụng
var yDays = 7;

var hourMode = '10h';                 // '10h' | '24h'
var currentMode = 'custom';           // 'custom' local range (chips/modal)

var PAD_HM = { L: 98, T: 34, R: 20, B: 22 };
var LEVEL_COUNT = 5;

var domainMax = 0;
var BINS = [];

// Guards (stale render / fetch)
var __fetchSeq = 0;
var __renderSeq = 0;

// For listening device switch (polling signature)
var __pollTimer = null;
var __lastSig = null;
var __lastEntitySig = null;

// DOM ids (phải khớp template HTML của widget)
var ids = {
  main:'eh2-main', canvas:'eh2-canvas',
  header:'eh2-header', rangeGroup:'eh2-range-group',
  hourGroup:'eh2-hour-mode-group',
  legend:'eh2-legend', tooltip:'eh2-tooltip',
  keyWrap:'eh2-key-wrap', keySelect:'eh2-key-select',
  // modal
  overlay:'eh2-range-overlay',
  prevL:'eh2-prevL', nextL:'eh2-nextL', titleL:'eh2-titleL', gridL:'eh2-gridL',
  prevR:'eh2-prevR', nextR:'eh2-nextR', titleR:'eh2-titleR', gridR:'eh2-gridR',
  close:'eh2-close', cancel:'eh2-cancel', apply:'eh2-apply',
  quickWeek:'eh2-week-cur', quickMonth:'eh2-month-cur'
};

/*************** PALETTE & HELPERS ***************/
var NO_DATA_COLOR = '#eeeeee';
var COLORS_GREEN   = ['#F1FFF6','#C9F5DB','#7EE2A8','#2FB463','#0B4A2A'];
var COLORS_BLUE    = ['#FBEAEA', '#F2BDBD', '#E47D7D', '#CD5C5C', '#6B1F1F'];
var COLORS_YELLOW  = ['#FFF9E5','#FFE7A9','#FFD166','#FFB020','#7A4E00'];

var selectedKeyId = null, dataKeyList = [];

function getPaletteForSelectedKey(){
  var idx = 0;
  for (var i=0;i<dataKeyList.length;i++){
    if(String(dataKeyList[i].id)===String(selectedKeyId)){ idx=i; break; }
  }
  return [COLORS_BLUE, COLORS_GREEN, COLORS_YELLOW][idx % 3];
}

var MS = { day: 86400000 };
function startOfDay(d){ var x=new Date(d); x.setHours(0,0,0,0); return x; }
function endOfDay(d){ var x=new Date(d); x.setHours(23,59,59,999); return x; }
function clamp(v,a,b){ return Math.max(a, Math.min(b, v)); }
function getEl(id){ return document.getElementById(id); }
function getCardEl(){
  try{
    if(self && self.ctx && self.ctx.$container && self.ctx.$container[0]) return self.ctx.$container[0];
  }catch(_){}
  return document.body;
}
function buildDaysCount(){
  var a = startOfDay(startMs).getTime(), b = startOfDay(endMs).getTime();
  yDays = clamp(Math.floor((b - a)/MS.day) + 1, 1, 366);
}
function ymd(d){ return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0'); }
function dayIndexOf(ts){
  return Math.floor((startOfDay(ts).getTime() - startOfDay(startMs).getTime()) / MS.day);
}

/*************** ThingsBoard state helpers (ALL/SINGLE) ***************/
function safeGetToken() {
  try { return localStorage.getItem('jwt_token') || localStorage.getItem('token') || ''; } catch(_) { return ''; }
}
function extractDeviceId(ent) {
  if (!ent) return null;
  if (typeof ent === 'string') return ent;
  if (typeof ent.id === 'string') return ent.id;
  if (ent.id && typeof ent.id.id === 'string') return ent.id.id;
  return null;
}
function dedupe(arr) {
  var out=[], set=new Set();
  (arr||[]).forEach(function(x){
    var v=String(x||'').trim();
    if(v && !set.has(v)){ set.add(v); out.push(v); }
  });
  return out;
}
function readStateParams() {
  var sc = self.ctx && self.ctx.stateController;
  if (!sc) return {};
  try { var p = sc.getStateParams(); if (p && typeof p === 'object') return p; } catch(_){}
  try { var p2 = sc.getStateParams('default'); if (p2 && typeof p2 === 'object') return p2; } catch(_){}
  return {};
}
function getAllDeviceIdsFromState(stateParams) {
  var list = stateParams.entities || stateParams.entityIds || [];
  var idsArr = [];
  if (Array.isArray(list)) list.forEach(function(e){ var id=extractDeviceId(e); if(id) idsArr.push(id); });
  else { var id2=extractDeviceId(list); if(id2) idsArr.push(id2); }
  return dedupe(idsArr);
}
function getSelectedMode(stateParams) {
  // bạn có thể đổi key này theo state của dashboard của bạn
  var m = stateParams.selectedDeviceMode || stateParams.mode;
  return m === 'ALL' ? 'ALL' : 'SINGLE';
}

// Try to read current SINGLE device id from ctx datasources (more reliable than state sometimes)
function getCurrentSingleEntityIdFromCtx() {
  try {
    var ds = self.ctx && (self.ctx.datasources || self.ctx.dataSources || self.ctx.dataSource);
    // TB thường là array
    if (Array.isArray(ds) && ds.length) {
      var e = ds[0].entity || ds[0].entityId || ds[0].entityID;
      var id = extractDeviceId(e) || extractDeviceId(ds[0].entityId) || extractDeviceId(ds[0].entityID);
      if (id) return id;
    }
  } catch(_) {}
  return null;
}

/*************** BINS & COLORS ***************/
function buildDiscreteBinsZeroToMax(max, levels){
  max = Math.max(0, Math.ceil(isFinite(max) ? max : 0));
  var bins = [];
  if (levels <= 1) { bins.push({ from:0, to:max, level:0 }); return bins; }
  var total = max + 1;
  var base = Math.floor(total/levels);
  var extra = total%levels;
  var start = 0;
  for (var i=0;i<levels;i++){
    var len = base + (i<extra?1:0);
    var end = i<levels-1 ? (start+len-1) : max;
    if (len<=0) end = start-1;
    bins.push({from:start,to:end,level:i});
    start = end+1;
  }
  return bins;
}
function hexToRgb(hex){
  var h=hex.replace('#','');
  if(h.length===3) h=h.split('').map(x=>x+x).join('');
  var n=parseInt(h,16);
  return {r:(n>>16)&255,g:(n>>8)&255,b:n&255};
}
function luminance(r,g,b){
  function s(u){u/=255; return u<=0.03928?u/12.92:Math.pow((u+0.055)/1.055,2.4);}
  var R=s(r),G=s(g),B=s(b);
  return 0.2126*R+0.7152*G+0.0722*B;
}
function levelColor(val, hasData, max, PALETTE){
  if (!hasData || !isFinite(val)) return { css: NO_DATA_COLOR, level: -1, lum: 1 };
  var dMax = Math.max(0, Math.ceil(max));
  if (!BINS.length || BINS[BINS.length-1].to !== dMax) BINS = buildDiscreteBinsZeroToMax(dMax, LEVEL_COUNT);
  var vInt = Math.floor(Math.max(0,val)+1e-9); if (vInt>dMax) vInt=dMax;
  var lvl=0;
  for (var i=0;i<BINS.length;i++){
    var b=BINS[i];
    if(vInt>=b.from && vInt<=b.to){ lvl=b.level; break; }
  }
  var rgb=hexToRgb(PALETTE[lvl]);
  return { css: PALETTE[lvl], level:lvl, lum:luminance(rgb.r,rgb.g,rgb.b) };
}

