    if (t === 'male' || t === 'm' || t === 'nam' || t === '1' || t === 'true') return 'male';
    if (t === 'female' || t === 'f' || t === 'nu' || t === 'nữ' || t === '0' || t === 'false') return 'female';
    if (t.indexOf('m') === 0) return 'male';
    if (t.indexOf('f') === 0) return 'female';
