descriptor.templateCss:
/* ===== Container ===== */
.store-cam-widget {
  width: 100%;
  height: 100%;
  padding: 12px;
  background: #fff;
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  font-size: clamp(11px, min(2vw, 3vh), 15px);
  color: #111827;
}

/* ===== Row: 3 dropdown cùng hàng ===== */
.selector-row {
  display: flex;
  gap: 12px;
  width: 100%;
  align-items: flex-start;
}

/* ===== Fields ===== */
.form-field {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

/* Bạn có thể chỉnh tỉ lệ ở đây */
.store-field { flex: 3; }
.device-field { flex: 5; }
.cam-field { flex: 3; }

/* ===== Label (có thanh đỏ) ===== */
.field-label {
  display: flex;
  align-items: center;
  font-size: 0.75em;
  font-weight: 700;
  color: #111827;
  margin-bottom: 6px;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.field-label::before {
  content: '';
  display: inline-block;
  width: 3px;
  height: 14px;
  background: linear-gradient(180deg, #ED1C24 0%, #c91820 100%);
  border-radius: 2px;
  margin-right: 8px;
  flex-shrink: 0;
}

/* ===== Select wrapper ===== */
.select-wrapper {
  position: relative;
  width: 100%;
  min-height: 36px;
  max-height: 48px;
  background: #ffffff;
  border: 2px solid #E5E7EB;
  border-radius: 6px;
  display: flex;
  align-items: center;
  transition: border-color 0.2s ease;
}

.select-wrapper:hover { border-color: #D1D5DB; }
.select-wrapper:focus-within { border-color: #ED1C24; }

/* Select */
.mat-select {
  width: 100%;
  height: 100%;
  padding: 0 34px 0 12px;
  font-size: 1em;
  font-weight: 600;
  color: #111827;
  background: transparent;
  border: none;
  outline: none;
  cursor: pointer;
  appearance: none;
  -webkit-appearance: none;
  -moz-appearance: none;
  line-height: 1.5;
}

/* Arrow đỏ */
.select-wrapper::after {
  content: '';
  position: absolute;
  right: 10px;
  top: 50%;
  transform: translateY(-50%);
  width: 16px;
  height: 16px;
  background: linear-gradient(135deg, #ED1C24 0%, #c91820 100%);
  mask-image: url("data:image/svg+xml,%3Csvg width='20' height='20' viewBox='0 0 20 20' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M5 7.5L10 12.5L15 7.5' stroke='black' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'/%3E%3C/svg%3E");
  mask-repeat: no-repeat;
  mask-position: center;
  mask-size: contain;
  -webkit-mask-image: url("data:image/svg+xml,%3Csvg width='20' height='20' viewBox='0 0 20 20' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M5 7.5L10 12.5L15 7.5' stroke='black' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'/%3E%3C/svg%3E");
  -webkit-mask-repeat: no-repeat;
  -webkit-mask-position: center;
  -webkit-mask-size: contain;
  pointer-events: none;
  opacity: 0.9;
}

.mat-select option {
  color: #111827;
  background: #fff;
}

/* Disabled */
.mat-select:disabled {
  color: #9CA3AF;
  cursor: not-allowed;
  opacity: 0.7;
}

/* ===== Tablet mode: ẩn camera "như không tồn tại" nhưng GIỮ CHỖ ===== */
.store-cam-widget.tablet-mode .cam-field {
  opacity: 0;            /* không thấy */
  pointer-events: none;  /* không click */
  user-select: none;
}

.store-cam-widget.tablet-mode .cam-field .select-wrapper {
  border-color: transparent;
  background: transparent;
}

.store-cam-widget.tablet-mode .cam-field .select-wrapper::after {
  opacity: 0;
}

.store-cam-widget.tablet-mode .cam-field .mat-select {
  color: transparent;
}

/* Responsive */
@media (max-width: 600px) {
  .selector-row {
    flex-direction: column;
    gap: 8px;
  }
  .store-field, .device-field, .cam-field {
    flex: auto;
    width: 100%;
  }
}

