(function ensureCamBus() {
  var topWin = window.top || window;
  if (topWin.__TB_CAM_BUS__) return;

  topWin.__TB_CAM_BUS__ = {
    last: null,
    _listeners: [],
    emit: function (camName) {
      this.last = camName;
      var payload = { cam: camName, ts: Date.now() };
      this._listeners.forEach(function (fn) { try { fn(payload); } catch (e) {} });
    },
    on: function (fn) { if (typeof fn === "function") this._listeners.push(fn); },
    off: function (fn) { this._listeners = this._listeners.filter(function (x) { return x !== fn; }); }
  };
})();

let seq = 0;

self.onInit = function () {
  self.rootEl = self.ctx.$container[0].querySelector('.store-cam-widget') || self.ctx.$container[0];

  self.typeSelect = document.getElementById('typeSelect');
  self.deviceSelect = document.getElementById('deviceSelect');
  self.camSelect = document.getElementById('camSelect');
  self.statusEl = document.getElementById('status');

  initServices();

  // events
  self.typeSelect.addEventListener('change', async () => {
    await loadDevicesByType(self.typeSelect.value);
    persistSelection(); // updates stateController
    await onDeviceChanged(); // auto load cam for first device
  });

  self.deviceSelect.addEventListener('change', async () => {
    persistSelection();
    await onDeviceChanged();
  });

  self.camSelect.addEventListener('change', async () => {
    const cam = self.camSelect.value;
    if (!cam) return;
    await setSelectedCamUI(cam);              // đảm bảo UI đúng ngay
    await saveCurrentCam(cam, true);          // save SERVER_SCOPE + emit bus
  });

  init();
};

self.onDestroy = function () {};
self.onDataUpdated = function () {
  // ❌ KHÔNG build camOptions từ ctx.data để tránh dính device cũ
};
self.onResize = function () {};

/* ---------------- services ---------------- */

function initServices() {
  const inj = self.ctx.$scope.$injector;
  self.attributeService = inj.get(self.ctx.servicesMap.get("attributeService"));

  // telemetryService (nếu có)
  self.telemetryService = null;
  try {
    const tToken =
      (self.ctx.servicesMap && self.ctx.servicesMap.get && (
        self.ctx.servicesMap.get("telemetryService") ||
        self.ctx.servicesMap.get("telemetry")
      )) || null;
    if (tToken) self.telemetryService = inj.get(tToken);
  } catch (e) {
    self.telemetryService = null;
  }

  self.telemetryKey = self.ctx.settings.telemetryKey || "pass_cam";
  self.serverAttrKey = "current_cam";
  self.deviceLabelKey = "deviceLabel";
}

/* ---------------- helpers ---------------- */

function setStatus(msg) {
  if (self.statusEl) self.statusEl.textContent = msg || '';
}

function setTabletMode(on) {
  try { self.rootEl.classList.toggle('tablet-mode', !!on); } catch (e) {}
}

function fillSelect(selectEl, items, placeholder) {
  selectEl.innerHTML = '';
  if (placeholder) {
    const ph = document.createElement('option');
    ph.value = '';
    ph.textContent = placeholder;
    selectEl.appendChild(ph);
  }
  (items || []).forEach(it => {
    const opt = document.createElement('option');
    opt.value = it.value;
    opt.textContent = it.label;
    selectEl.appendChild(opt);
  });
}

function setCamLoading(msg) {
  self.camSelect.innerHTML = '';
  const opt = document.createElement('option');
  opt.value = '';
  opt.textContent = msg || 'Loading cameras...';
  self.camSelect.appendChild(opt);
  self.camSelect.value = '';
  self.camSelect.disabled = true;
}

async function setSelectedCamUI(cam) {
  // ✅ quan trọng: UI phải set lại value sau khi options được build
  try {
    self.camSelect.value = cam;
  } catch (e) {}
}

/* ---------------- token + api ---------------- */

function getToken() {
  const jwtToken = localStorage.getItem('jwt_token');
  const token = localStorage.getItem('token');
  return jwtToken || token || '';
}

async function apiGet(url) {
  const token = getToken();
  const res = await fetch(url, {
    method: 'GET',
    headers: {
      'Content-Type': 'application/json',
      ...(token ? { 'X-Authorization': 'Bearer ' + token } : {})
    }
  });
  if (!res.ok) {
    const txt = await res.text();
    throw new Error(`HTTP ${res.status} GET ${url}: ${txt}`);
  }
  return res.json();
}

/* ---------------- store/type + device ---------------- */

async function fetchDeviceTypes() {
  const user = self.ctx.currentUser;

  if (user && user.authority === 'CUSTOMER_USER') {
    const customerId = (user.customerId && user.customerId.id) ? user.customerId.id : user.customerId;
    if (!customerId) return [];
    const r = await apiGet(`/api/customer/${customerId}/deviceInfos?pageSize=1000&page=0`);
    const data = r.data || [];
    return [...new Set(data.map(d => d.type))].filter(Boolean).sort();
  }

  const r = await apiGet('/api/device/types');
  let types = Array.isArray(r) ? r : (r.deviceTypes || []);
  if (types.length && typeof types[0] === 'object') {
    types = types.map(t => t.type || t.name || t.deviceType || t.label || JSON.stringify(t));
  }
  return types;
}

async function fetchDevices(deviceType) {
  const user = self.ctx.currentUser;
  let url;

  if (user && user.authority === 'CUSTOMER_USER') {
    const customerId = (user.customerId && user.customerId.id) ? user.customerId.id : user.customerId;
    if (!customerId) throw new Error('Customer ID not found');
    url = `/api/customer/${customerId}/deviceInfos?pageSize=100&page=0&type=${encodeURIComponent(deviceType)}`;
  } else {
    url = `/api/tenant/deviceInfos?pageSize=100&page=0&type=${encodeURIComponent(deviceType)}`;
  }

  const r = await apiGet(url);
  const data = r.data || [];
  return data
    .filter(x => x.type === deviceType)
    .map(x => ({ id: (x.id && (x.id.id || x.id)) || x.id, name: x.name || x.label || '(unnamed)' }));
}

async function init() {
  setStatus('Loading store types...');
  try {
    const types = await fetchDeviceTypes();
    fillSelect(self.typeSelect, types.map(t => ({ value: t, label: t })), null);
    setStatus('');

    const saved = restoreSelection();
    if (saved && saved.deviceType && types.includes(saved.deviceType)) {
      self.typeSelect.value = saved.deviceType;
      await loadDevicesByType(saved.deviceType);

      if (saved.deviceId) self.deviceSelect.value = saved.deviceId;
      persistSelection();
      await onDeviceChanged();
      return;
    }

    if (types.length) {
      self.typeSelect.value = types[0];
      await loadDevicesByType(types[0]);
      persistSelection();
      await onDeviceChanged();
    } else {
      setStatus('No store types');
    }
  } catch (e) {
    setStatus('Error: ' + e.message);
  }
}

async function loadDevicesByType(type) {
  if (!type) {
    fillSelect(self.deviceSelect, [], 'Select store first');
    return;
  }
  setStatus('Loading devices...');
  try {
    const devices = await fetchDevices(type);
    self.currentDevices = devices;

    // ✅ BỎ ALL DEVICES
    fillSelect(self.deviceSelect, devices.map(d => ({ value: d.id, label: d.name })), null);

    self.deviceSelect.value = devices[0]?.id || '';
    setStatus('');
  } catch (e) {
    setStatus('Error loading devices: ' + e.message);
    fillSelect(self.deviceSelect, [], 'Select store first');
  }
}

/* ---------------- device change -> camera logic ---------------- */

async function onDeviceChanged() {
  const deviceId = self.deviceSelect.value;
  if (!deviceId) {
    setTabletMode(false);
    setCamLoading('Select device');
    return;
  }

  const curSeq = ++seq;

  // Clear cam UI ngay lập tức
  setCamLoading('Loading cameras...');

  // 1) đọc deviceLabel + current_cam (SERVER_SCOPE)
  let deviceLabel = null;
  let currentCam = null;
  try {
    const url = `/api/plugins/telemetry/DEVICE/${deviceId}/values/attributes/SERVER_SCOPE?keys=${encodeURIComponent(self.deviceLabelKey)},${encodeURIComponent(self.serverAttrKey)}`;
    const r = await apiGet(url);
    const arr = r.data || r;

    if (Array.isArray(arr)) {
      const m = {};
      arr.forEach(it => { if (it && it.key != null) m[it.key] = it.value; });
      deviceLabel = m[self.deviceLabelKey] != null ? String(m[self.deviceLabelKey]) : null;
      currentCam = m[self.serverAttrKey] != null ? String(m[self.serverAttrKey]) : null;
    }
  } catch (e) {}

  if (curSeq !== seq) return;

  // 2) tablet-type: ẩn camera (giữ chỗ), không load telemetry
  if (String(deviceLabel || '').trim() === 'tablet-type') {
    setTabletMode(true);
    // camera field “ẩn” bằng CSS, nhưng vẫn clear data để không dính
    setCamLoading(''); // không quan trọng vì bị ẩn
    return;
  }

  // 3) edge/default: show camera
  setTabletMode(false);

  // 4) đọc latest pass_cam
  const options = await fetchLatestPassCam(deviceId);
  if (curSeq !== seq) return;

  if (!options.length) {
    setCamLoading('No cameras');
    return;
  }

  // 5) build options vào dropdown (enable)
  self.camSelect.innerHTML = '';
  options.forEach(cam => {
    const opt = document.createElement('option');
    opt.value = cam;
    opt.textContent = cam;
    self.camSelect.appendChild(opt);
  });
  self.camSelect.disabled = false;

  // 6) chọn theo current_cam nếu hợp lệ, không thì chọn cam đầu
  const sel = (currentCam && options.includes(currentCam)) ? currentCam : options[0];
  await setSelectedCamUI(sel);

  // 7) nếu current_cam không tồn tại/khác -> save lại, còn đúng thì emit bus
  if (!currentCam || currentCam !== sel) {
    await saveCurrentCam(sel, true, deviceId);
  } else {
    emitBus(sel);
  }
}

/* ---------------- telemetry: latest pass_cam ---------------- */

async function fetchLatestPassCam(deviceId) {
  // ưu tiên telemetryService.getLatestTimeseries
  const entityIdObj = { entityType: 'DEVICE', id: deviceId };

  try {
    if (self.telemetryService && self.telemetryService.getLatestTimeseries) {
      const data = await toPromise(self.telemetryService.getLatestTimeseries(entityIdObj, [self.telemetryKey]));
      const arr = data && data[self.telemetryKey];
      const raw = (arr && arr.length) ? arr[0].value : null;
      return parseCamOptions(raw);
    }
  } catch (e) {}

  // fallback REST
  try {
    const key = encodeURIComponent(self.telemetryKey);
    const url = `/api/plugins/telemetry/DEVICE/${deviceId}/values/timeseries?keys=${key}&limit=1`;
    const r = await apiGet(url);
    const data = r.data || r;
    const arr = data && data[self.telemetryKey];
    const raw = (arr && arr.length) ? arr[0].value : null;
    return parseCamOptions(raw);
  } catch (e) {
    return [];
  }
}

function parseCamOptions(raw) {
  if (raw == null) return [];
  let obj;
  try { obj = (typeof raw === "string") ? JSON.parse(raw) : raw; }
  catch (e) { return []; }
  if (!obj || typeof obj !== "object") return [];
  return Object.keys(obj)
    .sort((a, b) => (parseInt(a, 10) || 0) - (parseInt(b, 10) || 0))
    .map(k => `CAM_${k}`);
}

/* ---------------- save current_cam + bus ---------------- */

async function saveCurrentCam(camName, shouldEmit, deviceIdOverride) {
  const deviceId = deviceIdOverride || self.deviceSelect.value;
  if (!deviceId || !camName) return;

  try {
    await toPromise(
      self.attributeService.saveEntityAttributes(
        { entityType: 'DEVICE', id: deviceId },
        "SERVER_SCOPE",
        [{ key: self.serverAttrKey, value: camName }]
      )
    );
  } catch (e) {
    // ignore save fail, vẫn emit để sync UI
  }

  if (shouldEmit) emitBus(camName);
}

function emitBus(camName) {
  try {
    var bus = (window.top || window).__TB_CAM_BUS__;
    if (bus && bus.emit) bus.emit(camName);
  } catch (e) {}
}

/* ---------------- rxjs helper ---------------- */

function toPromise(obs) {
  return new Promise((resolve, reject) => {
    try {
      obs.subscribe(resolve, reject);
    } catch (e) {
      reject(e);
    }
  });
}

/* ---------------- localStorage + stateController ---------------- */

const STORAGE_KEY = 'store_type_selection';

function saveSelection(type, deviceId, deviceName) {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify({
      deviceType: type,
      deviceId: deviceId,
      deviceName: deviceName,
      timestamp: Date.now()
    }));
  } catch (e) {}
}

function restoreSelection() {
  try {
    const s = localStorage.getItem(STORAGE_KEY);
    return s ? JSON.parse(s) : null;
  } catch (e) { return null; }
}

function persistSelection() {
  const selectedType = self.typeSelect?.value || '';
  const selectedDeviceId = self.deviceSelect?.value || '';
  const selectedDeviceName =
    self.deviceSelect?.options?.[self.deviceSelect.selectedIndex]?.text || '';

  // update stateController (single device)
  try {
    if (self.ctx && self.ctx.stateController) {
      const stateParams = {
        entityType: selectedDeviceId ? 'DEVICE' : null,
        id: selectedDeviceId || null,
        entityId: selectedDeviceId ? { entityType: 'DEVICE', id: selectedDeviceId } : null,
        name: selectedDeviceName || null,
        label: selectedDeviceName || null,

        selectedDeviceMode: selectedDeviceId ? 'SINGLE' : 'NONE',
        selectedDeviceType: selectedType || null,
        selectedDeviceId: selectedDeviceId || null,
        selectedDeviceName: selectedDeviceName || null,

        mode: selectedDeviceId ? 'SINGLE' : 'NONE',
        type: selectedType || null
      };
      self.ctx.stateController.updateState(null, stateParams, true);
    }
  } catch (e) {}

  saveSelection(selectedType, selectedDeviceId, selectedDeviceName);
}

